INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "离说话的人比较远的那一边。", "primary_collocate": null, "pronunciation": "nà biān", "ipa": "nɑ˥˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "我在这边，你在那边。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那边比这边安静。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门在那边，不在这边。", "target_word": "那边", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这边没有人，那边有很多人。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河这边是村子，河那边是山。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那边的天气比这边冷得多。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你走那边，我走这边，我们在前面见。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那边的孩子正在唱歌，这边的孩子在听。", "target_word": "那边", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把椅子搬到那边去。", "target_word": "那边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指着那边说：“你看，那就是我家。”", "target_word": "那边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "那边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "与「这边」相对，指离说话人较远的一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c28d83a-6b09-4f23-ba3e-738046e27c83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那边", "is_correct": true, "explanation": "正确。「那边」与前句的「这边」相对，指离说话人较远的一侧。"}, {"text": "谁", "is_correct": false, "explanation": "语义：「谁」是疑问代词，不指处所，不能作「在」的处所。"}, {"text": "那个", "is_correct": false, "explanation": "语义：「那个」指物，不指处所，不能作「在」的处所。"}, {"text": "那些", "is_correct": false, "explanation": "配价：「那些」是限定词，后面必须接名词，不能单独作「在」的处所。"}], "explanations": {"那边": "正确。「那边」与前句的「这边」相对，指离说话人较远的一侧。", "谁": "语义：「谁」是疑问代词，不指处所，不能作「在」的处所。", "那个": "语义：「那个」指物，不指处所，不能作「在」的处所。", "那些": "配价：「那些」是限定词，后面必须接名词，不能单独作「在」的处所。"}, "sentence_index": 0, "correct_answer": "那边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那边他刚来这个城市。", "explanation": "这里应该用〈那时〉。那边指地方，不能表示时间，表示当时要用「那时」。"}, {"text": "他把那边读完了。", "explanation": "这里应该用〈书〉。那边指地方，不能作「读」的对象，应说把书读完了。"}, {"text": "他把那边关上了。", "explanation": "这里应该用〈门〉。那边指地方，不能作「关上」的对象，应说把门关上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那边", "is_correct": true, "explanation": "正确。「那边」指较远的地方，「走那边」与「我走这边」相对，符合语境。"}, {"text": "这个", "is_correct": false, "explanation": "语义：「这个」指物，不能作「走」的目标。"}, {"text": "它", "is_correct": false, "explanation": "配价：「走」需要处所或方向作宾语，「它」是指物代词，不能充当。"}, {"text": "她", "is_correct": false, "explanation": "配价：「走」后接的是处所，不能直接接人称代词「她」，应说「去她那里」。"}], "explanations": {"那边": "正确。「那边」指较远的地方，「走那边」与「我走这边」相对，符合语境。", "这个": "语义：「这个」指物，不能作「走」的目标。", "它": "配价：「走」需要处所或方向作宾语，「它」是指物代词，不能充当。", "她": "配价：「走」后接的是处所，不能直接接人称代词「她」，应说「去她那里」。"}, "sentence_index": 6, "correct_answer": "那边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那边吃完了。", "explanation": "这里应该用〈饭〉。那边指地方，不能作「吃完」的对象，应说把饭吃完。"}, {"text": "他把那边搬走了。", "explanation": "这里应该用〈书〉之类的物件名词。那边是地方，不能作「搬」的对象。"}, {"text": "他跑得那边快。", "explanation": "这里应该用〈那么〉。「那么」表示程度，那边只指地方，不能用来修饰动词的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他那边等你。", "corrected_sentence": "他在那边等你。", "error_description": "错误：「他那边等你」漏掉了介词「在」。正确：「他在那边等你」。表示动作发生的处所要用「在」引出，「那边」前不能直接接动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家坐往那边去。", "corrected_sentence": "请大家坐到那边去。", "error_description": "错误：「坐往那边去」中「往」不能直接接在动词「坐」之后。正确：「坐到那边去」。「坐」后表示到达某处要用「到」引出；也可以改为「往那边坐」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
