INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门的前面，进出的地方。", "primary_collocate": null, "pronunciation": "mén kǒu", "ipa": "mən kʰou", "syllable_count": 2, "sentences": [{"text": "我在学校门口等你。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一位老人。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鞋放在门口。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司门口有一家小饭店。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家门口等着我回家。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院门口排着长队。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把车停在门口。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们跑到门口迎接爸爸。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的那棵树很高。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在门口，没有进来。", "target_word": "门口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "門口", "label": "繁体"}, {"form": "家门口", "label": "复合"}, {"form": "校门口", "label": "复合"}], "register": "口语", "sense_fingerprint": "门前面的地方，人站立、等候或停放物品的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c28d83a-6b09-4f23-ba3e-738046e27c83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不是可以等人的地点，“在学校时间等你”不通。"}, {"text": "学期", "is_correct": false, "explanation": "语义：“学期”是一段时间，不是等人的地方，与“等你”的地点语境冲突。"}, {"text": "门口", "is_correct": true, "explanation": "“门口”是地点名词，与“在学校……等你”的语境相符。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不是等人的地点，句子荒谬。"}], "explanations": {"时间": "搭配：“时间”不是可以等人的地点，“在学校时间等你”不通。", "学期": "语义：“学期”是一段时间，不是等人的地方，与“等你”的地点语境冲突。", "门口": "“门口”是地点名词，与“在学校……等你”的语境相符。", "书包": "语义：“书包”是物品，不是等人的地点，句子荒谬。"}, "sentence_index": 0, "correct_answer": "门口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门口很结实。", "explanation": "这里应该用〈大门〉。“门口”指门前一带的位置，不能说它结实，说门本身的性质要用“大门”。"}, {"text": "我家门口号码是三十二号。", "explanation": "这里应该用〈门牌〉。“门口”是位置，写门号的是“门牌”，不能说门口号码。"}, {"text": "门口断了，门关不上。", "explanation": "这里应该用〈门闩〉。“门口”是位置，不会断；断的是门闩，所以门关不上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：车不能停在天空中，句子荒谬。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“停”不能用于饭菜，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：车辆一般不会停在厨房里，与“不要把车停在”的语境冲突。"}, {"text": "门口", "is_correct": true, "explanation": "“门口”是可以停车的地点，与“请不要把车停在”的语境相符。"}], "explanations": {"天空": "语义：车不能停在天空中，句子荒谬。", "饭菜": "搭配：“停”不能用于饭菜，句子不通。", "厨房": "语义：车辆一般不会停在厨房里，与“不要把车停在”的语境冲突。", "门口": "“门口”是可以停车的地点，与“请不要把车停在”的语境相符。"}, "sentence_index": 6, "correct_answer": "门口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一只手握住门口，把门推开了。", "explanation": "这里应该用〈门把手〉。“门口”是位置，不能握住；握的是“门把手”。"}, {"text": "孩子把门口摔坏了，爸爸很生气。", "explanation": "这里应该用〈门板〉。“门口”是位置，被摔坏的是门板，不能说门口摔坏。"}, {"text": "门口被换了，屋里更安全了。", "explanation": "这里应该用〈门锁〉。“门口”是位置，被换的是门锁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校门口见面吧。", "corrected_sentence": "我们在学校门口见面吧。", "error_description": "错误：缺少介词“在”，“学校门口”被误读为句子主语。正确：“在学校门口”，“在”引出处所。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们跑在门口迎接客人。", "corrected_sentence": "孩子们跑到门口迎接客人。", "error_description": "错误：“跑在门口”介词用错。正确：“跑到门口”。表示移动到某处要用介词“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
