INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90039, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "自身是自己,不是别人。", "primary_collocate": null, "pronunciation": "zì shēn", "ipa": "tsɿ˥˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他很少想到自身的安全。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到火灾,先要保护好自身安全。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只关心自身的利益,不管别人。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生也要先照顾好自身,才能帮助病人。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要总是看别人,先想想自身的问题。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从不为自身的事麻烦别人。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子能很好地管理自身的时间。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他救了别人,却忘了自身的危险。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都应该为自身的行为负责。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作再忙,也要注意自身的健康。", "target_word": "自身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自身:指人自己,与别人相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36c33a4a-e234-4e15-897c-30965f67ead3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "正确：“自身”指他自己，与别人相对，与“很少想到”的语境相合。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物，与句中指人的“他”不一致，“想到它的安全”不通。"}, {"text": "本身", "is_correct": false, "explanation": "搭配：“本身”多用于事物自身，不说想到本身的安全。"}, {"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”指双方互相，与“他很少想到”的只顾自己的语境不合。"}], "explanations": {"自身": "正确：“自身”指他自己，与别人相对，与“很少想到”的语境相合。", "它": "语义：“它”指事物，与句中指人的“他”不一致，“想到它的安全”不通。", "本身": "搭配：“本身”多用于事物自身，不说想到本身的安全。", "彼此": "搭配：“彼此”指双方互相，与“他很少想到”的只顾自己的语境不合。"}, "sentence_index": 0, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我请自身的父母来参加婚礼。", "explanation": "这里“自身”只指自己而不指别人，不能修饰“父母”这类他人，应说“自己的父母”。"}, {"text": "这个问题自身很难，需要大家一起想办法。", "explanation": "这里“自身”指事物本身，不是指人自己，属于另一个义项，不符合本义的用法。"}, {"text": "他的自身很强壮，不需要别人照顾。", "explanation": "这里“自身”不能用来形容身体，要说“身体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自身", "is_correct": true, "explanation": "正确：“自身”指这个孩子自己，与“管理自己的时间”的语境相合。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”指别人，句子说的是这个孩子管理自己的时间，不合语境。"}, {"text": "同桌", "is_correct": false, "explanation": "语义：“同桌”是另一个人，不说这个孩子管理同桌的时间。"}, {"text": "对方", "is_correct": false, "explanation": "搭配：“对方”多指谈判或竞争的另一方，不说管理对方的时间。"}], "explanations": {"自身": "正确：“自身”指这个孩子自己，与“管理自己的时间”的语境相合。", "老板": "语义：“老板”指别人，句子说的是这个孩子管理自己的时间，不合语境。", "同桌": "语义：“同桌”是另一个人，不说这个孩子管理同桌的时间。", "对方": "搭配：“对方”多指谈判或竞争的另一方，不说管理对方的时间。"}, "sentence_index": 6, "correct_answer": "自身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告自身的内容很全面。", "explanation": "这里“自身”修饰“报告”这类事物，表示事物本身，不指人自己，与本义不同。"}, {"text": "他总是和自身的同学一起玩。", "explanation": "这里“自身”不能修饰表示其他人的名词“同学”，它只指自己。"}, {"text": "这个人很自身，不喜欢和别人交流。", "explanation": "这里“自身”是名词，不能形容人的性格，应说“孤僻”或“自私”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是先顾好自身地安全，再考虑别人。", "corrected_sentence": "他总是先顾好自身的安全，再考虑别人。", "error_description": "错误：修饰名词“安全”的结构助词写成了“地”。“地”用于修饰动词或形容词，修饰名词应用“的”，正确应为“自身的安全”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都很照顾自身们，不给别人添麻烦。", "corrected_sentence": "大家都很照顾自身，不给别人添麻烦。", "error_description": "错误：“自身”后面不能加“们”。正确应为“自身”，它单独使用，不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
