INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90041, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在门口等了的一会儿，就进去了。", "corrected_sentence": "他在门口等了一会儿，就进去了。", "error_description": "错误：“一会儿”前不能插入结构助词“的”，“了”应直接接在动词后。应说“等了一会儿”，不能说“等了的一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
