INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物业是管理一个小区的房子和环境的工作。", "primary_collocate": null, "pronunciation": "wù yè", "ipa": "u⁵¹ jɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "我们小区的物业很负责，楼道每天都打扫。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，请你给物业打个电话。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物业说，下周六要检查电梯。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区新换了物业，门口干净多了。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上太吵了，邻居去找物业帮忙。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物业每个月都会检查一次消防设备。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在小区的物业工作，每天修灯修门。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对现在的物业不太满意，想换一家。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车的事，你可以问一下物业。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的物业能让小区更安全，也更干净。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物业费", "label": "复合"}, {"form": "物业公司", "label": "复合"}, {"form": "物业管理", "label": "复合"}], "register": "中性", "sense_fingerprint": "小区房屋与环境的管理服务工作(名词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede64bf9-61fe-41ae-8fa2-9847150bb0ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90043, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指负责管理小区房屋与环境的服务工作。"}, {"text": "无业", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。"}, {"text": "午夜", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。"}, {"text": "树叶", "is_correct": false, "explanation": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。"}, {"text": "副业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}], "explanations": {"物业": "正确答案。物业指负责管理小区房屋与环境的服务工作。", "无业": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。", "午夜": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。", "树叶": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。", "副业": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园是绿化场所，不是能负责管理的人或机构。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业是负责管理小区房屋与环境的机构或工作，与「负责」和「打扫楼道」相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是售货的商店，不负责楼道打扫。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：「负责」描述人或机构，不能说电梯很负责。"}], "explanations": {"花园": "语义：花园是绿化场所，不是能负责管理的人或机构。", "物业": "正确答案。物业是负责管理小区房屋与环境的机构或工作，与「负责」和「打扫楼道」相符。", "超市": "语义：超市是售货的商店，不负责楼道打扫。", "电梯": "搭配：「负责」描述人或机构，不能说电梯很负责。"}, "sentence_index": 0, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物业每个月都要交物业费。", "explanation": "这里应该用〈业主〉。交物业费的是房屋的业主，物业是收费并提供服务的一方，不能自己交给自己。"}, {"text": "这家物业公司每年卖出几百套新房。", "explanation": "这里应该用〈房地产〉。卖房的是房地产公司，物业公司负责管理服务，不负责销售新房。"}, {"text": "我们社区新请了一只物业来管理停车。", "explanation": "这里应该用〈家〉。物业作为公司或机构用「家」计量，「只」多用于动物或小件物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90043, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指负责管理小区房屋与环境的服务工作。"}, {"text": "牧业", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。"}, {"text": "入夜", "is_correct": false, "explanation": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。"}, {"text": "复业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}], "explanations": {"物业": "正确答案。物业指负责管理小区房屋与环境的服务工作。", "牧业": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。", "入夜": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。", "复业": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，不是可以去工作的机构或行业，「在小区的考试工作」说不通。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业指负责管理小区房屋与环境的机构或行业，「他在小区的物业工作」符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不是可以去工作的机构，「在小区的价格工作」说不通。"}, {"text": "教材", "is_correct": false, "explanation": "语义：教材是学习用书，不是可以去工作的机构，「在小区的教材工作」说不通。"}], "explanations": {"考试": "语义：考试是测验，不是可以去工作的机构或行业，「在小区的考试工作」说不通。", "物业": "正确答案。物业指负责管理小区房屋与环境的机构或行业，「他在小区的物业工作」符合语境。", "价格": "语义：价格是金额，不是可以去工作的机构，「在小区的价格工作」说不通。", "教材": "语义：教材是学习用书，不是可以去工作的机构，「在小区的教材工作」说不通。"}, "sentence_index": 6, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物业每个月都来收房租。", "explanation": "这里应该用〈房东〉。收房租的是房东，物业收取的是物业费，主要负责管理服务。"}, {"text": "我家请的物业每天给我做饭。", "explanation": "这里应该用〈保姆〉。上门做饭的是保姆这样的家政人员，物业负责管理小区的房屋和环境，不做家务。"}, {"text": "这家公司新请了一台物业，办公楼每天都打扫。", "explanation": "这里应该用〈家〉。物业作为公司或机构用「家」计量，「台」多用于机器设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区换了一只新物业，服务好多了。", "corrected_sentence": "我们小区换了一家新物业，服务好多了。", "error_description": "量词错误：物业作为公司或机构应该用「家」计量，不能用「只」。错误形式是「一只新物业」，正确形式是「一家新物业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个物业管很好，小区里很安静。", "corrected_sentence": "这个物业管得很好，小区里很安静。", "error_description": "补语错误：动词「管」后面带程度补语时要用「得」，应说「管得很好」，不能说「管很好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
