INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房屋及其配套设施；也指对其进行管理服务的行业或机构。", "primary_collocate": null, "pronunciation": "wù yè", "ipa": "u⁵¹ jɛ⁵¹", "syllable_count": 2, "sentences": [{"text": "他在城里有两处物业，一处自己住。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的物业包括办公楼和商店。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把旧物业卖掉，再买新房子。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的物业有一半已经租给了商店。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在郊区有三处物业，都租给了外地人。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片物业有楼房、花园和停车场。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，物业的服务越来越好。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把自己的物业留给了两个孩子。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一带的物业价格高得惊人，很少有人买得起。", "target_word": "物业", "complexity_tier": "T3", "furigana": "Zhè yí dài de wùyè jiàgé gāo de jīngrén, hěn shǎo yǒu rén mǎi de qǐ.", "sentence_source": "generated"}, {"text": "公司租了这栋楼的物业，用来开会和办公。", "target_word": "物业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物业费", "label": "复合"}, {"form": "物业公司", "label": "复合"}, {"form": "物业管理", "label": "复合"}], "register": "中性", "sense_fingerprint": "房屋及配套设施，也指管理服务的行业或机构(名词)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ede64bf9-61fe-41ae-8fa2-9847150bb0ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及其配套设施。"}, {"text": "无业", "is_correct": false, "explanation": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。"}, {"text": "午夜", "is_correct": false, "explanation": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。"}, {"text": "树叶", "is_correct": false, "explanation": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。"}, {"text": "副业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}], "explanations": {"物业": "正确答案。物业指房屋及其配套设施。", "无业": "wù（第四声）与 wú（第二声）声调不同，无业意思是没有工作。", "午夜": "wù（第四声）与 wǔ（第三声）声调不同，午夜意思是半夜。", "树叶": "shù 与 wù 声母不同（sh 与 w），树叶意思是树上的叶子。", "副业": "fù 与 wù 声母不同（f 与 w），副业意思是主业之外的工作。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "公园", "is_correct": false, "explanation": "语义：公园是供人游玩的场所，不能「自己住」。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房产，可以住人，符合「两处，一处自己住」。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是生产场所，不是用来居住的地方。"}, {"text": "股票", "is_correct": false, "explanation": "搭配：量词「处」用于场所，不能说「两处股票」。"}], "explanations": {"公园": "语义：公园是供人游玩的场所，不能「自己住」。", "物业": "正确答案。物业指房产，可以住人，符合「两处，一处自己住」。", "工厂": "语义：工厂是生产场所，不是用来居住的地方。", "股票": "搭配：量词「处」用于场所，不能说「两处股票」。"}, "sentence_index": 0, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的物业包括汽车、存款和股票。", "explanation": "这里应该用〈财产〉。汽车、存款和股票都不属于房屋及配套设施，物业这里指的是房产。"}, {"text": "他在城里有两只物业，一只自己住。", "explanation": "这里应该用〈处〉。物业作为房产用「处」计量，「只」不能用于房屋。"}, {"text": "这家公司的物业大部分是设备和现金。", "explanation": "这里应该用〈资产〉。设备和现金不属于房屋及配套设施，物业这里指的是房产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及其配套设施。"}, {"text": "牧业", "is_correct": false, "explanation": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。"}, {"text": "入夜", "is_correct": false, "explanation": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。"}, {"text": "复业", "is_correct": false, "explanation": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}], "explanations": {"物业": "正确答案。物业指房屋及其配套设施。", "牧业": "mù 与 wù 声母不同（m 与 w），牧业意思是放养牲畜的行业。", "入夜": "rù 与 wù 声母不同（r 与 w），入夜意思是天黑以后。", "复业": "fù 与 wù 声母不同（f 与 w），复业意思是恢复营业。"}, "sentence_index": null, "correct_answer": "物业"}, "level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不是提供服务的主体，「饭菜的服务」说不通。"}, {"text": "考试", "is_correct": false, "explanation": "正确答案。这里的「物业的服务」指管理房屋与环境的服务行业，属于本词的第二个义项，「这几年，物业的服务越来越好」符合语境。"}, {"text": "物业", "is_correct": true, "explanation": "正确答案。物业指房屋及其配套设施，「物业的服务越来越好」符合语境。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「服务」的提供方是人或机构，不说「价格的服务」。"}], "explanations": {"饭菜": "语义：饭菜是食物，不是提供服务的主体，「饭菜的服务」说不通。", "考试": "正确答案。这里的「物业的服务」指管理房屋与环境的服务行业，属于本词的第二个义项，「这几年，物业的服务越来越好」符合语境。", "物业": "正确答案。物业指房屋及其配套设施，「物业的服务越来越好」符合语境。", "价格": "搭配：「服务」的提供方是人或机构，不说「价格的服务」。"}, "sentence_index": 6, "correct_answer": "物业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "物业每个月都来收房租。", "explanation": "这里应该用〈房东〉。收房租的是房东，物业收取的是物业费，不收房租。"}, {"text": "物业每个月都要交物业费。", "explanation": "这里应该用〈业主〉。交物业费的是房屋的业主，物业是收费并提供服务的一方，不能自己交给自己。"}, {"text": "这家公司新买了一台物业，专门用来放设备。", "explanation": "这里应该用〈处〉。物业作为房产用「处」计量，「台」多用于机器设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在城里买了一只物业。", "corrected_sentence": "他在城里买了一处物业。", "error_description": "量词错误：物业作为房产应该用「处」计量，不能用「只」。错误形式是「一只物业」，正确形式是「一处物业」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把物业卖了掉。", "corrected_sentence": "他把物业卖掉了。", "error_description": "补语位置错误：「卖掉」是结果补语，「了」要放在补语之后，应说「卖掉了」，不能说「卖了掉」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9321f15-a6da-48a7-9b5c-21fba1605399') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天空正中间。", "primary_collocate": null, "pronunciation": "zhōng tiān", "ipa": "ʈʂʊŋ tʰiɛn", "syllable_count": 2, "sentences": [{"text": "十五的月亮正好在中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳走到中天，影子变得很短。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟飞过中天，不见了。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳落下前，它曾高悬中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中天有一朵白云，一动不动。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬头望着中天的月亮。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜，月亮到了中天。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中天的太阳照得人睁不开眼。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烟花在中天亮了一下。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月亮在中天，路上很亮。", "target_word": "中天", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日当中天", "label": "复合"}, {"form": "月到中天", "label": "复合"}], "register": "书面", "sense_fingerprint": "天空最中间的位置，常指月亮或太阳所在处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c28d83a-6b09-4f23-ba3e-738046e27c83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天：天空正中间。"}, {"text": "冲天", "is_correct": false, "explanation": "zh（中）与 ch（冲）声母不同，「冲天」意思是向上直冲天空，不是天空正中间。"}, {"text": "种田", "is_correct": false, "explanation": "zhōng（中）与 zhòng（种）声调不同，tiān（天）与 tián（田）声调也不同，「种田」意思是耕种田地。"}, {"text": "中听", "is_correct": false, "explanation": "tiān（天）与 tīng（听）韵母不同（ian/ing），「中听」意思是听起来悦耳。"}], "explanations": {"中天": "正确。中天：天空正中间。", "冲天": "zh（中）与 ch（冲）声母不同，「冲天」意思是向上直冲天空，不是天空正中间。", "种田": "zhōng（中）与 zhòng（种）声调不同，tiān（天）与 tián（田）声调也不同，「种田」意思是耕种田地。", "中听": "tiān（天）与 tīng（听）韵母不同（ian/ing），「中听」意思是听起来悦耳。"}, "sentence_index": null, "correct_answer": "中天"}, "level_3": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天指天空正中间，「正好在」这里的月亮所在位置符合语境。"}, {"text": "地底", "is_correct": false, "explanation": "语义：地底在地下，月亮不可能在那里，与“十五的月亮”所处的高空位置相反。"}, {"text": "河底", "is_correct": false, "explanation": "语义：河底在水下，月亮不可能在那里。"}, {"text": "窗台", "is_correct": false, "explanation": "搭配：表示「在某处」时应说「在窗台上」，只说「在窗台」不完整，且与月亮的位置不符。"}], "explanations": {"中天": "正确。中天指天空正中间，「正好在」这里的月亮所在位置符合语境。", "地底": "语义：地底在地下，月亮不可能在那里，与“十五的月亮”所处的高空位置相反。", "河底": "语义：河底在水下，月亮不可能在那里。", "窗台": "搭配：表示「在某处」时应说「在窗台上」，只说「在窗台」不完整，且与月亮的位置不符。"}, "sentence_index": 0, "correct_answer": "中天"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夕阳落在中天后面，天色渐渐暗了。", "explanation": "这里应该用〈西山〉。中天指天空正中，夕阳落下时应落在西山后面，不能落在中天后面。"}, {"text": "月亮倒映在中天上，波光粼粼。", "explanation": "这里应该用〈水面〉。倒映需要有水面，中天在天空，不能倒映月亮。"}, {"text": "一只猫躺在中天上晒太阳。", "explanation": "这里应该用〈房顶〉。中天只表示天空正中的位置，猫不能躺在那里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中天", "is_correct": true, "explanation": "正确。中天指天空正中间，「到了」这里的月亮是升到天空正中。"}, {"text": "地面", "is_correct": false, "explanation": "语义：月亮在夜空中升起，「到了地面」与月亮的位置相反。"}, {"text": "海底", "is_correct": false, "explanation": "语义：海底在水下，月亮不会到海底。"}, {"text": "锅底", "is_correct": false, "explanation": "搭配：「到了」后可以接地点，但「锅底」与「月亮」不搭，不能说月亮到了锅底。"}], "explanations": {"中天": "正确。中天指天空正中间，「到了」这里的月亮是升到天空正中。", "地面": "语义：月亮在夜空中升起，「到了地面」与月亮的位置相反。", "海底": "语义：海底在水下，月亮不会到海底。", "锅底": "搭配：「到了」后可以接地点，但「锅底」与「月亮」不搭，不能说月亮到了锅底。"}, "sentence_index": 6, "correct_answer": "中天"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站在操场的中天。", "explanation": "这里应该用〈中央〉。中天指天空正中，不能表示操场上的位置，应说站在操场的中央。"}, {"text": "学校在中天。", "explanation": "这里应该用〈河对岸〉。中天是天空中的位置，学校不可能在那里。"}, {"text": "地铁在中天。", "explanation": "这里应该用〈地下〉。地铁在地下运行，中天在天空，二者不能搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "月亮的升到中天了，路上亮起来了。", "corrected_sentence": "月亮升到中天了，路上亮起来了。", "error_description": "错误：“月亮的升到中天了”多出结构助词“的”，主语与动词之间不能插入“的”。正确：“月亮升到中天了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只鸟飞了中天，又落了下来。", "corrected_sentence": "那只鸟飞到了中天，又落了下来。", "error_description": "错误：「飞了中天」；正确：「飞到了中天」。表示飞到某个位置时要用「到」，漏掉「到」句子不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c8b20ac-4792-49c6-bbf2-bdca9f2af175') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与“集中”构成反义，指把注意力或东西分开、散开。"}, {"text": "拆卸", "is_correct": false, "explanation": "拆卸：指把整体拆开，与“集中”没有反义关系。"}, {"text": "出发", "is_correct": false, "explanation": "出发：指动身前往某地，与“集中”的聚合义没有对应关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息：指停下来不做事，与“集中”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：与“集中”构成反义，指把注意力或东西分开、散开。", "拆卸": "拆卸：指把整体拆开，与“集中”没有反义关系。", "出发": "出发：指动身前往某地，与“集中”的聚合义没有对应关系。", "休息": "休息：指停下来不做事，与“集中”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分散", "is_correct": true, "explanation": "分散：与“集中”构成反义，指把注意力或东西分开、散开。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：指闭眼休息，与“集中”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：指用声音表达乐曲，与“集中”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指随意地走走，与“集中”没有反义关系。"}], "correct_answer": "分散", "explanations": {"分散": "分散：与“集中”构成反义，指把注意力或东西分开、散开。", "睡觉": "睡觉：指闭眼休息，与“集中”没有反义关系。", "唱歌": "唱歌：指用声音表达乐曲，与“集中”没有反义关系。", "散步": "散步：指随意地走走，与“集中”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "集中是把心思或注意力放到一件事上，专心不分散。", "primary_collocate": null, "pronunciation": "jí zhōng", "ipa": "tɕi³⁵ ʈʂʊŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "上课时，请把注意力集中在黑板上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把所有的钱集中放在一个盒子里。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习的时候，我很难集中精神。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要集中想一想，这道题不难。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家的作业集中起来看。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把五个人的问题集中在一起回答。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时要集中注意，不能看手机。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把心思集中到工作上，不想别的。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把意见集中一下，再告诉我们。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把今天要买的东西集中写在纸上。", "target_word": "集中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集中了", "label": "体标"}, {"form": "集中着", "label": "体标"}, {"form": "集中过", "label": "体标"}, {"form": "集中营", "label": "复合"}], "register": "中性", "sense_fingerprint": "把心思或注意力专注到一件事上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集中", "is_correct": true, "explanation": "集中（jí zhōng）：把心思或东西放到一起，是本题要听的词。"}, {"text": "击中", "is_correct": false, "explanation": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。"}, {"text": "击钟", "is_correct": false, "explanation": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。"}, {"text": "极重", "is_correct": false, "explanation": "极重（jí zhòng）与集中（jí zhōng）只有第二音节的声调不同（zhòng 与 zhōng）。"}], "explanations": {"集中": "集中（jí zhōng）：把心思或东西放到一起，是本题要听的词。", "击中": "击中（jī zhòng）与集中（jí zhōng）两个音节的声调都不同，意思是“打中”。", "击钟": "击钟（jī zhōng）与集中（jí zhōng）只有第一音节的声调不同，意思是“敲钟”。", "极重": "极重（jí zhòng）与集中（jí zhōng）只有第二音节的声调不同（zhòng 与 zhōng）。"}, "sentence_index": null, "correct_answer": "集中"}, "level_3": {"options": [{"text": "挂", "is_correct": false, "explanation": "搭配：“挂”的对象是具体物件，注意力不能挂在黑板上。"}, {"text": "集中", "is_correct": true, "explanation": "集中：把心思专注在一处，与上课看黑板的语境相符。"}, {"text": "贴", "is_correct": false, "explanation": "搭配：“贴”要求把东西附着在表面上，注意力不能贴在黑板上。"}, {"text": "撒", "is_correct": false, "explanation": "语义：“撒”指把颗粒或液体散落开来，与抽象的注意力无关。"}], "explanations": {"挂": "搭配：“挂”的对象是具体物件，注意力不能挂在黑板上。", "集中": "集中：把心思专注在一处，与上课看黑板的语境相符。", "贴": "搭配：“贴”要求把东西附着在表面上，注意力不能贴在黑板上。", "撒": "语义：“撒”指把颗粒或液体散落开来，与抽象的注意力无关。"}, "sentence_index": 0, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的情绪很集中，一点都不着急。", "explanation": "这里应该用〈稳定〉。集中指把心思或东西聚到一处，不能用来形容情绪的平稳，形容情绪要用稳定。"}, {"text": "书架上的书按大小集中。", "explanation": "这里应该用〈排列〉。集中强调把分散的东西聚到一处，不能指按一定顺序摆放，按大小摆放要用排列。"}, {"text": "他一直集中良好的状态。", "explanation": "这里应该用〈保持〉。集中是把分散的东西或心思聚到一处，不能用于维持某种状态，维持良好状态要用保持。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放大", "is_correct": false, "explanation": "搭配：“放大”多用于图像或声音，注意力不能被放大到开车的状态。"}, {"text": "集中", "is_correct": true, "explanation": "集中：全神贯注地注意前方，与开车时不能看手机的要求一致。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”指数量变少，与开车时要专注的要求相反。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再坚持，开车时放弃注意会有危险，与句意不符。"}], "explanations": {"放大": "搭配：“放大”多用于图像或声音，注意力不能被放大到开车的状态。", "集中": "集中：全神贯注地注意前方，与开车时不能看手机的要求一致。", "减少": "语义：“减少”指数量变少，与开车时要专注的要求相反。", "放弃": "语义：“放弃”指不再坚持，开车时放弃注意会有危险，与句意不符。"}, "sentence_index": 6, "correct_answer": "集中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "上课累了，请大家集中身体休息一下。", "explanation": "这里应该用〈放松〉。集中是把分散的东西或心思聚到一处，不能用于让身体休息，放松身体要用放松。"}, {"text": "一开门，人群就集中离开了。", "explanation": "这里应该用〈散开〉。集中是聚拢的意思，不能表示向四处离去，人群四散要用散开。"}, {"text": "他的脾气很集中，发起火来很吓人。", "explanation": "这里应该用〈暴躁〉。集中是把分散的东西或心思放到一起，不能用来形容脾气，形容脾气不好要用暴躁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把全部精力集中学习上。", "corrected_sentence": "他把全部精力集中在学习上。", "error_description": "错误：“集中”后缺少介词“在”。正确：引进处所时要用“在”，说“集中在学习上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把注意力集中给书本上。", "corrected_sentence": "他把注意力集中在书本上。", "error_description": "错误：引进处所的介词用了“给”，“给”表示给予，与“集中”的意思不搭。正确：应用“在”，说“集中在书本上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
