INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90089, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名称是一个东西的名字。", "primary_collocate": null, "pronunciation": "míng chēng", "ipa": "miŋ˧˥ ʈʂʰɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这个商店的名称很好记。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格里写上产品的名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的名称，我不知道。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这条河的名称吗？", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的牌子上写着这家书店的名称。", "target_word": "名称", "complexity_tier": "T3", "furigana": "ménkǒu de páizi shang xiězhe zhè jiā shūdiàn de míngchēng.", "sentence_source": "generated"}, {"text": "他把这个节日的名称写在黑板上。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山的名称是什么意思？", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们每种水果的名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的名称改了，大家都不习惯。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药盒上有药的名称和用法。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "商品名称", "label": "复合"}], "register": "中性", "sense_fingerprint": "名称：一个东西的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90089, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名称", "is_correct": true, "explanation": "名称：事物的名字，与“很好记”相符。"}, {"text": "质量", "is_correct": false, "explanation": "语义：“质量”指好坏，不说“好记”，与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”指天空状况，不用于商店，不说“商店的天气”。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指人的性情，不用于商店。"}], "explanations": {"名称": "名称：事物的名字，与“很好记”相符。", "质量": "语义：“质量”指好坏，不说“好记”，与句意不合。", "天气": "搭配：“天气”指天空状况，不用于商店，不说“商店的天气”。", "脾气": "搭配：“脾气”指人的性情，不用于商店。"}, "sentence_index": 0, "correct_answer": "名称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里有一只名称，我很喜欢。", "explanation": "这里应该用〈个〉。名称是抽象名词，量词要用“个”，“只”多用于动物，不用于名称。"}, {"text": "他在圈子里很有名称。", "explanation": "这里应该用〈名声〉。名称指事物的名字，说人的声誉要用“名声”。"}, {"text": "老师的名称很亲切。", "explanation": "这里应该用〈称呼〉。名称指事物的名字，称呼人要用“称呼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名称", "is_correct": true, "explanation": "名称：事物的名字，与“是什么意思”的语境相符。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，与问山名含义的句意不合。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”用于人，不说山的性格。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”用于食物或气味，不说山的味道。"}], "explanations": {"名称": "名称：事物的名字，与“是什么意思”的语境相符。", "重量": "语义：“重量”指轻重，与问山名含义的句意不合。", "性格": "搭配：“性格”用于人，不说山的性格。", "味道": "搭配：“味道”用于食物或气味，不说山的味道。"}, "sentence_index": 6, "correct_answer": "名称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店有一条名称很好听。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，名称要用量词“个”。"}, {"text": "他这次考试拿到了好名称。", "explanation": "这里应该用〈名次〉。名称指事物的名字，考试的排列位置要用“名次”。"}, {"text": "我记下了他的电话名称。", "explanation": "这里应该用〈号码〉。名称指事物的名字，电话的数字要用“号码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想知道这种药名称。", "corrected_sentence": "我想知道这种药的名称。", "error_description": "错误：“药名称”。正确：“药的名称”。表示所属关系时，“的”不能省略，要放在“这种药”和“名称”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些名称们都很好记。", "corrected_sentence": "这些名称都很好记。", "error_description": "错误：“名称们”。正确：“名称”。“们”只用于指人的名词，名称指事物，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
