INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的名字。", "primary_collocate": null, "pronunciation": "míng chēng", "ipa": "miŋ˧˥ ʈʂʰɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "地图上每个城市都有名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新产品还没有名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们学会了很多动物的名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每道菜的名称都记在本子上。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种工具的名称很长，我记不住。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的树都挂着写有名称的小牌子。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的名称来自一位老人。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上查了这种鸟的名称。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些药的名称很难读。", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的名称是什么？", "target_word": "名称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "产品名称", "label": "复合"}], "register": "中性", "sense_fingerprint": "名称：事物的名字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名称", "is_correct": true, "explanation": "名称：事物的名字，与“地图上每个城市都有”相符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的练习，与地图上的城市无关。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“感情”用于人，地图上的城市不说有感情。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指人的性情，不用于城市。"}], "explanations": {"名称": "名称：事物的名字，与“地图上每个城市都有”相符。", "作业": "语义：“作业”指学生的练习，与地图上的城市无关。", "感情": "搭配：“感情”用于人，地图上的城市不说有感情。", "脾气": "搭配：“脾气”指人的性情，不用于城市。"}, "sentence_index": 0, "correct_answer": "名称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把每位同学的名称都记在本子上。", "explanation": "这里应该用〈名单〉。名称指事物的名字，一群人的名册要用“名单”。"}, {"text": "这一只名称我很喜欢。", "explanation": "这里应该用〈个〉。名称的量词是“个”，“只”一般用于动物，不用于名称。"}, {"text": "他这次比赛拿到了好名称。", "explanation": "这里应该用〈名次〉。名称指事物的名字，比赛的排列位置要用“名次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名称", "is_correct": true, "explanation": "名称：事物的名字，与“来自一位老人”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能“来自一位老人”，句意不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”用于人的劳动报酬，不说街道的工资。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物，不说街道的口味。"}], "explanations": {"名称": "名称：事物的名字，与“来自一位老人”的语境相符。", "颜色": "语义：“颜色”指色彩，不能“来自一位老人”，句意不合。", "工资": "搭配：“工资”用于人的劳动报酬，不说街道的工资。", "口味": "搭配：“口味”用于食物，不说街道的口味。"}, "sentence_index": 6, "correct_answer": "名称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在学校里很有名称。", "explanation": "这里应该用〈名声〉。名称指事物的名字，说人的声誉要用“名声”。"}, {"text": "老师的名称很亲切，大家都喜欢他。", "explanation": "这里应该用〈称呼〉。名称指事物的名字，称呼人要用“称呼”。"}, {"text": "我记下了他的电话名称。", "explanation": "这里应该用〈号码〉。名称指事物的名字，电话的数字要用“号码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
