INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90091, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哥哥是比自己大的男子,是同一个爸爸妈妈生的。", "primary_collocate": null, "pronunciation": "gē ge", "ipa": "kɤ˥ kɤ", "syllable_count": 2, "sentences": [{"text": "我哥哥今年十岁。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我有一个哥哥。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥每天骑车送我去学校。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是我哥哥，比我大三岁。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末哥哥带我去公园玩。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥喜欢踢足球。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥给我买了一个新书包。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥说他明天要去北京工作。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我和哥哥住在同一个房间里。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥做的饭很好吃，我们都喜欢。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "大哥", "label": "复合"}, {"form": "堂哥", "label": "复合"}], "register": "口语", "sense_fingerprint": "亲哥哥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36c33a4a-e234-4e15-897c-30965f67ead3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥指比自己大的同胞男子，「我哥哥今年十岁」说得通。"}, {"text": "爷爷", "is_correct": false, "explanation": "语义：爷爷是父亲的父亲，年纪不可能只有十岁，与句中年龄相矛盾。"}, {"text": "丈夫", "is_correct": false, "explanation": "语义：丈夫是配偶，十岁的孩子不能结婚，与句中年龄相矛盾。"}, {"text": "老头", "is_correct": false, "explanation": "体貌：老头指年老的男性，与「今年十岁」的描述不符。"}], "explanations": {"哥哥": "哥哥指比自己大的同胞男子，「我哥哥今年十岁」说得通。", "爷爷": "语义：爷爷是父亲的父亲，年纪不可能只有十岁，与句中年龄相矛盾。", "丈夫": "语义：丈夫是配偶，十岁的孩子不能结婚，与句中年龄相矛盾。", "老头": "体貌：老头指年老的男性，与「今年十岁」的描述不符。"}, "sentence_index": 0, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是我哥哥，在大学教书。", "explanation": "这里应该用〈姐姐〉或〈妹妹〉（视年龄而定）。哥哥只指男性，不能用来称呼女性。"}, {"text": "我哥哥是我爸爸的弟弟，住在我们隔壁。", "explanation": "这里应该用〈叔叔〉。叔叔指父亲的弟弟，不是同父母的哥哥，哥哥不能用来称呼父亲的弟弟。"}, {"text": "我哥哥今年十二岁，正在上小学，是我的儿子。", "explanation": "这里应该用〈儿子〉。哥哥是同辈的兄长，不能用来指自己的儿子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥是能给我买东西的同胞男子，句意通顺。"}, {"text": "小猫", "is_correct": false, "explanation": "配价：〈买〉要求能买东西的人作施事，小猫不能充当，句子荒谬。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是无生命的物体，不能给我买东西。"}, {"text": "大树", "is_correct": false, "explanation": "语义：大树不能去商店买东西，与句意不符。"}], "explanations": {"哥哥": "哥哥是能给我买东西的同胞男子，句意通顺。", "小猫": "配价：〈买〉要求能买东西的人作施事，小猫不能充当，句子荒谬。", "桌子": "语义：桌子是无生命的物体，不能给我买东西。", "大树": "语义：大树不能去商店买东西，与句意不符。"}, "sentence_index": 6, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥比我小三岁，很可爱。", "explanation": "这里应该用〈弟弟〉。哥哥指年纪比自己大的同胞男子，比自己小的要说弟弟。"}, {"text": "我哥哥是我爸爸的爸爸，今年八十岁了。", "explanation": "这里应该用〈爷爷〉。爷爷指父亲的父亲，比自己高一辈，不是同父母的哥哥。"}, {"text": "我哥哥今年五岁，是我的侄子。", "explanation": "这里应该用〈侄子〉。侄子指哥哥或弟弟的儿子，比自己低一辈，哥哥不能用来指侄子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有两条哥哥。", "corrected_sentence": "我们家有两个哥哥。", "error_description": "错误：“哥哥”指人，量词应用“个”或“位”。“条”用于长条形的事物，不能用来数人，应说“两个哥哥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我有两件哥哥，都比我大。", "corrected_sentence": "我有两个哥哥，都比我大。", "error_description": "〈哥哥〉指人，量词应用〈个〉或〈位〉。〈件〉用于衣物、事情等，不能用来数人，应说「两个哥哥」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
