INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "同父母(或同父异母、同母异父)而年纪比自己大的男子。", "primary_collocate": null, "pronunciation": "gē ge", "ipa": "kɤ˥ kɤ", "syllable_count": 2, "sentences": [{"text": "我的哥哥是一名医生。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥结婚以后搬到了上海。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥比我大八岁，已经工作了。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥和爸爸一样高。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的哥哥在大学教书。", "target_word": "哥哥", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给哥哥打电话，告诉他这个好消息。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们兄妹三个，哥哥最大。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥每个月都给妈妈寄钱。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过年的时候，哥哥从外地回家看爸爸妈妈。", "target_word": "哥哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥个子很高，还会打篮球。", "target_word": "哥哥", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "大哥", "label": "复合"}, {"form": "堂哥", "label": "复合"}], "register": "口语", "sense_fingerprint": "同父母年长男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36c33a4a-e234-4e15-897c-30965f67ead3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥是同父母而年长的男子，「我的哥哥是一名医生」句意通顺。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不能是医生，与「是一名医生」相矛盾。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：小孩子年纪还小，不可能是医生。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：〈是一名医生〉要求有职业的人作主语，〈桌子〉不能与之搭配。"}], "explanations": {"哥哥": "哥哥是同父母而年长的男子，「我的哥哥是一名医生」句意通顺。", "小狗": "语义：小狗是动物，不能是医生，与「是一名医生」相矛盾。", "小孩子": "语义：小孩子年纪还小，不可能是医生。", "桌子": "搭配：〈是一名医生〉要求有职业的人作主语，〈桌子〉不能与之搭配。"}, "sentence_index": 0, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥比我小两岁，还在上学。", "explanation": "这里应该用〈弟弟〉。哥哥指年纪比自己大的同胞男子，比自己小的要说弟弟。"}, {"text": "她是我哥哥，正在读小学。", "explanation": "这里应该用〈妹妹〉或〈姐姐〉（视年龄而定）。哥哥只指男性，不能用来称呼女性。"}, {"text": "我哥哥是我爸爸的弟弟，今年四十岁，在上海工作。", "explanation": "这里应该用〈叔叔〉。叔叔指父亲的弟弟，不是同父母或同父异母、同母异父的哥哥，哥哥不能用来指父亲的弟弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哥哥", "is_correct": true, "explanation": "哥哥是同父母而年长的男子，「我们兄妹三个，哥哥最大」句意通顺。"}, {"text": "妈妈", "is_correct": false, "explanation": "语义：妈妈是母亲，不是兄妹之一，句中「兄妹三个」里不会是她最大。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：叔叔是父亲的兄弟，不属于兄妹三个，与句意不符。"}, {"text": "小猫", "is_correct": false, "explanation": "搭配：〈兄妹三个〉指同辈的人，〈小猫〉不能与之搭配。"}], "explanations": {"哥哥": "哥哥是同父母而年长的男子，「我们兄妹三个，哥哥最大」句意通顺。", "妈妈": "语义：妈妈是母亲，不是兄妹之一，句中「兄妹三个」里不会是她最大。", "叔叔": "语义：叔叔是父亲的兄弟，不属于兄妹三个，与句意不符。", "小猫": "搭配：〈兄妹三个〉指同辈的人，〈小猫〉不能与之搭配。"}, "sentence_index": 6, "correct_answer": "哥哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我哥哥才五岁，是我的侄子，每天来我家玩。", "explanation": "这里应该用〈侄子〉。侄子指哥哥或弟弟的儿子，比自己低一辈，哥哥不能用来指侄子。"}, {"text": "她是我哥哥，个子很高，还会打篮球。", "explanation": "这里应该用〈姐姐〉或〈妹妹〉（视年龄而定）。哥哥只指男性，女性即使个子高也不能说哥哥。"}, {"text": "我哥哥是我爸爸的爸爸，今年八十岁了，身体很好。", "explanation": "这里应该用〈爷爷〉。爷爷指父亲的父亲，比自己高一辈，不是同父母或同父异母、同母异父的哥哥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有两只哥哥。", "corrected_sentence": "我有两个哥哥。", "error_description": "〈哥哥〉指人，量词应用〈个〉或〈位〉。〈只〉用于动物，不能用来数人，应说「两个哥哥」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有两哥哥，每天早上都跑步。", "corrected_sentence": "我家有两个哥哥，每天早上都跑步。", "error_description": "错误：数词“两”与“哥哥”之间需要量词，应说“两个哥哥”，不能省略量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "好：与“坏”相对，指灯能正常使用。"}, {"text": "长", "is_correct": false, "explanation": "长指长度，与“坏”没有反义关系，它的反义词是“短”。"}, {"text": "新", "is_correct": false, "explanation": "新与“旧”相对，不是“坏”的反义词。"}, {"text": "大", "is_correct": false, "explanation": "大指体积或程度，与“坏”没有反义关系。"}], "correct_answer": "好", "explanations": {"好": "好：与“坏”相对，指灯能正常使用。", "长": "长指长度，与“坏”没有反义关系，它的反义词是“短”。", "新": "新与“旧”相对，不是“坏”的反义词。", "大": "大指体积或程度，与“坏”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "好：与“坏”相对，指东西没有毛病、能用。"}, {"text": "快", "is_correct": false, "explanation": "快指速度，与“坏”没有反义关系，它的反义词是“慢”。"}, {"text": "轻", "is_correct": false, "explanation": "轻指重量，与“坏”没有反义关系，它的反义词是“重”。"}, {"text": "高", "is_correct": false, "explanation": "高指高度，与“坏”没有反义关系，它的反义词是“低”。"}], "correct_answer": "好", "explanations": {"好": "好：与“坏”相对，指东西没有毛病、能用。", "快": "快指速度，与“坏”没有反义关系，它的反义词是“慢”。", "轻": "轻指重量，与“坏”没有反义关系，它的反义词是“重”。", "高": "高指高度，与“坏”没有反义关系，它的反义词是“低”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "坏是不好的,不能用了。", "primary_collocate": null, "pronunciation": "huài", "ipa": "xwaɪ⁵¹", "syllable_count": 1, "sentences": [{"text": "我的手机坏了，不能打电话。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我们只能走楼梯上去。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子坏了，一坐就会倒。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯坏了，晚上屋里一点儿光都没有。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱坏了，里面的东西都不冷了。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔写不出字，是坏的。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车坏了，今天走路上班。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机坏了三天，还没有人来修。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门锁坏了，我进不去家门。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台旧电脑坏了，我想买新的。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坏了", "label": "体标"}, {"form": "坏过", "label": "体标"}, {"form": "坏处", "label": "复合"}, {"form": "坏蛋", "label": "复合"}, {"form": "壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西出了毛病，不能再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：东西出了毛病、不能用了，是本题答案。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。"}, {"text": "怀", "is_correct": false, "explanation": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。"}, {"text": "换", "is_correct": false, "explanation": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}], "explanations": {"坏": "坏 huài：东西出了毛病、不能用了，是本题答案。", "快": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。", "怪": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。", "怀": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。", "换": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：东西出了毛病、不能用了，与“不能打电话”的原因相符。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”说速度，手机慢了并不会导致不能打电话。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说屏幕发光，与句中“不能打电话”的意思不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”用于食物或味道，不说手机甜了。"}], "explanations": {"坏": "坏：东西出了毛病、不能用了，与“不能打电话”的原因相符。", "慢": "语义：“慢”说速度，手机慢了并不会导致不能打电话。", "亮": "语义：“亮”说屏幕发光，与句中“不能打电话”的意思不合。", "甜": "搭配：“甜”用于食物或味道，不说手机甜了。"}, "sentence_index": 0, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的会议坏了，改到明天再开。", "explanation": "这里应该用〈推迟〉。坏指东西出毛病，会议延期要用“推迟”，不说“会议坏了”。"}, {"text": "这张过期的优惠券早就坏了，不能用了。", "explanation": "这里应该用〈作废〉。坏指东西出毛病，优惠券、车票过期失去效力要用“作废”。"}, {"text": "地上的文件坏了一地，乱七八糟的。", "explanation": "这里应该用〈散〉。坏指东西出毛病，纸张、物品四处散落要用“散”，不说“坏了一地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：东西出了毛病、不能用了，是本题答案。"}, {"text": "块", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}], "explanations": {"坏": "坏 huài：东西出了毛病、不能用了，是本题答案。", "块": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。", "帅": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。", "话": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：东西出了毛病、不能骑了，与“走路上班”的原因相符。"}, {"text": "新", "is_correct": false, "explanation": "语义：“新”说崭新，自行车新了与走路上班没有因果关系。"}, {"text": "凉", "is_correct": false, "explanation": "搭配：“凉”多用于水、饭菜、天气，不说自行车凉了。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”说高度，自行车高了与走路上班之间没有因果。"}], "explanations": {"坏": "坏：东西出了毛病、不能骑了，与“走路上班”的原因相符。", "新": "语义：“新”说崭新，自行车新了与走路上班没有因果关系。", "凉": "搭配：“凉”多用于水、饭菜、天气，不说自行车凉了。", "高": "语义：“高”说高度，自行车高了与走路上班之间没有因果。"}, "sentence_index": 6, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店因为装修，暂时坏了。", "explanation": "这里应该用〈停业〉。坏指东西出毛病，店铺暂时关门不营业要用“停业”，不说“店坏了”。"}, {"text": "这门手艺已经坏了，没有人会做了。", "explanation": "这里应该用〈失传〉。坏指东西出毛病，技艺因无人继承而不再流传要用“失传”。"}, {"text": "炉子里的火坏了，屋里很冷。", "explanation": "这里应该用〈熄灭〉。坏指东西出毛病，火因没有燃料或风而灭掉要用“熄灭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台冰箱了坏，要找人修。", "corrected_sentence": "这台冰箱坏了，要找人修。", "error_description": "错误：“了坏”。正确：“坏了”。“了”要放在“坏”的后面，表示变化后的状态，不能放在“坏”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的自行车前天坏，修好要一个星期。", "corrected_sentence": "我的自行车前天坏了，修好要一个星期。", "error_description": "错误：“坏”。正确：“坏了”。句子表示车已经坏掉这一变化，要带“了”，省略后不符合已发生变化的说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
