INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "好", "is_correct": true, "explanation": "好：与“心情很坏”相对，指心情愉快。"}, {"text": "多", "is_correct": false, "explanation": "多指数量，与“坏”没有反义关系，它的反义词是“少”。"}, {"text": "短", "is_correct": false, "explanation": "短指长度，与“坏”没有反义关系，它的反义词是“长”。"}, {"text": "深", "is_correct": false, "explanation": "深指深度，与“坏”没有反义关系，它的反义词是“浅”。"}], "correct_answer": "好", "explanations": {"好": "好：与“心情很坏”相对，指心情愉快。", "多": "多指数量，与“坏”没有反义关系，它的反义词是“少”。", "短": "短指长度，与“坏”没有反义关系，它的反义词是“长”。", "深": "深指深度，与“坏”没有反义关系，它的反义词是“浅”。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不好的;有害的;出了毛病的。", "primary_collocate": null, "pronunciation": "huài", "ipa": "xwaɪ⁵¹", "syllable_count": 1, "sentences": [{"text": "他脾气很坏，大家都不愿意和他说话。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽烟是个坏习惯，对身体不好。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是坏天气，下了一整天大雨。", "target_word": "坏", "complexity_tier": "T3", "furigana": "jīntiān shì huài tiānqì, xià le yì zhěng tiān dà yǔ.", "sentence_source": "generated"}, {"text": "这个坏消息让全家人都很难过。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心眼不坏，只是说话太直。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人很坏，常常骗别人的钱。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱吃糖，所以牙坏了好几颗。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的坏主意太多，没人信他。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼放了三天，坏了，别吃。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天心情很坏，一句话也不想说。", "target_word": "坏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "坏了", "label": "体标"}, {"form": "坏过", "label": "体标"}, {"form": "坏处", "label": "复合"}, {"form": "坏蛋", "label": "复合"}, {"form": "壞", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人、事、天气等不好或有害，也指出了毛病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：状况不好或东西出了毛病，是本题答案。"}, {"text": "快", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。"}, {"text": "怪", "is_correct": false, "explanation": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。"}, {"text": "帅", "is_correct": false, "explanation": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。"}, {"text": "换", "is_correct": false, "explanation": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}], "explanations": {"坏": "坏 huài：状况不好或东西出了毛病，是本题答案。", "快": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是快。", "怪": "guài 与 huài 声母不同（g 与 h），声调相同，意思是奇怪。", "帅": "shuài 与 huài 声母不同（sh 与 h），声调相同，意思是英俊。", "换": "huàn 与 huài 韵母不同（末尾 -n 与 -i），声调相同，意思是交换。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：脾气不好，与“大家都不愿意和他说话”相符。"}, {"text": "好", "is_correct": false, "explanation": "语义：“好”指脾气好，与后半句“大家都不愿意和他说话”矛盾。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”说重量，不说脾气轻。"}, {"text": "温", "is_correct": false, "explanation": "语义：“温”指温和，与“大家都不愿意和他说话”的语境矛盾。"}], "explanations": {"坏": "坏：脾气不好，与“大家都不愿意和他说话”相符。", "好": "语义：“好”指脾气好，与后半句“大家都不愿意和他说话”矛盾。", "轻": "搭配：“轻”说重量，不说脾气轻。", "温": "语义：“温”指温和，与“大家都不愿意和他说话”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题我的答案坏了，应该再算一遍。", "explanation": "这里应该用〈错〉。坏指东西有毛病或状况不好，不用来判断答案对错；答案错了要说“错”。"}, {"text": "他的英语很坏，考试总是不及格。", "explanation": "这里应该用〈差〉。坏多用于品行、事情或东西有毛病，说能力不足要用“差”。"}, {"text": "这个房间的面积很坏，住起来很挤。", "explanation": "这里应该用〈小〉。坏表示不好或有毛病，不用来说面积的大小，面积小要用“小”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏 huài：状况不好或东西出了毛病，是本题答案。"}, {"text": "块", "is_correct": false, "explanation": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。"}, {"text": "怀", "is_correct": false, "explanation": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。"}, {"text": "话", "is_correct": false, "explanation": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}], "explanations": {"坏": "坏 huài：状况不好或东西出了毛病，是本题答案。", "块": "kuài 与 huài 声母不同（k 与 h），声调相同，意思是块状物。", "怀": "huái（第二声）与 huài（第四声）声调不同，意思是怀抱、怀念。", "话": "huà 与 huài 韵母不同（少了末尾的 -i），声调相同，意思是话语。"}, "sentence_index": null, "correct_answer": "坏"}, "level_3": {"options": [{"text": "坏", "is_correct": true, "explanation": "坏：牙齿出了毛病，与“爱吃糖”的原因相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说发光，牙亮了与“爱吃糖”的因果不合。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不说牙甜了。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说高度，不用来说牙高了。"}], "explanations": {"坏": "坏：牙齿出了毛病，与“爱吃糖”的原因相符。", "亮": "语义：“亮”说发光，牙亮了与“爱吃糖”的因果不合。", "甜": "搭配：“甜”说味道，不说牙甜了。", "高": "搭配：“高”说高度，不用来说牙高了。"}, "sentence_index": 6, "correct_answer": "坏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为堵车坏了，开会时才到。", "explanation": "这里应该用〈迟到〉。坏指东西或状况出了毛病，人来得晚要用“迟到”，不说“坏了”。"}, {"text": "我们这次比赛坏了，没能进入决赛。", "explanation": "这里应该用〈输〉。坏不用来说比赛的结果，比赛没赢要用“输”。"}, {"text": "我们在山里坏了，天黑才走出来。", "explanation": "这里应该用〈迷路〉。坏指东西出毛病或状况不好，人找不到方向要用“迷路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛的天气坏很，比赛推迟了。", "corrected_sentence": "这次比赛的天气很坏，比赛推迟了。", "error_description": "错误：“坏很”。正确：“很坏”。“坏”是形容词，前面要加程度副词“很”，语序应为“很坏”，不能说“坏很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的眼镜昨天就坏，所以没戴。", "corrected_sentence": "我的眼镜昨天就坏了，所以没戴。", "error_description": "错误：“坏”。正确：“坏了”。句子表示眼镜已经坏掉这一变化，要带“了”，省略后不符合已发生变化的说法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
