INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打算是想好了要做什么。", "primary_collocate": null, "pronunciation": "dǎ suàn", "ipa": "ta˨˩˦ swan˥˩", "syllable_count": 2, "sentences": [{"text": "我打算明天去看奶奶。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假你打算做什么？", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算下个月搬家。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算坐火车去北京。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算学开车，已经报名了。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我没打算出门。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们打算几点出发？", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打算把这本书看完。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就打算买新手机了。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算在家里吃晚饭。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打算过", "label": "体标"}, {"form": "打算了", "label": "体标"}], "register": "中性", "sense_fingerprint": "打算：已经想好要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings =