INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：已经想好要做某事，是本义。"}, {"text": "大蒜", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种调味的蔬菜。"}, {"text": "打散", "is_correct": false, "explanation": "sàn 与 suàn 韵母不同（少了 u），意思是分散、拆开。"}, {"text": "打伞", "is_correct": false, "explanation": "sǎn 与 suàn 韵母不同（少了 u），意思是撑开雨伞。"}], "explanations": {"打算": "打算：已经想好要做某事，是本义。", "大蒜": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种调味的蔬菜。", "打散": "sàn 与 suàn 韵母不同（少了 u），意思是分散、拆开。", "打伞": "sǎn 与 suàn 韵母不同（少了 u），意思是撑开雨伞。"}, "sentence_index": null, "correct_answer": "打算"}, "level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：已经想好明天要去看奶奶，符合句子的语境。"}, {"text": "后悔", "is_correct": false, "explanation": "语义：“后悔”针对已经发生的事，与“明天去看奶奶”的计划不符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”后面接活动名词，不能接“去看奶奶”这类动作短语。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”是清理场所，与“去看奶奶”的行程毫不相关。"}], "explanations": {"打算": "打算：已经想好明天要去看奶奶，符合句子的语境。", "后悔": "语义：“后悔”针对已经发生的事，与“明天去看奶奶”的计划不符。", "参加": "搭配：“参加”后面接活动名词，不能接“去看奶奶”这类动作短语。", "打扫": "语义：“打扫”是清理场所，与“去看奶奶”的行程毫不相关。"}, "sentence_index": 0, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打算明天会下雨。", "explanation": "这里应该用〈估计〉。打算表示想好要做的事，不表示对将来的推测，判断会不会下雨要用估计。"}, {"text": "我们打算吃掉一整座山。", "explanation": "这里误用了“打算”的计划义项。打算后面接的应是人能主动完成的行为，吃掉一整座山不是人能计划做到的事。"}, {"text": "她打算不喜欢这个礼物。", "explanation": "这里应该用〈觉得〉。打算表示计划要做的行为，不能接“不喜欢”这种心理感受；表示感受要用觉得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：已经想好何时出发的计划，符合句子的语境。"}, {"text": "允许", "is_correct": false, "explanation": "配价：“允许”要带“某人做某事”的结构，这里缺少动作的主体，不成立。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多接纪录、规定，不接“几点出发”这类时间安排。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复器物，与出发的时间安排毫不相关。"}], "explanations": {"打算": "打算：已经想好何时出发的计划，符合句子的语境。", "允许": "配价：“允许”要带“某人做某事”的结构，这里缺少动作的主体，不成立。", "打破": "搭配：“打破”多接纪录、规定，不接“几点出发”这类时间安排。", "修理": "语义：“修理”是修复器物，与出发的时间安排毫不相关。"}, "sentence_index": 6, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子打算明天搬到楼上去。", "explanation": "这里误用了“打算”的计划义项。打算要求有意志的人作主语，椅子不能计划搬动。"}, {"text": "我打算他的名字。", "explanation": "这里应该用〈记得〉。打算表示想好要做的事，不能表示记住人或事物。"}, {"text": "我正在打算丢失的钥匙。", "explanation": "这里应该用〈寻找〉。打算表示想好要做的事，不能表示去找东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我打算把下个月去上海。", "corrected_sentence": "我打算下个月去上海。", "error_description": "错误形式：“打算把下个月去上海”。正确形式：“打算下个月去上海”。“把”字句需要一个可被处置的宾语，这里“下个月”不是可处置的对象，多出的“把”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们周末打算哪儿玩？", "corrected_sentence": "你们周末打算去哪儿玩？", "error_description": "错误：“打算哪儿玩”。正确：“打算去哪儿玩”。“打算”后面要接完整的动词短语，“去”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
