INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考虑;想要做某事。", "primary_collocate": null, "pronunciation": "dǎ suàn", "ipa": "ta˨˩˦ swan˥˩", "syllable_count": 2, "sentences": [{"text": "我正在打算换一份新工作。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算来打算去，还是没有决定。", "target_word": "打算", "complexity_tier": "T3", "furigana": "tā dǎ suàn lái dǎ suàn qù, hái shì méi yǒu jué dìng.", "sentence_source": "generated"}, {"text": "你打算过出国学习吗？", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟长大以后打算当老师。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不打算参加这次比赛。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打算过一个安静的周末。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打算怎么回家？", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打算过自己开一家小店。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车的事，我还在打算，没有决定。", "target_word": "打算", "complexity_tier": "T3", "furigana": "mǎi chē de shì, wǒ hái zài dǎ suàn, méi yǒu jué dìng.", "sentence_source": "generated"}, {"text": "大家都在打算怎么过新年。", "target_word": "打算", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打算过", "label": "体标"}, {"form": "打算了", "label": "体标"}], "register": "中性", "sense_fingerprint": "打算：考虑、想要做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：考虑或想要做某事，是本句的义项。"}, {"text": "大蒜", "is_correct": false, "explanation": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种调味的蔬菜。"}, {"text": "打散", "is_correct": false, "explanation": "sàn 与 suàn 韵母不同（少了 u），意思是分散、拆开。"}, {"text": "打伞", "is_correct": false, "explanation": "sǎn 与 suàn 韵母不同（少了 u），意思是撑开雨伞。"}], "explanations": {"打算": "打算：考虑或想要做某事，是本句的义项。", "大蒜": "dà（第四声）与 dǎ（第三声）声调不同，意思是一种调味的蔬菜。", "打散": "sàn 与 suàn 韵母不同（少了 u），意思是分散、拆开。", "打伞": "sǎn 与 suàn 韵母不同（少了 u），意思是撑开雨伞。"}, "sentence_index": null, "correct_answer": "打算"}, "level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：考虑换一份新工作，符合句子的语境。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”多接纪录、规定，不能接“换一份新工作”。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”接具体的事物，不接“换工作”这样的动作。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是毁坏物品，与“换工作”的考虑毫不相关。"}], "explanations": {"打算": "打算：考虑换一份新工作，符合句子的语境。", "打破": "搭配：“打破”多接纪录、规定，不能接“换一份新工作”。", "拥有": "搭配：“拥有”接具体的事物，不接“换工作”这样的动作。", "烧毁": "语义：“烧毁”是毁坏物品，与“换工作”的考虑毫不相关。"}, "sentence_index": 0, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 8, "wrong_sentences": [{"text": "这位科学家打算这个现象已经很多年了。", "explanation": "这里应该用〈研究〉。打算的考虑义项多用于是否做某事的决定，不能用于研究事物或现象。"}, {"text": "我打算你能来参加我的生日。", "explanation": "这里应该用〈希望〉。打算表示自己想要做某事，不能表示希望别人做某事。"}, {"text": "我的手机一直在打算。", "explanation": "这里误用了“打算”的“考虑”义项，把它当作〈想〉来用。“打算”要求有意识的人作主语，手机不能考虑，应改用以人为主语的〈想〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打算", "is_correct": true, "explanation": "打算：考虑怎么回家，符合句子的语境。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”是心理动词，不能接“怎么回家”这样的疑问短语。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”指丢掉具体的东西或状态，与“回家的方式”的考虑毫不相干。"}, {"text": "分配", "is_correct": false, "explanation": "搭配：“分配”多接任务、资源，不接“怎么回家”这样的方式。"}], "explanations": {"打算": "打算：考虑怎么回家，符合句子的语境。", "讨厌": "语义：“讨厌”是心理动词，不能接“怎么回家”这样的疑问短语。", "失去": "语义：“失去”指丢掉具体的东西或状态，与“回家的方式”的考虑毫不相干。", "分配": "搭配：“分配”多接任务、资源，不接“怎么回家”这样的方式。"}, "sentence_index": 6, "correct_answer": "打算"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家打算这部电影的票房数字。", "explanation": "这里应该用〈统计〉。打算的考虑义项用于是否做某事的决定，不能用于统计数字。"}, {"text": "我打算他说的话，觉得很奇怪。", "explanation": "这里应该用〈怀疑〉。打算表示考虑或计划，不能表示对别人的话持怀疑态度。"}, {"text": "这个方案的数据打算了很久。", "explanation": "这里误用了“打算”的“考虑”义项，把它当作〈分析〉来用。数据是事物，不能作“考虑”的主语，应改用〈分析〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还在打算了要不要搬家。", "corrected_sentence": "他还在打算要不要搬家。", "error_description": "错误形式：“打算了”。正确形式：“打算”。表示还在考虑的状态时，“打算”后面不能接“了”，“了”会表示考虑已经结束。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还在打算了要不要买车。", "corrected_sentence": "他还在打算要不要买车。", "error_description": "错误形式：“打算了”。正确形式：“打算”。表示还在考虑的状态时，“打算”后面不能接“了”，“了”会表示考虑已经结束。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
