INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90106, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迎接人到来；把两头连在一起。", "primary_collocate": null, "pronunciation": "jiē", "ipa": "tɕjɛ˥", "syllable_count": 1, "sentences": [{"text": "我明天去机场接朋友。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天下午四点去学校接孩子。", "target_word": "接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管太短了，要再接一根。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人一到，主人就赶紧出门去接。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人在墙角接了一根新电线。", "target_word": "接", "complexity_tier": "T3", "furigana": "gōng rén zài qiáng jiǎo jiē le yì gēn xīn diàn xiàn", "sentence_source": "generated"}, {"text": "火车站太远，你能来接我吗？", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸开车来接我们回家。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去门口接客人吧。", "target_word": "接", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把这两根绳子接在一起，才够长。", "target_word": "接", "complexity_tier": "T3", "furigana": "bǎ zhè liǎng gēn shéng zi jiē zài yì qǐ cái gòu cháng", "sentence_source": "generated"}, {"text": "办公室的网线没有接，所以上不了网。", "target_word": "接", "complexity_tier": "T3", "furigana": "bàn gōng shì de wǎng xiàn méi yǒu jiē suǒ yǐ shàng bù liǎo wǎng", "sentence_source": "generated"}], "morphological_forms": [{"form": "接了", "label": "体标"}, {"form": "接着", "label": "体标"}, {"form": "接过", "label": "体标"}, {"form": "接上", "label": "复合"}], "register": "通用", "sense_fingerprint": "迎接人到来，或把两头连在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c16745d-ee73-4b44-8e65-a27eab05b8e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接", "is_correct": true, "explanation": "接（jiē）：迎接人到来，或把两头连在一起。"}, {"text": "姐", "is_correct": false, "explanation": "“姐”（jiě，第三声）与“接”声调不同，意思是姐姐。"}, {"text": "节", "is_correct": false, "explanation": "“节”（jié，第二声）与“接”声调不同，意思是节日。"}, {"text": "界", "is_correct": false, "explanation": "“界”（jiè，第四声）与“接”声调不同，意思是界限。"}, {"text": "切", "is_correct": false, "explanation": "“切”（qiē）与“接”（jiē）声母不同，意思是用刀切开。"}], "explanations": {"接": "接（jiē）：迎接人到来，或把两头连在一起。", "姐": "“姐”（jiě，第三声）与“接”声调不同，意思是姐姐。", "节": "“节”（jié，第二声）与“接”声调不同，意思是节日。", "界": "“界”（jiè，第四声）与“接”声调不同，意思是界限。", "切": "“切”（qiē）与“接”（jiē）声母不同，意思是用刀切开。"}, "sentence_index": null, "correct_answer": "接"}, "level_3": {"options": [{"text": "接", "is_correct": true, "explanation": "接表示到机场迎接朋友，与句意相合。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”不能和“朋友”搭配，“买朋友”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于人，“去机场吃朋友”说不通。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚攻击，不能用来对待朋友，句子不通。"}], "explanations": {"接": "接表示到机场迎接朋友，与句意相合。", "买": "搭配：“买”不能和“朋友”搭配，“买朋友”不成立。", "吃": "语义：“吃”不能用于人，“去机场吃朋友”说不通。", "踢": "语义：“踢”是用脚攻击，不能用来对待朋友，句子不通。"}, "sentence_index": 0, "correct_answer": "接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他接了巨大的压力，几乎喘不过气。", "explanation": "这里应该用〈承受〉。“接”用于接收、迎接或连上，承受压力应说“承受”。"}, {"text": "他接起一袋米，走进了仓库。", "explanation": "这里应该用〈扛〉。“扛”指把东西架在肩上搬运，“接”指用手承接飞来或递来的东西，不表示搬运。"}, {"text": "我把花瓶接在桌上，就出门了。", "explanation": "这里应该用〈摆〉。“摆”指陈设、放置，“接”不表示放置，不能说“接在桌上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "接", "is_correct": true, "explanation": "接（jiē）：迎接人到来，或把两头连在一起。"}, {"text": "借", "is_correct": false, "explanation": "“借”（jiè，第四声）与“接”声调不同，意思是借用。"}, {"text": "结", "is_correct": false, "explanation": "“结”（jié，第二声）与“接”声调不同，意思是打结或结束。"}, {"text": "些", "is_correct": false, "explanation": "“些”（xiē）与“接”（jiē）声母不同，意思是一些。"}], "explanations": {"接": "接（jiē）：迎接人到来，或把两头连在一起。", "借": "“借”（jiè，第四声）与“接”声调不同，意思是借用。", "结": "“结”（jié，第二声）与“接”声调不同，意思是打结或结束。", "些": "“些”（xiē）与“接”（jiē）声母不同，意思是一些。"}, "sentence_index": null, "correct_answer": "接"}, "level_3": {"options": [{"text": "接", "is_correct": true, "explanation": "接表示去迎接人，与“开车来”“回家”相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“我们回家”这样的宾语，与“开车来”也不搭配。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，与开车接人回家的语境不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与开车接人回家的意思相反。"}], "explanations": {"接": "接表示去迎接人，与“开车来”“回家”相合。", "洗": "搭配：“洗”不能带“我们回家”这样的宾语，与“开车来”也不搭配。", "修": "语义：“修”指修理，与开车接人回家的语境不符。", "扔": "语义：“扔”是丢弃，与开车接人回家的意思相反。"}, "sentence_index": 6, "correct_answer": "接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接起书包就出门了。", "explanation": "这里应该用〈背〉。“背”指用肩背着东西，“接”指用手承接对方递来的东西，不表示背着东西。"}, {"text": "他接了老师的批评，低头不说话。", "explanation": "这里应该用〈接受〉。“接”不用于接受批评，应说“接受”。"}, {"text": "他从书架上接下一本书。", "explanation": "这里应该用〈拿〉。“接下”指用手承接对方递来的东西，从书架上取书应说“拿下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两根管子终于上接了。", "corrected_sentence": "两根管子终于接上了。", "error_description": "“接上”是结果补语复合，“上”应放在“接”后，不能说“上接”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的网线已经接了好。", "corrected_sentence": "新的网线已经接好了。", "error_description": "“接好”是结果补语，“了”应放在补语后，说“接好了”，不能说“接了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
