INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90112, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接到;得到别人送来的东西。", "primary_collocate": null, "pronunciation": "shōu dào", "ipa": "ʂoʊ˥˥ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我昨天收到了朋友的信。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收到我发的短信了吗？", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收到一个很重的包裹。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没有收到快递。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他收到了大学的通知书。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从国外寄来的包裹，我今天收到了。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师收到了同学们的作业。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们收到了很多人寄来的明信片。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都会收到一张新年卡片。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你收到邮件后马上回复我。", "target_word": "收到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收到了", "label": "体标"}, {"form": "收到过", "label": "体标"}], "register": "中性", "sense_fingerprint": "收到：接到别人寄来、送来的信件或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c2be8c7-2080-49fc-b119-5704ca40e9ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90112, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：接到别人寄来、送来的东西，是本义。"}, {"text": "受到", "is_correct": false, "explanation": "shòu（第四声）与 shōu（第一声）声调不同，意思是遭受、承受，不是接到东西。"}, {"text": "搜到", "is_correct": false, "explanation": "sōu 与 shōu 声母不同（s 与 sh），意思是通过查找而找到。"}, {"text": "守到", "is_correct": false, "explanation": "shǒu（第三声）与 shōu（第一声）声调不同，意思是守候到某个时候。"}, {"text": "手到", "is_correct": false, "explanation": "shǒu（第三声）与 shōu（第一声）声调不同，意思是动手就能成功。"}], "explanations": {"收到": "收到：接到别人寄来、送来的东西，是本义。", "受到": "shòu（第四声）与 shōu（第一声）声调不同，意思是遭受、承受，不是接到东西。", "搜到": "sōu 与 shōu 声母不同（s 与 sh），意思是通过查找而找到。", "守到": "shǒu（第三声）与 shōu（第一声）声调不同，意思是守候到某个时候。", "手到": "shǒu（第三声）与 shōu（第一声）声调不同，意思是动手就能成功。"}, "sentence_index": null, "correct_answer": "收到"}, "level_3": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：接到朋友寄来的信，符合句子的语境。"}, {"text": "寄出", "is_correct": false, "explanation": "语义：寄出是把信发出去，与“朋友的信”这种来信的语境相反。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”多接荣誉、信任等抽象事物，不能说赢得一封信。"}, {"text": "发出", "is_correct": false, "explanation": "语义：发出指自己把东西送出去，与“我”作为收信人的语境不符。"}], "explanations": {"收到": "收到：接到朋友寄来的信，符合句子的语境。", "寄出": "语义：寄出是把信发出去，与“朋友的信”这种来信的语境相反。", "赢得": "搭配：“赢得”多接荣誉、信任等抽象事物，不能说赢得一封信。", "发出": "语义：发出指自己把东西送出去，与“我”作为收信人的语境不符。"}, "sentence_index": 0, "correct_answer": "收到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠努力收到了博士学位。", "explanation": "这里应该用〈获得〉。收到用于接到寄来的东西或消息，学位、奖项这类成果要用获得。"}, {"text": "他收到了很大的压力。", "explanation": "这里应该用〈承受〉。收到用于接到寄来的东西或消息，压力、负担要用承受。"}, {"text": "这次失败让他收到了很大的打击。", "explanation": "这里应该用〈受到〉。收到用于接到寄来的东西或消息，打击、伤害这类遭遇要用受到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收到", "is_correct": true, "explanation": "收到：接到学生交来的作业，符合句子的语境。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉是把东西吃下去，与“作业”毫不相关。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”多接申请、计划，不接“作业”这类东西。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”是心理动词，不表示接收或交付作业的动作。"}], "explanations": {"收到": "收到：接到学生交来的作业，符合句子的语境。", "吃掉": "语义：吃掉是把东西吃下去，与“作业”毫不相关。", "批准": "搭配：“批准”多接申请、计划，不接“作业”这类东西。", "讨厌": "语义：“讨厌”是心理动词，不表示接收或交付作业的动作。"}, "sentence_index": 6, "correct_answer": "收到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在比赛中收到了第一名。", "explanation": "这里应该用〈获得〉。收到用于接到东西、信息，名次、奖项要用获得。"}, {"text": "我昨天收到了一次车祸。", "explanation": "这里应该用〈经历〉。收到用于接到寄来的东西或消息，车祸这类事件要用经历。"}, {"text": "我在路上收到了老朋友。", "explanation": "这里应该用〈遇到〉。收到用于接到东西或消息，遇见人不能用收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天被收到了一封信。", "corrected_sentence": "我今天收到了一封信。", "error_description": "错误：“被收到”。正确：“收到”。“收到”的施事是收信的人，句中的“我”应作主语；加“被”后“我”变成受事，句意不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前收到了过一份生日礼物。", "corrected_sentence": "我以前收到过一份生日礼物。", "error_description": "错误形式：“收到了过”。正确形式：“收到过”。表示有过某种经历时只用“过”，“了”和“过”不能同时用在同一个动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96bd29f3-abbe-4b8b-bbd3-de146fc52766') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
