INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90113, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究领域是一个人专门研究的那一类事。", "primary_collocate": null, "pronunciation": "yán jiū lǐng yù", "ipa": "jɛn˧˥ tɕjoʊ˥ liŋ˨˩˦ y˥˩", "syllable_count": 4, "sentences": [{"text": "我的研究领域是海洋生物。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了研究领域，现在做人工智能。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的研究领域是什么？", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的研究领域和我的不一样。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个研究领域很感兴趣。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我以后想选哪个研究领域。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在自己的研究领域里努力工作。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王教授的研究领域是中国古代历史。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选好研究领域以后，我开始读相关的书。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人的研究领域很接近，常常讨论问题。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "研究領域", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人自己专门研究的那一类事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90113, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究领域", "is_correct": true, "explanation": "正确：“研究领域”指一个人专门研究的那一类事，与“海洋生物”相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，不能说“我的体重是海洋生物”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不指一个人研究的范围，不能与“海洋生物”等同。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是个人品质，不能用“是海洋生物”来说明。"}], "explanations": {"研究领域": "正确：“研究领域”指一个人专门研究的那一类事，与“海洋生物”相符。", "体重": "体貌：体重是人的身体特征，不能说“我的体重是海洋生物”。", "工资": "语义：工资是收入，不指一个人研究的范围，不能与“海洋生物”等同。", "性格": "语义：性格是个人品质，不能用“是海洋生物”来说明。"}, "sentence_index": 0, "correct_answer": "研究领域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验把老鼠当成了研究领域。", "explanation": "这里应该用〈研究对象〉。研究领域指研究的范围，实验研究的是老鼠这类对象，要说“研究对象”。"}, {"text": "我们用新的研究领域分析了数据。", "explanation": "这里应该用〈研究方法〉。研究领域是研究的范围，不是分析数据的手段，要说“研究方法”。"}, {"text": "他每天早上在研究领域跑步。", "explanation": "这里应该用〈操场〉。研究领域指专门研究的范围，不是可以跑步的场所，应说“操场”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90113, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究领域", "is_correct": true, "explanation": "正确：“在……里努力工作”要接场所或领域，“研究领域”符合句意。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：“在……里努力工作”要接场所或领域，“睡眠”不是可以工作的地方，不通。"}, {"text": "感情", "is_correct": false, "explanation": "语义：感情是心理状态，不是能够努力工作的场所，句子不成立。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不能作为工作的范围。"}], "explanations": {"研究领域": "正确：“在……里努力工作”要接场所或领域，“研究领域”符合句意。", "睡眠": "语义：“在……里努力工作”要接场所或领域，“睡眠”不是可以工作的地方，不通。", "感情": "语义：感情是心理状态，不是能够努力工作的场所，句子不成立。", "身高": "体貌：身高是外形特征，不能作为工作的范围。"}, "sentence_index": 6, "correct_answer": "研究领域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的研究领域发表在国际期刊上。", "explanation": "这里应该用〈论文〉。研究领域是范围，不能被“发表”，发表的是论文。"}, {"text": "三个研究领域在实验室里工作。", "explanation": "这里应该用〈研究人员〉。研究领域是抽象的范围，不能指人，也不能“在实验室里工作”。"}, {"text": "这个研究领域获得了一等奖。", "explanation": "这里应该用〈研究成果〉。研究领域是范围，不能获奖，获奖的是研究成果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一条新的研究领域，正在学习人工智能。", "corrected_sentence": "她有一个新的研究领域，正在学习人工智能。", "error_description": "量词用错：“研究领域”应该用量词“个”，不能用“条”。应为“一个新的研究领域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90113, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在自己的研究领域们里很有名。", "corrected_sentence": "她在自己的研究领域里很有名。", "error_description": "词缀用错：“们”只用于指人，“研究领域”不是人，不能加“们”，应为“她在自己的研究领域里很有名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
