INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90114, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学者进行研究的专门范围或方向。", "primary_collocate": null, "pronunciation": "yán jiū lǐng yù", "ipa": "jɛn˧˥ tɕjoʊ˥ liŋ˨˩˦ y˥˩", "syllable_count": 4, "sentences": [{"text": "这个研究领域最近发展得很快。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学是一个很大的研究领域。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言学是他们学院的重要研究领域。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究领域需要很多年轻人。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的研究领域常常出现在不同学科之间。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，学者们谈了各个研究领域的新发现。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气候变化成了科学家关注的研究领域。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有很多不同的研究领域。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个研究领域的论文越来越多。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人工智能这个研究领域吸引了很多学者。", "target_word": "研究领域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "研究領域", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学界划分出的专门研究范围或方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研究领域", "is_correct": true, "explanation": "正确：“研究领域”指学者研究的专门范围，能够“发展得很快”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是外形特征，不会“发展得很快”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是收入，不能说“发展得很快”。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“发展”不搭配“味道”，“味道发展得很快”不通。"}], "explanations": {"研究领域": "正确：“研究领域”指学者研究的专门范围，能够“发展得很快”。", "身高": "体貌：身高是外形特征，不会“发展得很快”。", "工资": "语义：工资是收入，不能说“发展得很快”。", "味道": "搭配：“发展”不搭配“味道”，“味道发展得很快”不通。"}, "sentence_index": 0, "correct_answer": "研究领域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次研究把老年人当成了研究领域。", "explanation": "这里应该用〈研究对象〉。研究领域是研究的范围，研究的是老年人这类对象，要说“研究对象”。"}, {"text": "我们采用了问卷调查这种研究领域。", "explanation": "这里应该用〈研究方法〉。问卷调查是方法，研究领域是范围，不能作为方法来用。"}, {"text": "这项研究得到了大量研究领域。", "explanation": "这里应该用〈研究经费〉。经费是钱，研究领域是范围，不能“得到”大量的研究领域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研究领域", "is_correct": true, "explanation": "正确：“科学家关注的”后接的是学者研究的范围，“研究领域”符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是科学家关注的研究范围，句子不通。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是携带的物品，不指研究的范围。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“关注的”后接的应是抽象事物或研究对象，“冰箱”不能作为科学家关注的研究范围。"}], "explanations": {"研究领域": "正确：“科学家关注的”后接的是学者研究的范围，“研究领域”符合句意。", "饮料": "语义：饮料不是科学家关注的研究范围，句子不通。", "行李": "语义：行李是携带的物品，不指研究的范围。", "冰箱": "搭配：“关注的”后接的应是抽象事物或研究对象，“冰箱”不能作为科学家关注的研究范围。"}, "sentence_index": 6, "correct_answer": "研究领域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个研究领域刊登在学术期刊的首页上。", "explanation": "这里应该用〈论文〉。研究领域是范围，不能被“刊登”，刊登的是论文。"}, {"text": "三个研究领域在实验室里做实验。", "explanation": "这里应该用〈研究人员〉。研究领域是抽象的范围，不能指人，也不能做实验。"}, {"text": "这个研究领域获得了今年的一等奖。", "explanation": "这里应该用〈研究成果〉。研究领域是范围，不能获奖，获奖的是研究成果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所学校新开了一条研究领域，专门研究能源。", "corrected_sentence": "这所学校新开了一个研究领域，专门研究能源。", "error_description": "量词用错：“研究领域”应该用量词“个”，不能用“条”。应为“一个研究领域”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些研究领域们都需要年轻人。", "corrected_sentence": "这些研究领域都需要年轻人。", "error_description": "词缀用错：“们”只用于指人，“研究领域”不是人，不能加“们”，应为“这些研究领域”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
