INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "保护国家不让坏人伤害，让大家平安。", "primary_collocate": null, "pronunciation": "guó jiā ān quán", "ipa": "ku̯o˧˥ tɕja˥ an˥ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "保护国家安全，人人有责。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察的工作和国家安全有关。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在为国家安全工作。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些人员负责维护国家安全。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了国家安全的重要性。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了国家安全日夜值守。", "target_word": "国家安全", "complexity_tier": "T3", "furigana": "tā men wèi le guó jiā ān quán rì yè zhí shǒu", "sentence_source": "generated"}, {"text": "我们要提高国家安全的意识。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家安全需要大家一起保护。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了国家安全教育课。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他决心守护国家安全，当了兵。", "target_word": "国家安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國家安全", "label": "繁体"}], "register": "正式", "sense_fingerprint": "保护国家、防止坏人破坏、让大家平安的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家安全", "is_correct": true, "explanation": "正确。「保护国家安全」是动宾结构，「国家安全」作宾语，符合句意。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：「保护」要求对象可以被保护，「午饭」是吃的东西，不能说「保护午饭」。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，人们不需要也无法「保护」它，与「人人有责」的语境不符。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：「生日」是日子，不能作为「保护」的对象。"}], "explanations": {"国家安全": "正确。「保护国家安全」是动宾结构，「国家安全」作宾语，符合句意。", "午饭": "搭配：「保护」要求对象可以被保护，「午饭」是吃的东西，不能说「保护午饭」。", "天气": "语义：天气是自然现象，人们不需要也无法「保护」它，与「人人有责」的语境不符。", "生日": "搭配：「生日」是日子，不能作为「保护」的对象。"}, "sentence_index": 0, "correct_answer": "国家安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很注意国家安全，出门总是小心。", "explanation": "这里应该用〈人身安全〉。「国家安全」指国家层面的保卫工作，个人出门的安全要用〈人身安全〉。"}, {"text": "这家超市很重视国家安全，每天都检查货架。", "explanation": "这里应该用〈食品安全〉。「国家安全」指国家层面，超市的食品卫生与货物质量要用〈食品安全〉。"}, {"text": "这个城市的国家安全很好，市民很放心。", "explanation": "这里应该用〈治安〉。「国家安全」指全国层面，描述一座城市的秩序要用〈治安〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家安全", "is_correct": true, "explanation": "正确。「提高」与「意识」搭配，「国家安全」是意识的对象，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「意识」的对象应是事情或问题，「厨房」是场所，不能作为「提高意识」的内容。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「意识」一般不与具体物件搭配，不能说「钢琴的意识」。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：「玻璃」是材料，不是需要被提高认识的对象，句意不通。"}], "explanations": {"国家安全": "正确。「提高」与「意识」搭配，「国家安全」是意识的对象，符合句意。", "厨房": "语义：「意识」的对象应是事情或问题，「厨房」是场所，不能作为「提高意识」的内容。", "钢琴": "搭配：「意识」一般不与具体物件搭配，不能说「钢琴的意识」。", "玻璃": "语义：「玻璃」是材料，不是需要被提高认识的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "国家安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机开车时要重视国家安全，不能超速。", "explanation": "这里应该用〈交通安全〉。「国家安全」指国家层面的保卫工作，行车过程中的安全要用〈交通安全〉。"}, {"text": "我们学校的国家安全一直很好。", "explanation": "这里应该用〈校园安全〉。「国家安全」指全国层面，描述一所学校的状况要用〈校园安全〉。"}, {"text": "这个小区的国家安全达标，大家都放心。", "explanation": "这里应该用〈治安〉。「国家安全」指国家层面，小区的秩序状况要用〈治安〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要守护得国家安全。", "corrected_sentence": "我们要守护好国家安全。", "error_description": "错误形式「守护得国家安全」；正确形式「守护好国家安全」。「得」后须接补语，表示结果的「好」应直接放在动词后作结果补语，「守护得」不能直接带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经维修过国家安全。", "corrected_sentence": "他们曾经维护过国家安全。", "error_description": "错误形式「维修国家安全」；正确形式「维护国家安全」。「维修」用于机器、设施等具体物品，保护国家的安全状态应说「维护」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
