INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东北是东和北中间的方向。", "primary_collocate": null, "pronunciation": "dōng běi", "ipa": "tʊŋ˥ peɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "指南针的针指向北，东北在它的右边。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，东北在东和北的中间。", "target_word": "东北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家在学校的东北，走路十分钟。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从东北吹来，今天有点冷。", "target_word": "东北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你往东北走，那里有一个公园。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行在十字路口的东北角。", "target_word": "东北", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着东北，说那边有座山。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北在上，东在右，东北在右上方。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船向东北开去，很快就看不见了。", "target_word": "东北", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院在车站东北，不太远。", "target_word": "东北", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "东北方", "label": "复合"}, {"form": "东北角", "label": "复合"}], "register": "中性", "sense_fingerprint": "东和北之间的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "东北", "is_correct": true, "explanation": "正确。指南针指北，它的右边正是东和北之间的东北方向。"}, {"text": "西北", "is_correct": false, "explanation": "语义：针指向北时，西北在左边，不在右边，句意与方位不符。"}, {"text": "南边", "is_correct": false, "explanation": "语义：针指向北，南边在身后，不可能在它的右边。"}, {"text": "北", "is_correct": false, "explanation": "语义：针指向北，北就在针所指的前方，不在它的右边，句意与方位不符。"}], "explanations": {"东北": "正确。指南针指北，它的右边正是东和北之间的东北方向。", "西北": "语义：针指向北时，西北在左边，不在右边，句意与方位不符。", "南边": "语义：针指向北，南边在身后，不可能在它的右边。", "北": "语义：针指向北，北就在针所指的前方，不在它的右边，句意与方位不符。"}, "sentence_index": 0, "correct_answer": "东北"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从学校出发往东北走了十分钟，却到了学校的西南门。", "explanation": "“往东北走”是朝东北方向移动，不可能走到学校西南方向的门。此处误把“东北”当作相反方向的意思。"}, {"text": "我家在学校的东北，可是爸爸说我家在学校的正南。", "explanation": "同一地点不能既在东北又在正南。“东北”表示的方位与后文相矛盾，误用了它的方位意思。"}, {"text": "这个湖在城市的东北，我们一直往西南走才找到它。", "explanation": "湖若在城市东北，就应往东北方向去。此处“往西南走”与“东北”的方位相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "东北", "is_correct": true, "explanation": "正确。“看着东北，说那边有座山”：看的是方向，那边有山，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“看着”后接可见的事物，“空气”看不见，不能说“看着空气”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”是用耳朵听的对象，不能说“看着声音”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度看不见，且与“说那边有座山”的语境无关，句意不通。"}], "explanations": {"东北": "正确。“看着东北，说那边有座山”：看的是方向，那边有山，句意通顺。", "空气": "搭配：“看着”后接可见的事物，“空气”看不见，不能说“看着空气”。", "声音": "搭配：“声音”是用耳朵听的对象，不能说“看着声音”。", "温度": "语义：温度看不见，且与“说那边有座山”的语境无关，句意不通。"}, "sentence_index": 6, "correct_answer": "东北"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我面朝东北坐着，背后就是东北。", "explanation": "面朝东北时，背后应是西南，不可能也是东北。此处“东北”的方位前后矛盾，误用了它的方向意思。"}, {"text": "东北在北，东在右，东北却在右下方。", "explanation": "东北应在右上方，位于东和北之间。此处把“东北”放到右下方，与它的方位意思相矛盾。"}, {"text": "房间的东北角放着床，床却在房间的西南角。", "explanation": "同一张床不能既在东北角又在西南角。此处“东北角”的方位与后文矛盾，误用了它的方位意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他东北走了十分钟。", "corrected_sentence": "他往东北走了十分钟。", "error_description": "错误：“东北”前缺少介词“往”。“东北”作方向，表示走的方向时要用“往”或“向”引出，应说“往东北走”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷风东北吹来，把窗户吹开了。", "corrected_sentence": "冷风从东北吹来，把窗户吹开了。", "error_description": "错误：“东北”前缺少介词“从”。表示风的来向要用“从”引出，应说“从东北吹来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
