INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物的起因或来历。", "primary_collocate": null, "pronunciation": "yóu lái", "ipa": "joʊ˧˥ laɪ˧˥", "syllable_count": 2, "sentences": [{"text": "你知道春节的由来吗？", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个名字有一个有趣的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们讲了端午节的由来。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街的名字有什么由来？", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶知道这道菜的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词语的由来很有意思。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解这个习惯的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里写了这座桥的由来。", "target_word": "由来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说不清这个故事的由来。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个节日的由来，大家都不太清楚。", "target_word": "由来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "事物的起因或来历", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c16745d-ee73-4b44-8e65-a27eab05b8e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确答案。读作 yóu lái（第二声），意思是事物的起因或来历。"}, {"text": "又来", "is_correct": false, "explanation": "yòu lái（第四声）与 yóu lái（第二声）只有第一个音节声调不同，意思是“再来、又来”，与题目词义无关。"}, {"text": "有赖", "is_correct": false, "explanation": "yǒu lài 与 yóu lái 两个音节的声调都不同，意思是“依靠”，不是起因或来历。"}, {"text": "游览", "is_correct": false, "explanation": "lǎn（第三声）与 lái（第二声）韵母不同（ai 与 an），意思是“参观游玩”。"}], "explanations": {"由来": "正确答案。读作 yóu lái（第二声），意思是事物的起因或来历。", "又来": "yòu lái（第四声）与 yóu lái（第二声）只有第一个音节声调不同，意思是“再来、又来”，与题目词义无关。", "有赖": "yǒu lài 与 yóu lái 两个音节的声调都不同，意思是“依靠”，不是起因或来历。", "游览": "lǎn（第三声）与 lái（第二声）韵母不同（ai 与 an），意思是“参观游玩”。"}, "sentence_index": null, "correct_answer": "由来"}, "level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确：由来指事物的起因或来历，可以说“春节的由来”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”只用于商品或服务，不能说“春节的价格”。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人或有形事物的外形，春节不能说外貌。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，只用于问别人的名字，用在这里语域不对，也不指来历。"}], "explanations": {"由来": "正确：由来指事物的起因或来历，可以说“春节的由来”。", "价格": "语义：“价格”只用于商品或服务，不能说“春节的价格”。", "外貌": "体貌：“外貌”指人或有形事物的外形，春节不能说外貌。", "芳名": "语域：“芳名”是敬辞，只用于问别人的名字，用在这里语域不对，也不指来历。"}, "sentence_index": 0, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的由来很好。", "explanation": "这里应该用〈心情〉。由来指事物的起因或来历，不能用来描述人的心情好坏；说心情要用“心情”。"}, {"text": "他没来上课的由来是蓝色的。", "explanation": "这里不成立。由来指事物的起因或来历，不能说它是什么颜色。"}, {"text": "这次旅行是我最难忘的由来。", "explanation": "这里应该用〈经历〉。由来指事物的起因或来历，不指个人亲身遭遇过的事；说“最难忘的经历”要用“经历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "由来", "is_correct": true, "explanation": "正确：由来指习惯的起因或来历，可以说“这个习惯的由来”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指人或物的重量，习惯没有体重，这里说不通。"}, {"text": "尊姓", "is_correct": false, "explanation": "语域：“尊姓”是敬辞，只用于问人的姓氏，不能用来问习惯的来历。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的体态特征，习惯没有身高，这里不成立。"}], "explanations": {"由来": "正确：由来指习惯的起因或来历，可以说“这个习惯的由来”。", "体重": "语义：“体重”指人或物的重量，习惯没有体重，这里说不通。", "尊姓": "语域：“尊姓”是敬辞，只用于问人的姓氏，不能用来问习惯的来历。", "身高": "体貌：“身高”是人的体态特征，习惯没有身高，这里不成立。"}, "sentence_index": 6, "correct_answer": "由来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他说话的由来很大声。", "explanation": "这里应该用〈音量〉。由来指事物的起因或来历，不指说话的音量；说音量大小要用“音量”。"}, {"text": "这件衣服的由来很亮。", "explanation": "这里应该用〈外观〉。由来指事物的起因或来历，不能用来描述衣服亮不亮这类外观。"}, {"text": "这次比赛的由来是我们赢了。", "explanation": "这里应该用〈结果〉。由来指事物的起因或来历，不指事情最后的结果；说比赛的结果要用“结果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街的名字有一个奇怪由来。", "corrected_sentence": "这条街的名字有一个奇怪的由来。", "error_description": "“奇怪”和“由来”之间漏了结构助词“的”。形容词修饰名词时要用“的”，应说“奇怪的由来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人们都很清楚这个节日的了由来。", "corrected_sentence": "老人们都很清楚这个节日的由来。", "error_description": "“了”不能插在定语“的”和“由来”之间，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违背", "is_correct": true, "explanation": "正确：违背指不一致、不遵守，与“符合”意思相反，是它的反义词。"}, {"text": "具备", "is_correct": false, "explanation": "具备指拥有某种条件，与“符合”的意思不相反，不是反义词。"}, {"text": "存在", "is_correct": false, "explanation": "存在指客观上有，与“符合”的意思不相反，不是反义词。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与“符合”的意思不相反，不是反义词。"}], "correct_answer": "违背", "explanations": {"违背": "正确：违背指不一致、不遵守，与“符合”意思相反，是它的反义词。", "具备": "具备指拥有某种条件，与“符合”的意思不相反，不是反义词。", "存在": "存在指客观上有，与“符合”的意思不相反，不是反义词。", "讨论": "讨论指交换意见，与“符合”的意思不相反，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "违反", "is_correct": true, "explanation": "正确：违反指不遵守规定或条件，与“符合”意思相反，是它的反义词。"}, {"text": "登记", "is_correct": false, "explanation": "登记指把情况记录下来，与“符合”的意思不相反，不是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "散步指随意走动，与“符合”的意思不相反，不是反义词。"}, {"text": "失踪", "is_correct": false, "explanation": "失踪指下落不明，与“符合”的意思不相反，不是反义词。"}], "correct_answer": "违反", "explanations": {"违反": "正确：违反指不遵守规定或条件，与“符合”意思相反，是它的反义词。", "登记": "登记指把情况记录下来，与“符合”的意思不相反，不是反义词。", "散步": "散步指随意走动，与“符合”的意思不相反，不是反义词。", "失踪": "失踪指下落不明，与“符合”的意思不相反，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "符合是跟要求一样,合得上。", "primary_collocate": null, "pronunciation": "fú hé", "ipa": "fu˧˥ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房子符合我们的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩符合学校的条件。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服的大小符合我的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说的话不符合事实。", "target_word": "符合", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法符合大家的想法。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的年龄符合比赛的要求。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店的菜符合我的口味。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说我的作业符合要求了。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做不符合学校的规定。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我找了很久，才找到符合条件的房子。", "target_word": "符合", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "符合了", "label": "体标"}, {"form": "符合过", "label": "体标"}], "register": "中性", "sense_fingerprint": "与要求相合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36c33a4a-e234-4e15-897c-30965f67ead3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：符合 fú hé，即题目所给词。"}, {"text": "复合", "is_correct": false, "explanation": "fù 与 fú 声调不同（第四声与第二声），意思是由几部分组成，不是“相合”。"}, {"text": "附和", "is_correct": false, "explanation": "fù hè 与 fú hé 两个音节声调都不同，意思是跟着别人表态。"}, {"text": "符号", "is_correct": false, "explanation": "hào 与 hé 的韵母和声调都不同（ao 与 e，第四声与第二声），意思是记号。"}], "explanations": {"符合": "正确：符合 fú hé，即题目所给词。", "复合": "fù 与 fú 声调不同（第四声与第二声），意思是由几部分组成，不是“相合”。", "附和": "fù hè 与 fú hé 两个音节声调都不同，意思是跟着别人表态。", "符号": "hào 与 hé 的韵母和声调都不同（ao 与 e，第四声与第二声），意思是记号。"}, "sentence_index": null, "correct_answer": "符合"}, "level_3": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：“这个房子符合我们的要求”，表示与要求相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：房子没有感情，不能喜欢“要求”，“这个房子喜欢我们的要求”说不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“要求”搭配。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”不能带“我们的要求”作宾语。"}], "explanations": {"符合": "正确：“这个房子符合我们的要求”，表示与要求相合。", "喜欢": "语义：房子没有感情，不能喜欢“要求”，“这个房子喜欢我们的要求”说不通。", "吃": "搭配：“吃”不能与“要求”搭配。", "满意": "配价：“满意”不能带“我们的要求”作宾语。"}, "sentence_index": 0, "correct_answer": "符合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母符合了我的计划。", "explanation": "这里应该用〈同意〉。符合表示与标准、要求相合，对人的赞同要用“同意”。"}, {"text": "我在路上符合了老朋友。", "explanation": "这里应该用〈遇见〉。符合只能接标准、要求，不能接人。"}, {"text": "我很符合这本书。", "explanation": "这里应该用〈喜欢〉。符合不表示对事物的喜爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符合", "is_correct": true, "explanation": "正确：“这家饭店的菜符合我的口味”，表示与口味一致。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能与“口味”搭配。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：菜没有感情，不能讨厌人的口味。"}, {"text": "猜", "is_correct": false, "explanation": "语义：菜不会猜测，“猜”的主体必须是人。"}], "explanations": {"符合": "正确：“这家饭店的菜符合我的口味”，表示与口味一致。", "批评": "搭配：“批评”的对象是人或行为，不能与“口味”搭配。", "讨厌": "语义：菜没有感情，不能讨厌人的口味。", "猜": "语义：菜不会猜测，“猜”的主体必须是人。"}, "sentence_index": 6, "correct_answer": "符合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快符合了新环境。", "explanation": "这里应该用〈适应〉。符合表示与标准一致，人对环境的适应要用“适应”。"}, {"text": "我们符合了比赛。", "explanation": "这里应该用〈参加〉。符合不能接活动，参与比赛要用“参加”。"}, {"text": "我们明天在车站符合。", "explanation": "这里应该用〈见面〉。符合不能表示人与人相见，应说“见面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告符合着公司的格式。", "corrected_sentence": "这份报告符合公司的格式。", "error_description": "错误：“符合”后加了“着”。“着”表示动作或状态的持续，而“符合”是表示与要求相合的动词，一般不与“着”连用。正确应为“符合公司的格式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统符合得安全标准。", "corrected_sentence": "这套系统符合安全标准。", "error_description": "错误：“符合”是及物动词，后面直接带宾语，中间不能加“得”。正确应为“符合安全标准”；“得”只用于“符合得很好”这类补语结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9288f865-fe4b-4c74-a4ce-91393ddf6af8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
