INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "观看表演、比赛等的人。", "primary_collocate": null, "pronunciation": "guān zhòng", "ipa": "kwan˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这场比赛的观众非常多。", "target_word": "观众", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众为中国队大声加油。", "target_word": "观众", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出时，请观众关上手机。", "target_word": "观众", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一位有经验的演员，不怕面对观众。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完表演，观众们拍手叫好。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视机前的观众朋友们，晚上好！", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛进行到最后，观众都很激动。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部话剧让很多观众哭了。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众一进门，工作人员就给了他们节目单。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请一位观众上台和演员玩游戏。", "target_word": "观众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "观众席", "label": "复合"}], "register": "通用", "sense_fingerprint": "观看表演、比赛等的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c16745d-ee73-4b44-8e65-a27eab05b8e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观众", "is_correct": true, "explanation": "正确：观众指看比赛的人，可以说“观众非常多”。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”说高低，不能用“非常多”来形容价格。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”说高矮，不能用“非常多”来形容。"}, {"text": "芳名", "is_correct": false, "explanation": "语域：“芳名”是敬辞，只用于问人的名字，不能用在比赛上。"}], "explanations": {"观众": "正确：观众指看比赛的人，可以说“观众非常多”。", "价格": "搭配：“价格”说高低，不能用“非常多”来形容价格。", "身高": "搭配：“身高”说高矮，不能用“非常多”来形容。", "芳名": "语域：“芳名”是敬辞，只用于问人的名字，不能用在比赛上。"}, "sentence_index": 0, "correct_answer": "观众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "讲座结束后，观众提出了很多问题。", "explanation": "这里应该用〈听众〉。观众指看表演、比赛的人，听讲座、报告的人用“听众”。"}, {"text": "景区里来了很多观众。", "explanation": "这里应该用〈游客〉。观众指看表演、比赛的人，到景区游览的人用“游客”。"}, {"text": "公交车上坐满了观众。", "explanation": "这里应该用〈乘客〉。观众指看表演、比赛的人，乘车的人用“乘客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观众", "is_correct": true, "explanation": "正确：观众指看比赛的人，比赛进行到最后时观众会很激动。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：“草坪”是地面草地，不会激动，这句说不通。"}, {"text": "尊驾", "is_correct": false, "explanation": "语域：“尊驾”是敬辞，用来称呼客人，用在这里语域不对。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”指重量，不会激动，这句说不通。"}], "explanations": {"观众": "正确：观众指看比赛的人，比赛进行到最后时观众会很激动。", "草坪": "语义：“草坪”是地面草地，不会激动，这句说不通。", "尊驾": "语域：“尊驾”是敬辞，用来称呼客人，用在这里语域不对。", "体重": "语义：“体重”指重量，不会激动，这句说不通。"}, "sentence_index": 6, "correct_answer": "观众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的观众很多。", "explanation": "这里应该用〈读者〉。观众指看表演、比赛的人，阅读书的人用“读者”。"}, {"text": "超市里观众很多。", "explanation": "这里应该用〈顾客〉。观众指看表演、比赛的人，在超市购物的人用“顾客”。"}, {"text": "医院里来了很多观众。", "explanation": "这里应该用〈病人〉。观众指看表演、比赛的人，到医院就诊的人用“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演出的一只观众都很安静。", "corrected_sentence": "这场演出的观众都很安静。", "error_description": "多加了“一只”。“只”是错误的量词，观众是人，不能用“只”计量；这里直接说“观众”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师请一位观众们上台。", "corrected_sentence": "老师请一位观众上台。", "error_description": "“们”不能用在带数量词的名词后面。“一位观众”已表示单数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46522ee1-d75f-4836-a52a-093b7eb3a775') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
