INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不出声地轻轻笑。", "primary_collocate": null, "pronunciation": "wēi xiào", "ipa": "weɪ˥ ɕjɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她看着我，轻轻地微笑。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师听了，没说话，只是微笑。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他安静地坐着，对大家微笑。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩看见妈妈，开心地微笑了。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里不能大声笑，只能微笑。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他接过礼物，不好意思地微笑。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生一直微笑，病人也不怕了。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到好消息，她没笑出声，只微笑着点头。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朝他微笑，他也朝我点点头。", "target_word": "微笑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在门口微笑着等我回家。", "target_word": "微笑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微笑了", "label": "完成体"}, {"form": "微笑着", "label": "持续体"}, {"form": "微笑过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不出声、轻轻地笑，表达友好、平静或不好意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781f7237-455d-43e9-a284-e6dad8f125c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大笑", "is_correct": false, "explanation": "语义：大笑声音大，与“轻轻地”的方式相反。"}, {"text": "微笑", "is_correct": true, "explanation": "正确。微笑不出声，与“轻轻地”的动作相符。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：咆哮是怒吼般的大声，与“轻轻地”冲突。"}, {"text": "嚎啕", "is_correct": false, "explanation": "搭配：“轻轻地”不与“嚎啕”搭配，嚎啕指放声大哭。"}], "explanations": {"大笑": "语义：大笑声音大，与“轻轻地”的方式相反。", "微笑": "正确。微笑不出声，与“轻轻地”的动作相符。", "咆哮": "语义：咆哮是怒吼般的大声，与“轻轻地”冲突。", "嚎啕": "搭配：“轻轻地”不与“嚎啕”搭配，嚎啕指放声大哭。"}, "sentence_index": 0, "correct_answer": "微笑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子听完笑话，哈哈微笑起来。", "explanation": "语义：“微笑”不出声，不能与拟声词“哈哈”搭配，这里应用〈大笑〉。"}, {"text": "他被逗得不停地微笑出声。", "explanation": "语义：“微笑”本身不出声，不能说“微笑出声”，这里应用〈笑出声〉。"}, {"text": "台上的人放声微笑，台下的观众都愣住了。", "explanation": "语义：“微笑”本身不出声，与“放声”的大声相冲突，这里应用〈大笑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭泣", "is_correct": false, "explanation": "语义：医生哭泣会让病人更紧张，与“病人也不怕了”的结果相反。"}, {"text": "微笑", "is_correct": true, "explanation": "正确。医生一直微笑，能让病人安心，与“病人也不怕了”相符。"}, {"text": "怒吼", "is_correct": false, "explanation": "语义：怒吼会吓到病人，与“病人也不怕了”的结果矛盾。"}, {"text": "发抖", "is_correct": false, "explanation": "体貌：发抖是身体紧张的表现，不符合医生稳定安抚病人的形象。"}], "explanations": {"哭泣": "语义：医生哭泣会让病人更紧张，与“病人也不怕了”的结果相反。", "微笑": "正确。医生一直微笑，能让病人安心，与“病人也不怕了”相符。", "怒吼": "语义：怒吼会吓到病人，与“病人也不怕了”的结果矛盾。", "发抖": "体貌：发抖是身体紧张的表现，不符合医生稳定安抚病人的形象。"}, "sentence_index": 6, "correct_answer": "微笑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了我的话，冷冷地微笑了一声。", "explanation": "语义：“微笑”不出声，不能用“一声”计量，这里说的是有声的讥笑，应用〈冷笑〉。"}, {"text": "妈妈在门口咯咯微笑着等我回家。", "explanation": "语义：“咯咯”形容有声的笑，与不出声的“微笑”冲突，这里应用〈咯咯地笑〉。"}, {"text": "妈妈在门口高声微笑着等我回家。", "explanation": "语义：“微笑”不出声，与“高声”的大声相冲突，这里应用〈大笑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他我微笑，然后转身走了。", "corrected_sentence": "他对我微笑，然后转身走了。", "error_description": "错误：“微笑”是不及物动词，不带宾语；引出对象须用介词“对”。这里“我”作对象却漏掉“对”，且句中已有主语“他”，应说“他对我微笑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她微笑了着点了点头，没说话。", "corrected_sentence": "她微笑着点了点头，没说话。", "error_description": "错误：“微笑”后不能同时用“了”和“着”。表示持续状态应只用“着”，写作“微笑着点了点头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
