INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "声音相互呼应，彼此回应。", "primary_collocate": null, "pronunciation": "yìng hè", "ipa": "iŋ˥˩ xɤ˥˩", "syllable_count": 2, "sentences": [{"text": "山谷里，鸟叫声和流水声互相应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处传来钟声，近处的歌声与它相互应和。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一只青蛙先叫，别的青蛙都来应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师弹钢琴，学生的歌声在旁边应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里一只狗叫起来，远处的狗也叫着应和。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的蛙声和树上的蝉声互相应和，很热闹。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一句，台下的观众立刻应和起来。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风吹过竹林，沙沙声与远处的流水声应和着。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱起歌来，树上的小鸟也在应和。", "target_word": "应和", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声响起，笛声马上应和，音乐一下子热闹了。", "target_word": "应和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应和着", "label": "着体标"}, {"form": "应和了", "label": "了体标"}, {"form": "应和过", "label": "过体标"}], "register": "书面", "sense_fingerprint": "应和|声音相互呼应，彼此回应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "应和", "is_correct": true, "explanation": "正确：应和（yìng hè），指声音相互呼应。"}, {"text": "硬核", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。"}, {"text": "迎合", "is_correct": false, "explanation": "yíng（第二声）与 yìng（第四声）声调不同，hé 与 hè 声调也不同，意思是迎合。"}, {"text": "硬盒", "is_correct": false, "explanation": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}], "explanations": {"应和": "正确：应和（yìng hè），指声音相互呼应。", "硬核": "hé（第二声）与 hè（第四声）声调不同，意思是硬核，指核心内容，与应和不同。", "迎合": "yíng（第二声）与 yìng（第四声）声调不同，hé 与 hè 声调也不同，意思是迎合。", "硬盒": "hé（第二声）与 hè（第四声）声调不同，意思是硬质的盒子。"}, "sentence_index": null, "correct_answer": "应和"}, "level_3": {"options": [{"text": "争吵", "is_correct": false, "explanation": "语义：“争吵”指人之间因意见不合而大声吵，鸟叫声和流水声不会争吵。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指声音相互呼应，与“互相”搭配，符合句意。"}, {"text": "对骂", "is_correct": false, "explanation": "语域：“对骂”是口语中很粗的说法，不能用于描写山谷里的声音。"}, {"text": "道歉", "is_correct": false, "explanation": "语义：“道歉”要向人认错，鸟叫声和流水声之间不存在道歉的关系。"}], "explanations": {"争吵": "语义：“争吵”指人之间因意见不合而大声吵，鸟叫声和流水声不会争吵。", "应和": "正确：“应和”指声音相互呼应，与“互相”搭配，符合句意。", "对骂": "语域：“对骂”是口语中很粗的说法，不能用于描写山谷里的声音。", "道歉": "语义：“道歉”要向人认错，鸟叫声和流水声之间不存在道歉的关系。"}, "sentence_index": 0, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把海报应和在墙上，很显眼。", "explanation": "这里应该用〈贴〉。应和指声音相互呼应，把海报贴在墙上要用“贴”。"}, {"text": "这把钥匙和锁应和得很好，一插就开。", "explanation": "这里应该用〈吻合〉。应和指声音相互呼应，钥匙和锁形状相合要用“吻合”。"}, {"text": "他把两张纸应和在一起，很结实。", "explanation": "这里应该用〈粘〉。应和指声音相互呼应，把两张纸粘在一起要用“粘”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撒谎", "is_correct": false, "explanation": "语义：“撒谎”指说假话，观众听到歌声后不会因此撒谎。"}, {"text": "让步", "is_correct": false, "explanation": "语义：“让步”指一方向另一方妥协，台下观众并没有与谁对立。"}, {"text": "应和", "is_correct": true, "explanation": "正确：“应和”指跟着歌声发出声音，与“立刻……起来”搭配，符合句意。"}, {"text": "夸口", "is_correct": false, "explanation": "语域：“夸口”偏口语，且与观众跟着唱的情境不合。"}], "explanations": {"撒谎": "语义：“撒谎”指说假话，观众听到歌声后不会因此撒谎。", "让步": "语义：“让步”指一方向另一方妥协，台下观众并没有与谁对立。", "应和": "正确：“应和”指跟着歌声发出声音，与“立刻……起来”搭配，符合句意。", "夸口": "语域：“夸口”偏口语，且与观众跟着唱的情境不合。"}, "sentence_index": 6, "correct_answer": "应和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把照片应和在本子上，很整齐。", "explanation": "这里应该用〈贴〉。应和指声音相互呼应，把照片贴在本子上要用“贴”。"}, {"text": "两根电线互相应和，把电路接在一起。", "explanation": "这里应该用〈连接〉。应和指声音相互呼应，两个物体接在一起要用“连接”。"}, {"text": "他把两块木板应和在一起，钉得很牢。", "explanation": "这里应该用〈钉〉。应和指声音相互呼应，把木板钉在一起要用“钉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋外的鸟叫声和屋里的歌声互相应和很好。", "corrected_sentence": "屋外的鸟叫声和屋里的歌声互相应和得很好。", "error_description": "错误：动词后的程度补语漏了“得”。动词后带表示程度的补语，要说“动词＋得＋补语”，应说“互相应和得很好”，不能说“互相应和很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这首歌，乐迷们立刻应和下来。", "corrected_sentence": "听到这首歌，乐迷们立刻应和起来。", "error_description": "错误：趋向补语用错。“应和”后面应接“起来”，表示开始并持续，应说“应和起来”，不能说“应和下来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开", "is_correct": true, "explanation": "开：与“合”（闭合）相对，指打开、张开，构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发声歌唱，与“合”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：指移动脚步，与“合”没有反义关系。"}, {"text": "看", "is_correct": false, "explanation": "看：指用眼睛观察，与“合”没有反义关系。"}], "correct_answer": "开", "explanations": {"开": "开：与“合”（闭合）相对，指打开、张开，构成反义。", "唱": "唱：指发声歌唱，与“合”没有反义关系。", "走": "走：指移动脚步，与“合”没有反义关系。", "看": "看：指用眼睛观察，与“合”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "睁", "is_correct": true, "explanation": "睁：指把闭着的眼睛张开，与“合”（闭眼）相反。"}, {"text": "吃", "is_correct": false, "explanation": "吃：指进食，与“合”的闭合义无关，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动，与“合”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔书写，与“合”没有反义关系。"}], "correct_answer": "睁", "explanations": {"睁": "睁：指把闭着的眼睛张开，与“合”（闭眼）相反。", "吃": "吃：指进食，与“合”的闭合义无关，不构成反义。", "跑": "跑：指快速移动，与“合”没有反义关系。", "写": "写：指用笔书写，与“合”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "合是把张开的东西关起来,使其闭拢。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "请把书合上,我们开始上课。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了,花慢慢合起来了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得眼睛一合就睡着了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把嘴合上,不要说话了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子盖太大,合不上。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她合上雨伞,走进了商店。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里,小鸟把翅膀合起来睡觉。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书太厚了,我合不上。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把窗户合上，屋里很安静。", "target_word": "合", "complexity_tier": "T3", "furigana": "tā bǎ chuānghu hé shàng, wūlǐ hěn ānjìng.", "sentence_source": "generated"}, {"text": "他合着眼睛,听了一首歌。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合上", "label": "复合"}, {"form": "合拢", "label": "复合"}, {"form": "合了", "label": "体标"}, {"form": "合着", "label": "体标"}], "register": "中性", "sense_fingerprint": "合:把张开的东西关上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：把张开的东西关上，指闭合。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。"}, {"text": "格", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），格是格子的意思。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}], "explanations": {"合": "合（hé）：把张开的东西关上，指闭合。", "贺": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。", "格": "gé 与 hé 声母不同（g 与 h），格是格子的意思。", "喝": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合上：闭拢，把书合起来，与“开始上课”的语境相合。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写上”指在书上写字，与“请把书……我们开始上课”的关书之意不符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦上”要求擦拭某个表面，“把书擦上”说不通，书本不需要擦。"}, {"text": "点", "is_correct": false, "explanation": "搭配：“点”用于点火、点灯，不能与“书”搭配，“把书点上”不成立。"}], "explanations": {"合": "合上：闭拢，把书合起来，与“开始上课”的语境相合。", "写": "语义：“写上”指在书上写字，与“请把书……我们开始上课”的关书之意不符。", "擦": "搭配：“擦上”要求擦拭某个表面，“把书擦上”说不通，书本不需要擦。", "点": "搭配：“点”用于点火、点灯，不能与“书”搭配，“把书点上”不成立。"}, "sentence_index": 0, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "睡觉前，我把灯合上了。", "explanation": "这里应该用〈关〉。灯要用关上，合用于书、盒子、嘴等能开合的东西。"}, {"text": "出门前，他把衣服合上了。", "explanation": "这里应该用〈扣〉。衣服的纽扣要用扣上，合只用于书、盒子、嘴等能开合的东西。"}, {"text": "施工期间，这条马路被合上了，车辆不能通行。", "explanation": "这里应该用〈封〉。道路要用封，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：把张开的东西关上，指闭合。"}, {"text": "鹤", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，鹤是仙鹤的意思。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}], "explanations": {"合": "合（hé）：把张开的东西关上，指闭合。", "鹤": "hè（第四声）与 hé（第二声）声调不同，鹤是仙鹤的意思。", "咳": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。", "隔": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合起来：收拢，指小鸟把翅膀收拢贴在身上。"}, {"text": "扇", "is_correct": false, "explanation": "语义：“扇起来”是拍动翅膀，小鸟夜里睡觉时不会这样做，与句意不符。"}, {"text": "晃", "is_correct": false, "explanation": "搭配：“晃起来”指摇动，“把翅膀晃起来睡觉”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象要能清洗，不能与“翅膀”搭配，“洗起来睡觉”不成立。"}], "explanations": {"合": "合起来：收拢，指小鸟把翅膀收拢贴在身上。", "扇": "语义：“扇起来”是拍动翅膀，小鸟夜里睡觉时不会这样做，与句意不符。", "晃": "搭配：“晃起来”指摇动，“把翅膀晃起来睡觉”说不通。", "洗": "搭配：“洗”的对象要能清洗，不能与“翅膀”搭配，“洗起来睡觉”不成立。"}, "sentence_index": 6, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里太吵了，他把电视合上，睡了一会儿。", "explanation": "这里应该用〈关〉。电视要用关，合只用于书、盒子、嘴等能开合的东西。"}, {"text": "夜里很冷，他把被子合上睡觉了。", "explanation": "这里应该用〈盖〉。被子要用盖上，合只用于书、盒子等能开合的东西。"}, {"text": "天冷了，他把帽子合上了。", "explanation": "这里应该用〈戴〉。帽子要用戴，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把箱子合了。", "corrected_sentence": "妈妈把箱子合上了。", "error_description": "错误：“把箱子合了”，“把”字句中的动词后缺少结果补语；正确：“把箱子合上了”，“合上”表示闭合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典太厚，我怎么也合不住。", "corrected_sentence": "这本词典太厚，我怎么也合不上。", "error_description": "错误：“合不住”，补语“住”表示牢牢固定，不能用来表示合拢；正确：“合不上”，表示无法合拢，补语“上”表示闭合。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分", "is_correct": true, "explanation": "分：分开、分离，与“合到一起”的聚合义相反，构成反义。"}, {"text": "写", "is_correct": false, "explanation": "写：指用笔书写，与“合”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：指进食，与“合”的聚合义无关，不构成反义。"}, {"text": "跑", "is_correct": false, "explanation": "跑：指快速移动，与“合”没有反义关系。"}], "correct_answer": "分", "explanations": {"分": "分：分开、分离，与“合到一起”的聚合义相反，构成反义。", "写": "写：指用笔书写，与“合”没有反义关系。", "吃": "吃：指进食，与“合”的聚合义无关，不构成反义。", "跑": "跑：指快速移动，与“合”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分", "is_correct": true, "explanation": "分：分开、分离，与“合在一起”相反，构成反义。"}, {"text": "唱", "is_correct": false, "explanation": "唱：指发声歌唱，与“合”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：指露出喜悦的表情或发出笑声，与“合”没有反义关系。"}, {"text": "哭", "is_correct": false, "explanation": "哭：指因悲伤而流泪或出声，与“合”没有反义关系。"}], "correct_answer": "分", "explanations": {"分": "分：分开、分离，与“合在一起”相反，构成反义。", "唱": "唱：指发声歌唱，与“合”没有反义关系。", "笑": "笑：指露出喜悦的表情或发出笑声，与“合”没有反义关系。", "哭": "哭：指因悲伤而流泪或出声，与“合”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "聚拢;结合。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "两只手合在一起,他开始祈祷。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两块木板合在一起,就是一张桌子。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的力量合起来,一定能搬走石头。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两条河在前面合到一起,变成大河。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这两个小盒子合到一起放吧。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人的钱合起来才买了一台电脑。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把两张图合在一起看看。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队人合在一起,一共有五十个人。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司合在一起，力量就更大了。", "target_word": "合", "complexity_tier": "T3", "furigana": "liǎng jiā gōngsī hé zài yìqǐ, lìliang jiù gèng dà le.", "sentence_source": "generated"}, {"text": "两个班合在一起上课,教室太小了。", "target_word": "合", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合起来", "label": "复合"}, {"form": "合在一起", "label": "复合"}, {"form": "合了", "label": "体标"}], "register": "中性", "sense_fingerprint": "合:聚拢、结合在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9b39dce-ffa7-40dd-9acf-f1d2abe1fc96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：聚拢、结合在一起。"}, {"text": "褐", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，褐是褐色的意思。"}, {"text": "革", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），革是皮革、变革的意思。"}, {"text": "咳", "is_correct": false, "explanation": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}], "explanations": {"合": "合（hé）：聚拢、结合在一起。", "褐": "hè（第四声）与 hé（第二声）声调不同，褐是褐色的意思。", "革": "gé 与 hé 声母不同（g 与 h），革是皮革、变革的意思。", "咳": "ké 与 hé 声母不同（k 与 h），咳是咳嗽的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合在一起：聚拢、靠拢成一处，指两只手靠到一起。"}, {"text": "分", "is_correct": false, "explanation": "语义：“分”表示分开，与“在一起”的聚拢义相反，“两只手分在一起”说不通。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”指悬挂，不能与“两只手”搭配，“挂在一起”不成立。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”指抛掷，不能表示两只手聚在一起，“扔在一起”不成立。"}], "explanations": {"合": "合在一起：聚拢、靠拢成一处，指两只手靠到一起。", "分": "语义：“分”表示分开，与“在一起”的聚拢义相反，“两只手分在一起”说不通。", "挂": "搭配：“挂”指悬挂，不能与“两只手”搭配，“挂在一起”不成立。", "扔": "搭配：“扔”指抛掷，不能表示两只手聚在一起，“扔在一起”不成立。"}, "sentence_index": 0, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月都把工资合到老家去。", "explanation": "这里应该用〈汇〉。寄钱要用汇，合表示把东西聚拢在一起，不能说“合到老家”。"}, {"text": "他渴极了，把水合进杯子里一口喝光。", "explanation": "这里应该用〈倒〉。水要用倒，合不能表示把液体注入容器。"}, {"text": "各地的报告都合到了总部。", "explanation": "这里应该用〈汇总〉。报告要用汇总，合只表示把东西拼在一起，不能说“合到总部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "合", "is_correct": true, "explanation": "合（hé）：聚拢、结合在一起。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。"}, {"text": "隔", "is_correct": false, "explanation": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}], "explanations": {"合": "合（hé）：聚拢、结合在一起。", "贺": "hè（第四声）与 hé（第二声）声调不同，贺是祝贺的意思。", "隔": "gé 与 hé 声母不同（g 与 h），隔是隔开的意思。", "喝": "hē（第一声）与 hé（第二声）声调不同，喝是饮用的意思。"}, "sentence_index": null, "correct_answer": "合"}, "level_3": {"options": [{"text": "合", "is_correct": true, "explanation": "合在一起：并列放置，指把两张图靠在一起看。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指撕破，与“放在一起看看”的意思相反，图不能这样处理。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”用于食物，不能与“两张图”搭配，“吃在一起”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能与“两张图”搭配，“喝在一起”不成立。"}], "explanations": {"合": "合在一起：并列放置，指把两张图靠在一起看。", "撕": "语义：“撕”指撕破，与“放在一起看看”的意思相反，图不能这样处理。", "吃": "搭配：“吃”用于食物，不能与“两张图”搭配，“吃在一起”说不通。", "喝": "搭配：“喝”的对象是液体，不能与“两张图”搭配，“喝在一起”不成立。"}, "sentence_index": 6, "correct_answer": "合"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩合成了好朋友。", "explanation": "这里应该用〈结成〉。建立友谊要用结成，合表示把东西拼合在一起，不说“合成朋友”。"}, {"text": "同学们在操场合，然后一起出发。", "explanation": "这里应该用〈集合〉。“合”单用时不表示召集、聚集的意思，人群聚在一起要用集合。"}, {"text": "洗完手，他把水龙头合上了。", "explanation": "这里应该用〈关〉。水龙头要用关上，合只用于书、盒子、嘴等能开合的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家店合在一起，把生意更好了。", "corrected_sentence": "两家店合在一起了，生意更好了。", "error_description": "错误：「把生意更好了」误用「把」字句，「把」后需要处置动词，形容词不能直接作谓语。正确：去掉「把」，说「生意更好了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把两张纸合上一起，装订成一本书。", "corrected_sentence": "把两张纸合在一起，装订成一本书。", "error_description": "错误：“合上一起”，补语“上”表示闭合，不能与“一起”搭配；正确：“合在一起”，表示聚拢到同一处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdf4198-c9e7-4c7b-ac69-1c4cd56fe5fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "读", "is_correct": false, "explanation": "指看着文字发出声音或理解内容，与“插”没有反义关系。"}, {"text": "拔", "is_correct": true, "explanation": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。"}, {"text": "笑", "is_correct": false, "explanation": "指脸上露出高兴的表情或发出笑声，与“插”没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "指迈步前进，与“插”没有反义关系。"}], "correct_answer": "拔", "explanations": {"读": "指看着文字发出声音或理解内容，与“插”没有反义关系。", "拔": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。", "笑": "指脸上露出高兴的表情或发出笑声，与“插”没有反义关系。", "走": "指迈步前进，与“插”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "唱", "is_correct": false, "explanation": "指发出歌声，与“插”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "指快速移动双腿前进，与“插”没有反义关系。"}, {"text": "拔", "is_correct": true, "explanation": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。"}, {"text": "吃", "is_correct": false, "explanation": "指把食物放进嘴里咽下，与“插”没有反义关系。"}], "correct_answer": "拔", "explanations": {"唱": "指发出歌声，与“插”没有反义关系。", "跑": "指快速移动双腿前进，与“插”没有反义关系。", "拔": "指把立在里面的东西抽出来，与“插”的动作相反，是反义词。", "吃": "指把食物放进嘴里咽下，与“插”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把细长的东西放进去，立在里面。", "primary_collocate": null, "pronunciation": "chā", "ipa": "ʈʂʰa˥", "syllable_count": 1, "sentences": [{"text": "她把花插在花瓶里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的花瓶里插着几朵红花。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕上插着六根蜡烛。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在沙滩上插了一面小旗。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不要把筷子插在饭里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在花盆里插了一根小木棍。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山顶上插着一面红旗，很远就能看见。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在地里插了几根竹竿。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把伞插在门口的伞筒里。", "target_word": "插", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在雪地里插了一根树枝。", "target_word": "插", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "插着", "label": "着体标"}, {"form": "插了", "label": "了体标"}, {"form": "插过", "label": "过体标"}, {"form": "插入", "label": "复合词"}], "register": "中性", "sense_fingerprint": "插|把细长的东西放进去并立在里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长的东西放进去并立在里面。"}, {"text": "查", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是检查。"}, {"text": "茶", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。"}, {"text": "擦", "is_correct": false, "explanation": "cā（不送气）与 chā（送气）声母不同，意思是擦拭。"}, {"text": "掺", "is_correct": false, "explanation": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}], "explanations": {"插": "正确：插（chā），指把细长的东西放进去并立在里面。", "查": "chá（第二声）与 chā（第一声）声调不同，意思是检查。", "茶": "chá（第二声）与 chā（第一声）声调不同，意思是茶叶。", "擦": "cā（不送气）与 chā（送气）声母不同，意思是擦拭。", "掺": "chān 与 chā 韵母不同（多一个 -n），意思是掺和。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：“插”指把花放进花瓶里并立住，与“在花瓶里”搭配，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”要加热，花不能煮在花瓶里。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”指把液体倒出，花不是液体，不能倒在花瓶里。"}, {"text": "别", "is_correct": false, "explanation": "搭配：“别”一般接衣服、头发等，不能说“别在花瓶里”。"}], "explanations": {"插": "正确：“插”指把花放进花瓶里并立住，与“在花瓶里”搭配，符合句意。", "煮": "语义：“煮”要加热，花不能煮在花瓶里。", "倒": "语义：“倒”指把液体倒出，花不是液体，不能倒在花瓶里。", "别": "搭配：“别”一般接衣服、头发等，不能说“别在花瓶里”。"}, "sentence_index": 0, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把海报插在墙上，很显眼。", "explanation": "这里应该用〈贴〉。插指把细长的东西放进去并立在里面，海报平贴在墙上要用“贴”。"}, {"text": "他把饼干插在桌子上。", "explanation": "这里应该用〈放〉。插指把细长的东西放进去并立在里面，饼干这类东西放在桌上要用“放”。"}, {"text": "他用笔插了一行字。", "explanation": "这里应该用〈写〉。插指把细长的东西放进去并立在里面，写字要用“写”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "插", "is_correct": true, "explanation": "正确：插（chā），指把细长的东西放进去并立在里面。"}, {"text": "察", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是观察。"}, {"text": "岔", "is_correct": false, "explanation": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。"}, {"text": "搽", "is_correct": false, "explanation": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。"}, {"text": "昌", "is_correct": false, "explanation": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}], "explanations": {"插": "正确：插（chā），指把细长的东西放进去并立在里面。", "察": "chá（第二声）与 chā（第一声）声调不同，意思是观察。", "岔": "chà（第四声）与 chā（第一声）声调不同，意思是岔开、分岔。", "搽": "chá（第二声）与 chā（第一声）声调不同，意思是涂抹。", "昌": "chāng 比 chā 多一个 -ng 韵尾，意思是昌盛。"}, "sentence_index": null, "correct_answer": "插"}, "level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，不能说“挖着一面红旗”。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”要用水清洗东西，与“山顶上”搭不上。"}, {"text": "插", "is_correct": true, "explanation": "正确：“插着”表示红旗立在山顶上的状态，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣服，不能说“穿着一面红旗”。"}], "explanations": {"挖": "语义：“挖”指挖掘，不能说“挖着一面红旗”。", "洗": "语义：“洗”要用水清洗东西，与“山顶上”搭不上。", "插": "正确：“插着”表示红旗立在山顶上的状态，符合句意。", "穿": "搭配：“穿”的对象是衣服，不能说“穿着一面红旗”。"}, "sentence_index": 6, "correct_answer": "插"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士把药膏插在伤口上，很快就好了。", "explanation": "这里应该用〈涂〉。插指把细长的东西放进去并立在里面，药膏抹在伤口上要用“涂”。"}, {"text": "他把水插进瓶子里。", "explanation": "这里应该用〈装〉。插指把细长的东西放进去并立在里面，液体装进容器要用“装”。"}, {"text": "他把衣服插干净了。", "explanation": "这里应该用〈洗〉。插指把细长的东西放进去并立在里面，把衣服弄干净要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在花瓶里着插一束白花。", "corrected_sentence": "她在花瓶里插着一束白花。", "error_description": "错误：“着”的位置不对。表示状态持续的“着”应紧跟动词，要说“插着一束白花”，不能说“着插一束白花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他树枝插在雪地里。", "corrected_sentence": "他把树枝插在雪地里。", "error_description": "错误：“把”字句漏了“把”。“树枝”是被插的东西，要放在“把”后面，应说“他把树枝插在雪地里”，不能说“他树枝插在雪地里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
