INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90199, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "唱歌、跳舞、写故事、画画这些好玩又美的事。", "primary_collocate": null, "pronunciation": "wén yì", "ipa": "wən˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他从小爱搞文艺，又唱歌又画画。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们在公园搞文艺，大家唱歌跳舞。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我女儿喜欢文艺，每天都要唱歌跳舞。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的课外时间都用来搞文艺。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱运动，只爱文艺，天天写故事画画。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，学点文艺，生活会更有意思。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，村里的人聚在一起搞文艺。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对文艺不太在行，不会唱也不会跳。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请同学们说说自己喜欢哪种文艺。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们在教室里搞文艺，真热闹。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文藝", "label": "繁体"}, {"form": "文艺界", "label": "复合"}, {"form": "文艺工作者", "label": "复合"}], "register": "口语", "sense_fingerprint": "文艺：日常说的唱歌、跳舞、画画等好玩又美的活动（口语，常说搞文艺）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781f7237-455d-43e9-a284-e6dad8f125c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文艺", "is_correct": true, "explanation": "“文艺”指唱歌、画画等文娱活动，与后半句“又唱歌又画画”呼应，符合句意。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“搞”后接的应是文娱活动，“西瓜”不是活动，句子说不通。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：“搞”后面接活动类名词，“收入”不能说“搞收入”。"}, {"text": "厕所", "is_correct": false, "explanation": "语义：“搞”后接的应是文娱活动，“厕所”是场所，与“唱歌画画”的语境不符。"}], "explanations": {"文艺": "“文艺”指唱歌、画画等文娱活动，与后半句“又唱歌又画画”呼应，符合句意。", "西瓜": "语义：“搞”后接的应是文娱活动，“西瓜”不是活动，句子说不通。", "收入": "搭配：“搞”后面接活动类名词，“收入”不能说“搞收入”。", "厕所": "语义：“搞”后接的应是文娱活动，“厕所”是场所，与“唱歌画画”的语境不符。"}, "sentence_index": 0, "correct_answer": "文艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在黑板上搞文艺，写了很多字。", "explanation": "“搞文艺”指唱歌、跳舞、写故事、画画这类文娱活动，在黑板上写字属于日常书写，不能说“搞文艺”。"}, {"text": "妈妈在厨房里搞文艺，把衣服洗得很干净。", "explanation": "“搞文艺”指唱歌、跳舞、画画等文娱活动，在厨房里洗衣服属于家务，不能说“搞文艺”。"}, {"text": "他买了一台文艺，回家用来做饭。", "explanation": "这里的“文艺”指唱歌、跳舞等文娱活动，是一种活动，不是可以购买的机器，也不能用量词“台”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文艺", "is_correct": true, "explanation": "“文艺”指唱歌跳舞等娱乐活动，与“过年时聚在一起”的语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“搞”后接的应是文娱活动，“雨伞”是日用品，与“过年时聚在一起”的场景不符。"}, {"text": "眼泪", "is_correct": false, "explanation": "搭配：“搞”不能与“眼泪”搭配，“搞眼泪”不成说法。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“脚印”是足迹，不是活动，“搞脚印”说不通，句子不成立。"}], "explanations": {"文艺": "“文艺”指唱歌跳舞等娱乐活动，与“过年时聚在一起”的语境相符。", "雨伞": "语义：“搞”后接的应是文娱活动，“雨伞”是日用品，与“过年时聚在一起”的场景不符。", "眼泪": "搭配：“搞”不能与“眼泪”搭配，“搞眼泪”不成说法。", "脚印": "语义：“脚印”是足迹，不是活动，“搞脚印”说不通，句子不成立。"}, "sentence_index": 6, "correct_answer": "文艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上在公园搞文艺，主要是跑步和打太极。", "explanation": "这里应该用〈锻炼〉。“搞文艺”指唱歌、跳舞、写故事、画画这类文娱活动，跑步、打太极属于体育锻炼，不属于这一类。"}, {"text": "周末我们去郊外搞文艺，爬山看风景。", "explanation": "这里应该用〈旅行〉。“搞文艺”指唱歌、跳舞、写故事、画画等文娱活动，爬山看风景属于旅游，不能说“搞文艺”。"}, {"text": "上课时，同学们在教室里搞文艺，互相讨论题目。", "explanation": "这里应该用〈学习〉。“搞文艺”指文娱活动，互相讨论题目属于学习，与“搞文艺”的含义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候就喜欢搞了文艺，周末总和朋友一起唱歌。", "corrected_sentence": "我小时候就喜欢搞文艺，周末总和朋友一起唱歌。", "error_description": "错误：“喜欢”表示长期的习惯，“搞文艺”前不能加“了”，应为〈喜欢搞文艺〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学以后，孩子们在院子里搞文艺们，唱歌跳舞。", "corrected_sentence": "放学以后，孩子们在院子里搞文艺，唱歌跳舞。", "error_description": "错误：“们”只用于指人，“文艺”是抽象名词，不能加〈们〉，应为〈搞文艺〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
