INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "文学和艺术的总称。", "primary_collocate": null, "pronunciation": "wén yì", "ipa": "wən˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他一生都在研究文艺。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人热爱文艺，也爱科学。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上有一个专门介绍文艺的版面。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺能让人看到生活中美的东西。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的文艺发展得很快。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他大学时学的是文艺，不是经济。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺和政治有什么关系？", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本杂志专门谈文艺，不谈经济。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家一直很重视文艺的发展。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过很多关于文艺的文章。", "target_word": "文艺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文藝", "label": "繁体"}, {"form": "文艺界", "label": "复合"}, {"form": "文艺工作者", "label": "复合"}], "register": "书面", "sense_fingerprint": "文艺：文学和艺术的总称（书面，指整个文学艺术领域）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781f7237-455d-43e9-a284-e6dad8f125c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文艺", "is_correct": true, "explanation": "“文艺”指文学和艺术的总称，是“研究”的对象，符合句意。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：“研究”的对象是学问或事物，“朋友”是人，不能被研究。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“研究”的宾语应是学问、问题或规律，“门票”不能与“研究”搭配。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“研究”不能跟“生日”这类日子名词搭配。"}], "explanations": {"文艺": "“文艺”指文学和艺术的总称，是“研究”的对象，符合句意。", "朋友": "语义：“研究”的对象是学问或事物，“朋友”是人，不能被研究。", "门票": "搭配：“研究”的宾语应是学问、问题或规律，“门票”不能与“研究”搭配。", "生日": "搭配：“研究”不能跟“生日”这类日子名词搭配。"}, "sentence_index": 0, "correct_answer": "文艺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他穿衣服很文艺，喜欢戴帽子和围巾。", "explanation": "此处“文艺”作形容词，形容穿着有艺术气息，是另一个义项，与本句所指的“文学和艺术的总称”不符，这里不应这样用。"}, {"text": "妈妈喜欢吃文艺，每天晚饭都要吃一点。", "explanation": "“文艺”是抽象名词，不是可以吃的东西；这里应该用〈面条〉。"}, {"text": "我的个子很文艺，已经长到一米八了。", "explanation": "“文艺”不能用来形容身高或身材；这里应该用〈高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文艺", "is_correct": true, "explanation": "“文艺”与“政治”并列，构成“文艺和政治”的问句，符合句意。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：“西瓜”是食物，与“政治”不相关，问句无法成立。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是日用品，与“政治”的关系说不通，句意不合。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：“鞋子”是日用品，与“政治”毫无关系，问句不成立。"}], "explanations": {"文艺": "“文艺”与“政治”并列，构成“文艺和政治”的问句，符合句意。", "西瓜": "语义：“西瓜”是食物，与“政治”不相关，问句无法成立。", "雨伞": "语义：“雨伞”是日用品，与“政治”的关系说不通，句意不合。", "鞋子": "语义：“鞋子”是日用品，与“政治”毫无关系，问句不成立。"}, "sentence_index": 6, "correct_answer": "文艺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都去文艺打篮球。", "explanation": "“文艺”指文学和艺术，不是运动场所；打篮球应去〈体育馆〉。"}, {"text": "这盘菜的文艺太咸了。", "explanation": "“文艺”不能用来说菜的味道；这里应该用〈味道〉。"}, {"text": "我的书包里装着三张文艺。", "explanation": "“文艺”指文学和艺术这一领域，是抽象名词，不能用量词“张”计量；这里的“文艺”不能作为书包里装的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的哥哥是一位文艺。", "corrected_sentence": "他的哥哥是一位文艺工作者。", "error_description": "错误：“文艺”指文学和艺术的总称，是领域名词，不能指从事文艺的人。应使用复合词〈文艺工作者〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在文艺里工作，认识很多作家。", "corrected_sentence": "他在文艺界工作，认识很多作家。", "error_description": "错误：“文艺”指领域，表示在这一领域工作要用复合词〈文艺界〉，“里”不能代替“界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
