INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按设计进行建筑、修建工程。", "primary_collocate": null, "pronunciation": "shī gōng", "ipa": "ʂʅ˥ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "工程队按照图纸施工。", "target_word": "施工", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司必须按设计图施工，不能随便改。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥由三家公司一起施工。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新医院预计明年春天开始施工。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施工前，工程师先检查了设计图。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们严格按照标准施工，所以房子很结实。", "target_word": "施工", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站已经批准施工，下个月就开始。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程队没有按图纸施工，房子出了问题。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程公司要先做好计划，再开始施工。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，这座大楼必须按新标准施工。", "target_word": "施工", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "施工队", "label": "复合词"}, {"form": "施工现场", "label": "复合词"}, {"form": "施工图", "label": "复合词"}], "register": "中性", "sense_fingerprint": "施工|按设计进行建筑、修建工程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "施工", "is_correct": true, "explanation": "正确：施工指按设计进行建造，与“按照图纸”搭配。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做食品，不能按照图纸进行。"}, {"text": "栽培", "is_correct": false, "explanation": "语义：栽培指培育植物，与按图纸的工程无关。"}, {"text": "弹奏", "is_correct": false, "explanation": "语义：弹奏是演奏乐器，与图纸没有关系。"}], "explanations": {"施工": "正确：施工指按设计进行建造，与“按照图纸”搭配。", "烘焙": "语义：烘焙是做食品，不能按照图纸进行。", "栽培": "语义：栽培指培育植物，与按图纸的工程无关。", "弹奏": "语义：弹奏是演奏乐器，与图纸没有关系。"}, "sentence_index": 0, "correct_answer": "施工"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位建筑师施工了这座大楼的图纸。", "explanation": "这里应该用〈设计〉。施工是按图纸进行建造，画出图纸要用设计。"}, {"text": "我每天早上施工一杯咖啡。", "explanation": "这里应该用〈冲泡〉。施工指按设计建造工程，冲泡饮品这类日常活动不能用施工。"}, {"text": "老师施工了这道数学题。", "explanation": "这里应该用〈分析〉。施工指进行工程建设，讲解数学题要用分析。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施工", "is_correct": true, "explanation": "正确：施工指按计划进行工程建设，与“已经批准”“下个月就开始”相合。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是加热食物，与批准的工程无关。"}, {"text": "写作", "is_correct": false, "explanation": "语义：写作是写文章，与地铁站的工程无关。"}, {"text": "编织", "is_correct": false, "explanation": "搭配：“编织”的对象是线、布等，不能说批准编织地铁工程。"}], "explanations": {"施工": "正确：施工指按计划进行工程建设，与“已经批准”“下个月就开始”相合。", "烤": "语义：烤是加热食物，与批准的工程无关。", "写作": "语义：写作是写文章，与地铁站的工程无关。", "编织": "搭配：“编织”的对象是线、布等，不能说批准编织地铁工程。"}, "sentence_index": 6, "correct_answer": "施工"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乐队在广场上施工一首新歌。", "explanation": "这里应该用〈演奏〉。施工指工程建设，演奏乐曲要用演奏。"}, {"text": "译者施工了这本小说。", "explanation": "这里应该用〈翻译〉。施工是建造工程，把小说译成另一种语言要用翻译。"}, {"text": "科学家在实验室施工了一个新理论。", "explanation": "这里应该用〈提出〉。施工指按设计进行建造，提出学说、思想要用提出，不能用施工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工程队正在施工过，明天应该能完成。", "corrected_sentence": "工程队正在施工，明天应该能完成。", "error_description": "错误：“正在……施工过”。“正在”表示动作正在进行，“过”表示曾经发生的经历，二者不能同用。正确：“正在施工”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座大楼施工的完了，可以搬进去住了。", "corrected_sentence": "这座大楼施工完了，可以搬进去住了。", "error_description": "错误：“施工”后多加了“的”。“施工”是动词，后面应直接接结果补语“完”，加“的”会使结构变成名词性的，不通顺。正确：“施工完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
