INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "客户是去商店买东西或找人做事的人。", "primary_collocate": null, "pronunciation": "kè hù", "ipa": "kʰɤ˥˩ xu˥˩", "syllable_count": 2, "sentences": [{"text": "这位客户在商店里买了一件外套。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板正在给客户介绍新手机。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户说这双鞋太小了，想换一双。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的客户大多是附近的居民。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位客户来找我帮他修电脑。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户等了很久，有点儿不高兴。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们店里的老客户。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客户付完钱，店员把东西给了他。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有一位客户想找人帮他画画。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员对每位客户都很客气。", "target_word": "客户", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老客户", "label": "复合"}, {"form": "新客户", "label": "复合"}, {"form": "客戶", "label": "繁体"}], "register": "中性", "sense_fingerprint": "去商店买东西或找人做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fafc2b1a-7f36-4e83-bdbd-e4c78289d12a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90209, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "客户", "is_correct": true, "explanation": "正确答案。客户指去商店买东西或找人做事的人。"}, {"text": "刻苦", "is_correct": false, "explanation": "hù（第四声）与 kǔ（第三声）声母不同，声调也不同，意思是刻苦（用功、吃苦）。"}, {"text": "刻度", "is_correct": false, "explanation": "hù 与 dù 声母不同，声调相同，意思是刻度（量具上的标记）。"}, {"text": "客服", "is_correct": false, "explanation": "hù（第四声）与 fú（第二声）声母不同，声调也不同，意思是客服（为客户提供服务的人员）。"}], "explanations": {"客户": "正确答案。客户指去商店买东西或找人做事的人。", "刻苦": "hù（第四声）与 kǔ（第三声）声母不同，声调也不同，意思是刻苦（用功、吃苦）。", "刻度": "hù 与 dù 声母不同，声调相同，意思是刻度（量具上的标记）。", "客服": "hù（第四声）与 fú（第二声）声母不同，声调也不同，意思是客服（为客户提供服务的人员）。"}, "sentence_index": null, "correct_answer": "客户"}, "level_3": {"options": [{"text": "客户", "is_correct": true, "explanation": "正确。“客户”指去商店买东西的人，与“在商店里买了一件外套”相符。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能独自到商店买衣服。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”不是人，不能去商店买外套。"}, {"text": "幽灵", "is_correct": false, "explanation": "语义：幽灵没有实体，不能在商店里买外套。"}], "explanations": {"客户": "正确。“客户”指去商店买东西的人，与“在商店里买了一件外套”相符。", "婴儿": "语义：婴儿不能独自到商店买衣服。", "月亮": "语义：“月亮”不是人，不能去商店买外套。", "幽灵": "语义：幽灵没有实体，不能在商店里买外套。"}, "sentence_index": 0, "correct_answer": "客户"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "家里来了两位客户，妈妈去厨房做饭。", "explanation": "这里应该用〈客人〉。“客户”指去商店买东西或找人办事的人，到家里做客的人要说客人。"}, {"text": "公交车上来了一位客户，他坐在前排。", "explanation": "这里应该用〈乘客〉。“客户”不指坐车的人，乘车的人要说乘客。"}, {"text": "这位客户每天负责给来店里的顾客修车，技术很好。", "explanation": "这里应该用〈修理工〉。“客户”指找人做事的一方，替人修车的人要说修理工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "客户", "is_correct": true, "explanation": "正确。“老客户”指经常来店里买东西的熟客，与句意相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”不是人，不能说“他是我们店里的老河流”。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”不是人，不能说“他是我们店里的老树叶”。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不是店里的关系，这里的“老病人”与“我们店里的”语境不合。"}], "explanations": {"客户": "正确。“老客户”指经常来店里买东西的熟客，与句意相符。", "河流": "语义：“河流”不是人，不能说“他是我们店里的老河流”。", "树叶": "语义：“树叶”不是人，不能说“他是我们店里的老树叶”。", "病人": "语义：病人不是店里的关系，这里的“老病人”与“我们店里的”语境不合。"}, "sentence_index": 6, "correct_answer": "客户"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们店里来了一只客户，店员很客气地招呼他。", "explanation": "这里应该用〈位〉。“客户”指人，量词要用“位”；“只”多用于动物。"}, {"text": "门口来了一辆客户，正在等店员。", "explanation": "这里应该用〈位〉。“辆”用于车辆，不能用来数“客户”这样的人。"}, {"text": "店里来了一条客户，他想买外套。", "explanation": "这里应该用〈位〉。“条”用于细长的东西，数人要用“位”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位客户们走进店里，想买一双鞋。", "corrected_sentence": "一位客户走进店里，想买一双鞋。", "error_description": "数量词“一位”后的名词不能再加复数标记“们”，应说“一位客户”，不能说“一位客户们”。正确形式是“一位客户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只客户刚付完钱，店员就把包好的鞋递给了他。", "corrected_sentence": "这位客户刚付完钱，店员就把包好的鞋递给了他。", "error_description": "“只”多用于动物，指人应说“这位客户”，量词应为“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac40eb3-d553-49c2-9d11-c56d1d3ee3ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
