INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90219, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可以拿来学习的真实事情。", "primary_collocate": null, "pronunciation": "àn lì", "ipa": "an⁵¹ li⁵¹", "syllable_count": 2, "sentences": [{"text": "书里的每个案例都是真事。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用真实的案例教我们法律。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的经历写成了一个案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们读了这个案例，都很吃惊。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案例是去年在北京发生的。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给新人讲了一个病人的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢从真实案例里学东西。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课本上没有这样的案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案例告诉我们要小心网络骗子。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每周我们学习一个新案例。", "target_word": "案例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个案例", "label": "量词"}, {"form": "案例分析", "label": "复合"}], "register": "中性", "sense_fingerprint": "可用来学习的真实事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "案例", "is_correct": true, "explanation": "正确：案例指可供学习的真实事情，与“都是真事”相合。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与“都是真事”矛盾。"}, {"text": "谜语", "is_correct": false, "explanation": "搭配：谜语是需要猜的题，“真事”不能作谜语的所指。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是收录词语的工具书，不是真实发生的事情。"}], "explanations": {"案例": "正确：案例指可供学习的真实事情，与“都是真事”相合。", "童话": "语义：童话是虚构的故事，与“都是真事”矛盾。", "谜语": "搭配：谜语是需要猜的题，“真事”不能作谜语的所指。", "词典": "语义：词典是收录词语的工具书，不是真实发生的事情。"}, "sentence_index": 0, "correct_answer": "案例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察破获了这起案例。", "explanation": "这里应该用〈案件〉。破获的是刑事案件，案例指可供学习的真实事情。"}, {"text": "这则案例的主角是一只会说话的狐狸。", "explanation": "这里应该用〈寓言〉。寓言是虚构的故事，案例指真实发生、可供学习的事情，不能描述会说话的狐狸。"}, {"text": "这场案例造成了三人受伤。", "explanation": "这里应该用〈事故〉。事故指造成伤亡的意外事件，案例是用来学习的真实事情，不能造成伤亡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "案例", "is_correct": true, "explanation": "正确：案例指可供学习的真实事情，与“真实”“学东西”相合。"}, {"text": "梦境", "is_correct": false, "explanation": "语义：梦境是虚幻的，与“真实”矛盾。"}, {"text": "幻想", "is_correct": false, "explanation": "语义：幻想是不真实的想象，与“真实”矛盾。"}, {"text": "墙壁", "is_correct": false, "explanation": "搭配：“从……里学东西”的“里”后应是可供学习的内容，墙壁不能充当。"}], "explanations": {"案例": "正确：案例指可供学习的真实事情，与“真实”“学东西”相合。", "梦境": "语义：梦境是虚幻的，与“真实”矛盾。", "幻想": "语义：幻想是不真实的想象，与“真实”矛盾。", "墙壁": "搭配：“从……里学东西”的“里”后应是可供学习的内容，墙壁不能充当。"}, "sentence_index": 6, "correct_answer": "案例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场案例下周六举行。", "explanation": "这里应该用〈比赛〉。案例是已经发生的真实事情，不能像比赛那样在将来某个时间举行。"}, {"text": "我们每周吃一个新案例。", "explanation": "案例是可供学习参考的真实事情，不能当作食物吃。"}, {"text": "这个案例非常好听。", "explanation": "案例指真实事情，不是声音，不能用“好听”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们讨论了两案例。", "corrected_sentence": "我们讨论了两个案例。", "error_description": "错误：“两案例”。正确：“两个案例”。数词与名词之间要加量词，“案例”前应加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们读完了很多案例们。", "corrected_sentence": "我们读完了很多案例。", "error_description": "错误：“案例们”。正确：“案例”。“们”不能加在指事物的名词后面，表示复数不用“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
