INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90225, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这件事。", "primary_collocate": null, "pronunciation": "cǐ shì", "ipa": "tsʰɨ²¹⁴ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "此事不能让妈妈知道。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在讨论此事。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会认真考虑此事。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事让他很难过。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来负责此事？", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有跟我说过此事。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事到这里就结束吧。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都很关心此事。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先别急，此事有办法。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师已经回答了我们关于此事的问题。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指眼前或刚说过的这件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90225, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此事", "is_correct": true, "explanation": "此事：指眼前这件事，作主语，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能作为“让妈妈知道”的内容，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被“知道”的秘密，句子不通。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“知道”要接事情或信息作宾语，椅子不能作“让妈妈知道”的对象。"}], "explanations": {"此事": "此事：指眼前这件事，作主语，符合句意。", "钥匙": "语义：钥匙不能作为“让妈妈知道”的内容，句子不通。", "天气": "语义：天气不是可以被“知道”的秘密，句子不通。", "椅子": "配价：“知道”要接事情或信息作宾语，椅子不能作“让妈妈知道”的对象。"}, "sentence_index": 0, "correct_answer": "此事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们约好在此事见面。", "explanation": "这里应该用〈此地〉。此地指地点，此事指事情，不能用作见面的地方。"}, {"text": "我的哥哥就是此事。", "explanation": "这里应该用〈人〉。此事只指事情，不指人，不能用来指哥哥。"}, {"text": "他此事没有别的爱好。", "explanation": "这里应该用〈此外〉。此外表示“除此以外”，此事不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90225, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此事", "is_correct": true, "explanation": "此事：指这件事，作主语，符合句意。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“结束”接的是事情或活动，不能说“月亮到这里就结束吧”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能在这里“结束”，这里指的不是一件事情，句子不通。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不是可以“结束”的事情，句子不通。"}], "explanations": {"此事": "此事：指这件事，作主语，符合句意。", "月亮": "搭配：“结束”接的是事情或活动，不能说“月亮到这里就结束吧”。", "大海": "语义：大海不能在这里“结束”，这里指的不是一件事情，句子不通。", "白菜": "语义：白菜不是可以“结束”的事情，句子不通。"}, "sentence_index": 6, "correct_answer": "此事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我此事从未去过国外。", "explanation": "这里应该用〈此生〉。此生表示一生的时间，此事指事情，不能这样用。"}, {"text": "学校此事再也没有放假。", "explanation": "这里应该用〈此后〉。此后表示之后的时间，此事不能表示时间。"}, {"text": "孩子们在此事里跑来跑去。", "explanation": "这里应该用〈院子〉。此事指事情，不能作为“里”所指的处所；表示场所应说院子等地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90225, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这此事已经传遍了整个学校。", "corrected_sentence": "此事已经传遍了整个学校。", "error_description": "错误：“此”本身已表示指示，前面不能再加“这”。应直接说“此事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90225, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没提过一件此事。", "corrected_sentence": "他从来没提过此事。", "error_description": "错误：“此事”不能与“一件”连用，“此”已表示指示。应说“此事”或“这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
