INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这件事情。", "primary_collocate": null, "pronunciation": "cǐ shì", "ipa": "tsʰɨ²¹⁴ ʂɻ̩⁵¹", "syllable_count": 2, "sentences": [{"text": "此事我已经告诉经理了。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你不要把此事告诉别人。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事很重要，我们明天再谈。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于此事，我没有别的看法。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对此事一点也不知道。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事发生在三年前。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得此事应该怎么办？", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都不想再提此事。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板已经知道此事了。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此事与我没有关系。", "target_word": "此事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "指上文提到的这件事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此事", "is_correct": true, "explanation": "此事：指上文提到的这件事，可作“告诉”的宾语，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是实物，不能作为“告诉经理”的内容，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“告诉”接的是事情或消息，不能说“天气我已经告诉经理了”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是可以被告知的事情，句子不通。"}], "explanations": {"此事": "此事：指上文提到的这件事，可作“告诉”的宾语，符合句意。", "钥匙": "语义：钥匙是实物，不能作为“告诉经理”的内容，句子不通。", "天气": "搭配：“告诉”接的是事情或消息，不能说“天气我已经告诉经理了”。", "椅子": "语义：椅子不是可以被告知的事情，句子不通。"}, "sentence_index": 0, "correct_answer": "此事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在此事出发。", "explanation": "这里应该用〈此时〉。此时表示时间，指“在这个时候”；此事指事情，不能表示时间。"}, {"text": "我们约好在此事见面。", "explanation": "这里应该用〈此地〉。此地表示地点，此事指事情，不能用作见面的地方。"}, {"text": "我的好朋友就是此事。", "explanation": "这里应该用〈人〉。此事只指事情，不指人，不能用来指一个朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此事", "is_correct": true, "explanation": "此事：指这件事，作主语，符合“应该怎么办”的语境。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是需要人决定怎么办的事情，句子不通。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“怎么办”问的是事情或问题，不能与“太阳”搭配。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以讨论“怎么办”的对象，句子不通。"}], "explanations": {"此事": "此事：指这件事，作主语，符合“应该怎么办”的语境。", "月亮": "语义：月亮不是需要人决定怎么办的事情，句子不通。", "太阳": "搭配：“怎么办”问的是事情或问题，不能与“太阳”搭配。", "大海": "语义：大海不是可以讨论“怎么办”的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "此事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他此事再也没有回来。", "explanation": "这里应该用〈此后〉。此后表示之后的时间；此事是指事情的名词，不能表示时间。"}, {"text": "我们一起去了此事玩了一天。", "explanation": "这里应该用〈公园〉。此事指事情，不能作为地点；去某处玩要说地点，如公园。"}, {"text": "她此事没有别的爱好。", "explanation": "这里应该用〈此外〉。此外表示“除此以外”，此事不能表示这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这此事对公司的影响很大。", "corrected_sentence": "此事对公司的影响很大。", "error_description": "错误：“此”本身已表示“这”的意思，前面不能再加“这”。应直接说“此事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们很少提起一件此事。", "corrected_sentence": "他们很少提起此事。", "error_description": "错误：“此”已表示指示，不能与数量词“一件”连用。应说“此事”或“这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
