INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种透明而硬脆的物质，用来做窗、杯子等。", "primary_collocate": null, "pronunciation": "bō li", "ipa": "pwo⁵⁵ li", "syllable_count": 2, "sentences": [{"text": "这个杯子是玻璃做的。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户用的是厚玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃可以用来做窗和杯子。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间的门是玻璃做的，很大。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃是一种很常见的材料。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在楼上装了新玻璃。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玻璃能挡住紫外线。", "target_word": "玻璃", "complexity_tier": "T3", "furigana": "zhè zhǒng bō li néng dǎng zhù zǐ wài xiàn", "sentence_source": "generated"}, {"text": "玻璃和塑料一样可以回收。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里放着很多用玻璃做的杯子。", "target_word": "玻璃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块玻璃", "label": "量词"}, {"form": "玻璃杯", "label": "复合"}, {"form": "玻璃窗", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来做窗、杯子等的透明硬脆材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64773334-eec3-477e-9941-8cbc9d543f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玻璃", "is_correct": true, "explanation": "玻璃：一种透明硬脆的材料，可以用来做杯子，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用来做杯子，句子不通。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不是可以做杯子的材料，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：“是……做的”要接材料，月亮不能作杯子的材料。"}], "explanations": {"玻璃": "玻璃：一种透明硬脆的材料，可以用来做杯子，符合句意。", "空气": "语义：空气不能用来做杯子，句子不通。", "云": "语义：云不是可以做杯子的材料，句子不通。", "月亮": "搭配：“是……做的”要接材料，月亮不能作杯子的材料。"}, "sentence_index": 0, "correct_answer": "玻璃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想买一只玻璃。", "explanation": "这里应该用〈块〉。玻璃作为材料，量词用“块”或“片”，不用“只”。"}, {"text": "这里摆着一根玻璃。", "explanation": "这里应该用〈块〉。“根”用于细长的东西，玻璃是片状的，不能用“根”。"}, {"text": "她用玻璃擦了擦嘴。", "explanation": "这里应该用〈纸巾〉。玻璃硬而易碎，不能用来擦嘴，擦嘴要用纸巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玻璃", "is_correct": true, "explanation": "玻璃：可以安装在楼上做窗，符合句意。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“装”接的是设备或材料，阳光不能被安装。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不能被“装”在楼上，句子不通。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不是可以安装的东西，句子不通。"}], "explanations": {"玻璃": "玻璃：可以安装在楼上做窗，符合句意。", "阳光": "搭配：“装”接的是设备或材料，阳光不能被安装。", "雨水": "语义：雨水不能被“装”在楼上，句子不通。", "月光": "语义：月光不是可以安装的东西，句子不通。"}, "sentence_index": 6, "correct_answer": "玻璃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商店里放着很多条玻璃。", "explanation": "这里应该用〈块〉。“条”不用于玻璃这样的片状材料。"}, {"text": "她用一把玻璃擦桌子。", "explanation": "这里应该用〈块〉。“把”用于有柄的东西，玻璃不用“把”。"}, {"text": "他家的窗户上装着一个玻璃。", "explanation": "这里应该用〈块〉。“个”不适合用于玻璃这种材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这扇门上装的是一只厚玻璃。", "corrected_sentence": "这扇门上装的是一块厚玻璃。", "error_description": "错误：玻璃是片状材料，应用量词“块”，不用“只”。应说“一块厚玻璃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把桌上的那只玻璃擦干净了。", "corrected_sentence": "他把桌上的那块玻璃擦干净了。", "error_description": "错误：“那只玻璃”。正确：“那块玻璃”。玻璃是片状材料，量词应用“块”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e41ac393-2e0a-46ab-84e4-91341431eb74') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
