INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90253, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "万人是很多很多的人，多到有一万个。", "primary_collocate": null, "pronunciation": "wàn rén", "ipa": "wan˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "体育场里坐满了上万人。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "广场上聚集了上万人，大家都在唱歌。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "这场比赛有上万人到现场看。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "万人大会在大礼堂举行。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "这座城市有上万人参加了长跑。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "他的演唱会来了上万人。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "昨天的音乐会吸引了上万人。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "上万人的会场里一点声音也没有。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "街上有上万人欢呼，非常热闹。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "球场能容纳上万人，位子很多。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "多到一万个的很多人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1a0300-a4d2-44ca-8527-0106e0d41547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万元", "is_correct": false, "explanation": "搭配：“坐满”的对象是人或座位，“万元”是钱数，不能坐满。"}, {"text": "万人", "is_correct": true, "explanation": "正确。“上万人”指一万以上的人，与体育场里坐满的人群相合。"}, {"text": "万字", "is_correct": false, "explanation": "语义：“万字”指文字的数量，句中要说的是坐满体育场的人，不符。"}, {"text": "万年", "is_correct": false, "explanation": "语义：“万年”指时间长度，不能用来指坐满体育场的人数。"}], "explanations": {"万元": "搭配：“坐满”的对象是人或座位，“万元”是钱数，不能坐满。", "万人": "正确。“上万人”指一万以上的人，与体育场里坐满的人群相合。", "万字": "语义：“万字”指文字的数量，句中要说的是坐满体育场的人，不符。", "万年": "语义：“万年”指时间长度，不能用来指坐满体育场的人数。"}, "sentence_index": 0, "correct_answer": "万人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一位万人。", "explanation": "这里应该用〈一位同学〉。“万人”指一万以上的人群，不能用“一位”来数单个人。"}, {"text": "体育场里坐满了一条万人。", "explanation": "这里应该用〈一万人〉。“条”用于细长的物体，不能用来修饰“万人”。"}, {"text": "个别万人没来参加会议。", "explanation": "这里应该用〈个别同学〉。“个别”指很少的几个，与“万人”表示一万以上的人群相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万公里", "is_correct": false, "explanation": "搭配：“吸引”的对象是人或注意力，“公里”是距离，不能被吸引。"}, {"text": "万小时", "is_correct": false, "explanation": "搭配：“吸引”的对象是人或注意力，不能说吸引了几万小时。"}, {"text": "万人", "is_correct": true, "explanation": "正确。“上万人”指一万以上的观众，与音乐会吸引的人群相合。"}, {"text": "万天", "is_correct": false, "explanation": "语义：“万天”指时间长度，与“吸引”的人群不符。"}], "explanations": {"万公里": "搭配：“吸引”的对象是人或注意力，“公里”是距离，不能被吸引。", "万小时": "搭配：“吸引”的对象是人或注意力，不能说吸引了几万小时。", "万人": "正确。“上万人”指一万以上的观众，与音乐会吸引的人群相合。", "万天": "语义：“万天”指时间长度，与“吸引”的人群不符。"}, "sentence_index": 6, "correct_answer": "万人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们组只有五个万人。", "explanation": "这里应该用〈五个人〉。“万人”指一万以上的人群，不能用来数“五个”。"}, {"text": "会场里坐着一对万人。", "explanation": "这里应该用〈一群观众〉。“对”指成双的事物，不能用来数“万人”这样的群体。"}, {"text": "他的同事个个都是万人。", "explanation": "这里应该用〈能干的人〉。“万人”指一万以上的群体，不能拿来指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节日的广场上挤了一只上万人。", "corrected_sentence": "节日的广场上挤了上万人。", "error_description": "量词错误：“上万人”是不定量的人群，不能用个体量词“只”修饰。应删去“一只”，写作“节日的广场上挤了上万人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90253, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座大剧院一次能坐一只上万人。", "corrected_sentence": "这座大剧院一次能坐上万人。", "error_description": "量词错误：“人”不能用个体量词“只”修饰，应删去“只”，写作“这座大剧院一次能坐上万人。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
