INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90254, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一万个人；泛指人数极多。", "primary_collocate": null, "pronunciation": "wàn rén", "ipa": "wan˥˩ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "这个体育馆可以坐上万人。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "公司要招上万人，要求不高。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "他们的队伍有上万人。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "万人合唱团在广场上唱歌。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "这条路上每天有上万人经过。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "学校有上万人参加了考试。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "这家工厂有上万人在工作。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "万人长跑今天早上开始了。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "新机场建好后，每天能送上万人出国。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}, {"text": "万人大合唱让大家很感动。", "target_word": "万人", "complexity_tier": "T3", "furigana": "wàn rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "萬人", "label": "繁体"}], "register": "通用", "sense_fingerprint": "一万个人；泛指人数极多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1a0300-a4d2-44ca-8527-0106e0d41547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "万元", "is_correct": false, "explanation": "搭配：“坐”的对象是人或座位，“万元”是钱数，体育馆不能坐钱数。"}, {"text": "万人", "is_correct": true, "explanation": "正确。“上万人”表示一万以上的人数，与体育馆能容纳的观众相合。"}, {"text": "万字", "is_correct": false, "explanation": "语义：“万字”指文字数量，与“坐”和体育馆的语境不符。"}, {"text": "万美元", "is_correct": false, "explanation": "搭配：货币不能被“坐”，与体育馆可以容纳人的语境不符。"}], "explanations": {"万元": "搭配：“坐”的对象是人或座位，“万元”是钱数，体育馆不能坐钱数。", "万人": "正确。“上万人”表示一万以上的人数，与体育馆能容纳的观众相合。", "万字": "语义：“万字”指文字数量，与“坐”和体育馆的语境不符。", "万美元": "搭配：货币不能被“坐”，与体育馆可以容纳人的语境不符。"}, "sentence_index": 0, "correct_answer": "万人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里坐着三个万人。", "explanation": "这里应该用〈三十个学生〉。“万人”指一万以上，不能用来数“三个”。"}, {"text": "一位万人走进了办公室。", "explanation": "这里应该用〈一位老师〉。“万人”是一万以上的群体，不能用“一位”来数单个人。"}, {"text": "广场上有一把万人在跳舞。", "explanation": "这里应该用〈一群人〉。“把”用于有柄的物件，不能用来修饰“万人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "万里", "is_correct": false, "explanation": "语义：“万里”指距离，句中说的是在工作的人，不符。"}, {"text": "万人", "is_correct": true, "explanation": "正确。“上万人”表示一万以上在工作的人，与工厂的语境相合。"}, {"text": "万天", "is_correct": false, "explanation": "语义：“万天”指时间长度，不能用来指在工作的人数。"}, {"text": "万秒", "is_correct": false, "explanation": "搭配：“有……在工作”要接表示人的数量，“万秒”是时间，不能与在工作的人搭配。"}], "explanations": {"万里": "语义：“万里”指距离，句中说的是在工作的人，不符。", "万人": "正确。“上万人”表示一万以上在工作的人，与工厂的语境相合。", "万天": "语义：“万天”指时间长度，不能用来指在工作的人数。", "万秒": "搭配：“有……在工作”要接表示人的数量，“万秒”是时间，不能与在工作的人搭配。"}, "sentence_index": 6, "correct_answer": "万人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里只有一块万人。", "explanation": "这里应该用〈一群人〉。“块”用于物体，不能用来数万人群体。"}, {"text": "我们班有很多万人在上课。", "explanation": "这里应该用〈很多学生〉。一个班级不可能有一万人以上，“万人”在此语义不合。"}, {"text": "这个队伍的队长是万人。", "explanation": "这里应该用〈一位队长〉。“万人”指一万以上的群体，不能作为单个人身份的名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "礼堂里来了一条上万人听讲座。", "corrected_sentence": "礼堂里来了上万人听讲座。", "error_description": "量词错误：“条”用于细长的物体，不能用来修饰“上万人”这样的人群。应删去“一条”，写作“礼堂里来了上万人听讲座。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个剧场一次能坐上万人们。", "corrected_sentence": "这个剧场一次能坐上万人。", "error_description": "错误：“万人”后面加了复数词尾“们”。“万人”本身已表示一万以上的人群，不能再加“们”。正确说法：这个剧场一次能坐上万人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
