INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90255, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到不好的事，不再难过，想开一点。", "primary_collocate": null, "pronunciation": "kàn kāi", "ipa": "kʰan˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "失败了没关系，你要看开一点。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失恋以后很难过，现在终于看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶生病了，但她很快就看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友离开了，你别太伤心，要看开。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没考好，妈妈让我看开一点。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丢了钱我很难过，睡一觉就看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了几年，他对那件伤心事看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了一晚上，第二天看开了。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都希望他早点儿看开，别再难过。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说人生有苦有甜，要学会看开。", "target_word": "看开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看开了", "label": "体标"}, {"form": "看开过", "label": "体标"}, {"form": "看得开", "label": "可能补语"}, {"form": "看不开", "label": "可能补语"}, {"form": "看開", "label": "繁体"}], "register": "口语", "sense_fingerprint": "遇到失败、失去、伤心事后想开，不再难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4809b0-ba75-480f-b901-0e7163480787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃一点”指吃东西，与“失败了没关系”的安慰语境无关。"}, {"text": "看开", "is_correct": true, "explanation": "正确：看开表示遇到不好的事想得开、不再难过，符合安慰对方的语境。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡一点”指休息，无法表达对失败的态度。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象通常是文字或文章，不能与“你要……一点”的心态安慰搭配。"}], "explanations": {"吃": "语义：“吃一点”指吃东西，与“失败了没关系”的安慰语境无关。", "看开": "正确：看开表示遇到不好的事想得开、不再难过，符合安慰对方的语境。", "睡": "语义：“睡一点”指休息，无法表达对失败的态度。", "写": "搭配：“写”的对象通常是文字或文章，不能与“你要……一点”的心态安慰搭配。"}, "sentence_index": 0, "correct_answer": "看开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的谎话很拙劣，我一眼就看开了。", "explanation": "这里应该用〈看穿〉。看开指遇事想得开、不再难过，不表示看透对方的谎言。"}, {"text": "她在店里看开了一条裙子，马上买下。", "explanation": "这里应该用〈看中〉。看开指想得开，不能表示挑中某样东西。"}, {"text": "他一直抓着我的手，不肯看开。", "explanation": "这里应该用〈放开〉。看开指心态，不指松手；松开抓着的东西要说“放开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：“唱了”与“伤心事”无关，无法表示心情平复。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物或身体，不能与“伤心事”搭配。"}, {"text": "看开", "is_correct": true, "explanation": "正确：看开表示想开、不再难过，符合“过了几年”后心情平复的语境。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”指把东西放在阳光下，不能表示对伤心事的态度变化。"}], "explanations": {"唱": "语义：“唱了”与“伤心事”无关，无法表示心情平复。", "洗": "搭配：“洗”的对象是衣物或身体，不能与“伤心事”搭配。", "看开": "正确：看开表示想开、不再难过，符合“过了几年”后心情平复的语境。", "晒": "语义：“晒”指把东西放在阳光下，不能表示对伤心事的态度变化。"}, "sentence_index": 6, "correct_answer": "看开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他总是看开穷人，真让人不舒服。", "explanation": "这里应该用〈看不起〉。看开指想得开，不能用来表示轻视他人。"}, {"text": "我看开这支球队，觉得他们能赢。", "explanation": "这里应该用〈看好〉。看开表示想得开，不能表示对球队前景的乐观判断。"}, {"text": "他负责看开两个孩子。", "explanation": "这里应该用〈看管〉。看开指想得开，不能表示照看、管理人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈终于看了开，不再怪自己。", "corrected_sentence": "妈妈终于看开了，不再怪自己。", "error_description": "错误：“看了开”。正确：“看开了”。“看开”是固定的动补词，“了”不能插在其中，应置于词末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "分手后，她慢慢把看开了，又开始笑了。", "corrected_sentence": "分手后，她慢慢看开了，又开始笑了。", "error_description": "错误：“把看开了”。正确：“看开了”。“把”字句要求把字后有宾语（如“把这件事看开了”），此句“把”后没有宾语，所以不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
