INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90262, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向神灵诉说心愿，请求保佑。", "primary_collocate": null, "pronunciation": "qí dǎo", "ipa": "tɕʰi˧˥ tɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "村民们到庙里祈祷，希望明年有好收成。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲每天都向神祈祷，请他保佑孩子。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，她去教堂祈祷了一会儿。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人跪在佛像前，低声祈祷着。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争期间，人们天天祈祷和平早日到来。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向上天祈祷，请保佑全家平安。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨不停，农民们祈祷河水别再上涨。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾在这座寺庙里祈祷过很多次。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们围着火堆，一起向神祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的家人在医院外面不停地祈祷。", "target_word": "祈祷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祈祷了", "label": "体标"}, {"form": "祈祷着", "label": "体标"}, {"form": "祈祷过", "label": "体标"}, {"form": "祈禱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "向神灵诉说心愿并请求保佑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9d3da1c-9c58-4131-8533-51a4d2c792cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祈祷", "is_correct": true, "explanation": "正确：“祈祷”指向神灵请求保佑，与村民到庙里希望有好收成相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：庙里不能游泳，与“到庙里”的场景不符。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指丢掉工作，不是能在庙里进行的动作，句意不通。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”需要文件等对象，单独用于“到庙里”不通。"}], "explanations": {"祈祷": "正确：“祈祷”指向神灵请求保佑，与村民到庙里希望有好收成相符。", "游泳": "语义：庙里不能游泳，与“到庙里”的场景不符。", "失业": "语义：“失业”指丢掉工作，不是能在庙里进行的动作，句意不通。", "打印": "搭配：“打印”需要文件等对象，单独用于“到庙里”不通。"}, "sentence_index": 0, "correct_answer": "祈祷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们向他祈祷，表示感谢。", "explanation": "这里应该用〈感谢〉。祈祷是向神灵求保佑，不能用来对人表示谢意，应说“感谢”。"}, {"text": "老师祈祷了他的错误。", "explanation": "这里应该用〈批评〉。祈祷是向神灵求福，不能用于指出别人的错误，应说“批评”。"}, {"text": "公司祈祷员工明天放假。", "explanation": "这里应该用〈通知〉。祈祷是向神灵请求保佑，不能用于告知员工事情，应说“通知”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祈祷", "is_correct": true, "explanation": "正确：“祈祷”表示农民向神灵请求停止上涨，与大雨不停的情境相符。"}, {"text": "统计", "is_correct": false, "explanation": "配价：“统计”的宾语应是数据或对象，不能带“河水别再上涨”这样的小句。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：“搬运”是搬东西的动作，不能说“搬运河水别再上涨”。"}, {"text": "复习", "is_correct": false, "explanation": "语义：复习针对学过的内容，与河水上涨的情境不符，句子不通。"}], "explanations": {"祈祷": "正确：“祈祷”表示农民向神灵请求停止上涨，与大雨不停的情境相符。", "统计": "配价：“统计”的宾语应是数据或对象，不能带“河水别再上涨”这样的小句。", "搬运": "语义：“搬运”是搬东西的动作，不能说“搬运河水别再上涨”。", "复习": "语义：复习针对学过的内容，与河水上涨的情境不符，句子不通。"}, "sentence_index": 6, "correct_answer": "祈祷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向路人祈祷去车站的路。", "explanation": "这里应该用〈询问〉。祈祷是向神灵求保佑，不能用来向路人打听，应说“询问”。"}, {"text": "老师祈祷了他的努力。", "explanation": "这里应该用〈夸奖〉。祈祷是向神灵求福，不能用于称赞别人的努力，应说“夸奖”。"}, {"text": "他向朋友祈祷，说自己错了。", "explanation": "这里应该用〈道歉〉。祈祷是向神灵诉说心愿，不能用于向朋友认错，应说“道歉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士们向病人祈祷，希望他们早日康复。", "corrected_sentence": "护士们为病人祈祷，希望他们早日康复。", "error_description": "介词用错：“向”引出的是神灵，这里祈求的对象是病人，为别人祈求时要用“为”，应为“为病人祈祷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们在庙前一个祈祷，希望明年有好收成。", "corrected_sentence": "村民们在庙前一起祈祷，希望明年有好收成。", "error_description": "用词错误：“一个”是数量词，不能修饰动词“祈祷”；表示共同做应当用副词“一起”，应为“一起祈祷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a84b536-6151-456e-becf-c5d1dc5abf8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "推卸", "is_correct": true, "explanation": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。"}, {"text": "观看", "is_correct": false, "explanation": "“观看”指用眼睛看，与“负”不构成反义。"}, {"text": "陪伴", "is_correct": false, "explanation": "“陪伴”指陪在身边，与“负”不构成反义。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与“负”不构成反义。"}], "correct_answer": "推卸", "explanations": {"推卸": "“推卸”指不肯承担责任，与“负”（担负、承担）相反。", "观看": "“观看”指用眼睛看，与“负”不构成反义。", "陪伴": "“陪伴”指陪在身边，与“负”不构成反义。", "参加": "“参加”指加入某项活动，与“负”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
