INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担负，承担责任或任务。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "他一个人负起了养家的责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机对这次事故负有责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥负起了照顾弟弟的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长说，学校要对每个学生负起责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她肩上负着一家人的希望。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事的人要自己负起责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母年纪大了，儿子应该负起照顾他们的责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司对产品的质量负有责任。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长负起了带领大家的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚当上班长，就负起了管理全班的任务。", "target_word": "负", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "负着", "label": "体标"}, {"form": "负了", "label": "体标"}, {"form": "负责", "label": "复合"}, {"form": "負", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "负：担负、承担责任或任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "负", "is_correct": true, "explanation": "负（fù）指担负、承担责任或任务，正是听到的词。"}, {"text": "夫", "is_correct": false, "explanation": "夫（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "服", "is_correct": false, "explanation": "服（第二声）与 fù（第四声）声调不同，意思是服从或衣服。"}, {"text": "步", "is_correct": false, "explanation": "步（bù）与 fù 声母不同，声母由 f 变为 b，意思是脚步。"}, {"text": "路", "is_correct": false, "explanation": "路（lù）与 fù 声母不同，声母由 f 变为 l，意思是道路。"}], "explanations": {"负": "负（fù）指担负、承担责任或任务，正是听到的词。", "夫": "夫（第一声）与 fù（第四声）声调不同，意思是丈夫。", "服": "服（第二声）与 fù（第四声）声调不同，意思是服从或衣服。", "步": "步（bù）与 fù 声母不同，声母由 f 变为 b，意思是脚步。", "路": "路（lù）与 fù 声母不同，声母由 f 变为 l，意思是道路。"}, "sentence_index": null, "correct_answer": "负"}, "level_3": {"options": [{"text": "负", "is_correct": true, "explanation": "“负起”表示开始承担，与“养家的责任”的语境相符。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推”是推开或推卸，与“承担养家的责任”的意思相反。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”是躲避，与“承担养家的责任”相矛盾。"}, {"text": "赖", "is_correct": false, "explanation": "搭配：“赖”常用于“赖账”，不能与“起……的责任”搭配，意思也与承担相反。"}], "explanations": {"负": "“负起”表示开始承担，与“养家的责任”的语境相符。", "推": "语义：“推”是推开或推卸，与“承担养家的责任”的意思相反。", "躲": "语义：“躲”是躲避，与“承担养家的责任”相矛盾。", "赖": "搭配：“赖”常用于“赖账”，不能与“起……的责任”搭配，意思也与承担相反。"}, "sentence_index": 0, "correct_answer": "负"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年被选为班长，今年又负起了班长。", "explanation": "这里应该用〈担任〉。“负起”用于责任或任务，表示职务时要说“担任”。"}, {"text": "他负起了一杯茶，递给了客人。", "explanation": "这里应该用〈端〉。“负起”只用于责任或任务，不能用于端茶这类动作。"}, {"text": "他负起了一双鞋，穿在了脚上。", "explanation": "这里应该用〈穿〉。“负起”只用于责任或任务，不能用于穿鞋这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "负", "is_correct": true, "explanation": "负（fù）指担负、承担责任或任务，正是听到的词。"}, {"text": "扶", "is_correct": false, "explanation": "扶（第二声）与 fù（第四声）声调不同，意思是扶持。"}, {"text": "辅", "is_correct": false, "explanation": "辅（第三声）与 fù（第四声）声调不同，意思是辅助。"}, {"text": "布", "is_correct": false, "explanation": "布（bù）与 fù 声母不同，声母由 f 变为 b，意思是布料。"}, {"text": "户", "is_correct": false, "explanation": "户（hù）与 fù 声母不同，声母由 f 变为 h，意思是家庭或门户。"}], "explanations": {"负": "负（fù）指担负、承担责任或任务，正是听到的词。", "扶": "扶（第二声）与 fù（第四声）声调不同，意思是扶持。", "辅": "辅（第三声）与 fù（第四声）声调不同，意思是辅助。", "布": "布（bù）与 fù 声母不同，声母由 f 变为 b，意思是布料。", "户": "户（hù）与 fù 声母不同，声母由 f 变为 h，意思是家庭或门户。"}, "sentence_index": null, "correct_answer": "负"}, "level_3": {"options": [{"text": "负", "is_correct": true, "explanation": "“负起照顾父母的责任”符合“应该”的要求，与语境相符。"}, {"text": "逃", "is_correct": false, "explanation": "语义：“逃”是逃避，与“应该……照顾父母的责任”的意思相反。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不说“放起……的责任”，与“照顾父母”不搭配。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”是丢失，不能表示承担照顾父母的责任。"}], "explanations": {"负": "“负起照顾父母的责任”符合“应该”的要求，与语境相符。", "逃": "语义：“逃”是逃避，与“应该……照顾父母的责任”的意思相反。", "放": "搭配：“放”不说“放起……的责任”，与“照顾父母”不搭配。", "丢": "语义：“丢”是丢失，不能表示承担照顾父母的责任。"}, "sentence_index": 6, "correct_answer": "负"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他负起了一首歌，唱给大家听。", "explanation": "这里应该用〈唱〉。“负起”只用于责任或任务，不能与“歌”搭配。"}, {"text": "他负起了一封信，寄到了北京。", "explanation": "这里应该用〈寄〉。“负起”只用于责任或任务，不能用于寄信这类动作。"}, {"text": "他负起了一个故事，讲给孩子们听。", "explanation": "这里应该用〈讲〉。“负起”只用于责任或任务，讲故事应说“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCL