INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事他应该负下责任。", "corrected_sentence": "这件事他应该负起责任。", "error_description": "错误：“负”后的补语用了“下”。正确：“负起责任”，“起”表示开始承担；“负下”不是这个词的搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经负了起责任。", "corrected_sentence": "他已经负起了责任。", "error_description": "错误：“了”放在了“负”和“起”之间。正确：“负起了责任”，“了”应放在动补结构“负起”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
