INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事做过一遍以后，再做的这一回。", "primary_collocate": null, "pronunciation": "dì èr cì", "ipa": "ti˥˩ ɚ˥˩ tsʰɨ˥˩", "syllable_count": 3, "sentences": [{"text": "第一次做错了，第二次我很小心。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜我第一次没做好，第二次就好吃多了。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二次来这里，我已经不会迷路了。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次没听懂，我又讲了第二次。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次太紧张了，第二次我就不怕了。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看过一遍，现在看第二次。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天没成功，今天是他第二次试。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第二次洗的时候，衣服就不掉色了。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说第一次不好意思，第二次就自然了。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字我第二次才写对。", "target_word": "第二次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做过一遍之后重新再做的这一回，与第一次对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4809b0-ba75-480f-b901-0e7163480787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不能“小心”，作为“我很小心”的主语，句意荒谬。"}, {"text": "第二次", "is_correct": true, "explanation": "正确：第二次指做过一遍后再做的这一回，与前面做错的“第一次”形成对比。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”不能“小心”，作为“我很小心”的主语，表意不通。"}, {"text": "第一次", "is_correct": false, "explanation": "搭配：句中已有“第一次做错了”，同一句再用“第一次”会使前后矛盾。"}], "explanations": {"鸡蛋": "语义：“鸡蛋”不能“小心”，作为“我很小心”的主语，句意荒谬。", "第二次": "正确：第二次指做过一遍后再做的这一回，与前面做错的“第一次”形成对比。", "地铁": "语义：“地铁”不能“小心”，作为“我很小心”的主语，表意不通。", "第一次": "搭配：句中已有“第一次做错了”，同一句再用“第一次”会使前后矛盾。"}, "sentence_index": 0, "correct_answer": "第二次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这三个苹果里，第二次最甜。", "explanation": "这里应该用〈第二个〉。第二次指再做一遍的这一回，不能描述苹果的甜度，应使用“第二个”。"}, {"text": "我们坐车坐了一小时，终于到了第二次。", "explanation": "这里应该用〈第二站〉。第二次指再做一遍的这一回，不能指车辆的停靠点。"}, {"text": "汉语的第二次是阳平。", "explanation": "这里应该用〈第二声〉。第二次指再做一遍，不能指声调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上次", "is_correct": false, "explanation": "语义：“上次”指昨天这一回之前的一回，与“今天”的时间冲突。"}, {"text": "第二次", "is_correct": true, "explanation": "正确：第二次指再做一遍的这一回，与“昨天没成功”的上一次尝试相承接。"}, {"text": "下次", "is_correct": false, "explanation": "搭配：“下次”指将来的一回，不能与“今天”这一时间搭配。"}, {"text": "首次", "is_correct": false, "explanation": "语义：“首次”表示第一次，与“昨天没成功”已有过尝试的事实矛盾。"}], "explanations": {"上次": "语义：“上次”指昨天这一回之前的一回，与“今天”的时间冲突。", "第二次": "正确：第二次指再做一遍的这一回，与“昨天没成功”的上一次尝试相承接。", "下次": "搭配：“下次”指将来的一回，不能与“今天”这一时间搭配。", "首次": "语义：“首次”表示第一次，与“昨天没成功”已有过尝试的事实矛盾。"}, "sentence_index": 6, "correct_answer": "第二次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个字的第二次笔画写歪了。", "explanation": "这里应该用〈第二笔〉。第二次指再做一遍的这一回，不能指字的笔画顺序。"}, {"text": "他家住在第二次，窗户很大。", "explanation": "这里应该用〈第二层〉。第二次表示事件的次序，不能指楼层。"}, {"text": "我们坐在第二次，看得很清楚。", "explanation": "这里应该用〈第二排〉。第二次表示事件的次序，不能表示座位的排次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我第一次没写好，一第二次就写对了。", "corrected_sentence": "我第一次没写好，第二次就写对了。", "error_description": "错误：“一第二次”。正确：“第二次”。“第二次”本身已表示次序，前面不能再加数词“一”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天是我把第二次复习这个词。", "corrected_sentence": "今天是我第二次复习这个词。", "error_description": "错误：“把第二次复习”。正确：“第二次复习”。“第二次”表示次序，是时间状语，不能作“把”字句的宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
