INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "隶属于一个国家主权管辖下的区域，包括陆地、领水和领空。", "primary_collocate": null, "pronunciation": "lǐng tǔ", "ipa": "liŋ˨˩ tʰu˨˩", "syllable_count": 2, "sentences": [{"text": "一个国家的领土包括陆地、领水和领空。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国飞机没有同意，不能飞进我国领土上空。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家有权管理自己的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的领水也是国家领土的一部分。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国对这片领土的归属有不同看法。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护领土完整是每个国家的责任。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛是我国不可分割的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家用法律保护自己的领土和主权。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国军队进入了别国的领土。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领土和主权都不能随便交给别人。", "target_word": "领土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "領土", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家主权管辖的区域；包括陆地、领水、领空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54cdf3f2-e251-4733-85cf-17180d6e4543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领土", "is_correct": true, "explanation": "正确：“一个国家的领土”包括陆地、领水和领空，语义和搭配都合适。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口不包括陆地、领水和领空，句子的意思说不通。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史不是由陆地、领水和领空构成的，与“包括”的意思冲突。"}, {"text": "语言", "is_correct": false, "explanation": "配价：“包括”的主语须是由陆地、领水、领空组成的整体，“语言”不能包括这些。"}], "explanations": {"领土": "正确：“一个国家的领土”包括陆地、领水和领空，语义和搭配都合适。", "人口": "语义：人口不包括陆地、领水和领空，句子的意思说不通。", "历史": "语义：历史不是由陆地、领水和领空构成的，与“包括”的意思冲突。", "语言": "配价：“包括”的主语须是由陆地、领水、领空组成的整体，“语言”不能包括这些。"}, "sentence_index": 0, "correct_answer": "领土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在音乐的领土上很有名。", "explanation": "这里应该用〈领域〉。“领土”指国家主权范围的区域，指专业范围应说“领域”。"}, {"text": "这块领土的价格涨了三倍。", "explanation": "这里应该用〈地价〉。“领土”指国家主权范围的区域，地产的价格应说“地价”。"}, {"text": "这个农场有五百亩领土。", "explanation": "这里应该用〈田地〉。“领土”指国家主权管辖的区域，农场的土地应说“田地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领土", "is_correct": true, "explanation": "正确：“不可分割的”可以修饰国家的领土，语义和语域都合适。"}, {"text": "玩具", "is_correct": false, "explanation": "语域：“不可分割”是书面语，与口语化的“玩具”不协调，且搭配不通。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：米饭不是岛屿的组成部分，“不可分割的米饭”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能与岛屿构成不可分割的整体，句子的意思不成立。"}], "explanations": {"领土": "正确：“不可分割的”可以修饰国家的领土，语义和语域都合适。", "玩具": "语域：“不可分割”是书面语，与口语化的“玩具”不协调，且搭配不通。", "米饭": "语义：米饭不是岛屿的组成部分，“不可分割的米饭”说不通。", "窗户": "语义：窗户不能与岛屿构成不可分割的整体，句子的意思不成立。"}, "sentence_index": 6, "correct_answer": "领土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校有很大的领土。", "explanation": "这里应该用〈校园〉。“领土”只用于国家主权范围，不能用来指学校的场地。"}, {"text": "这家商场的领土很大。", "explanation": "这里应该用〈面积〉。“领土”只用于国家，不能用来形容商场的大小。"}, {"text": "这座城市的领土很大，有很多高楼。", "explanation": "这里应该用〈面积〉。“领土”只用于国家主权范围，城市不说领土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一座领土不容侵犯。", "corrected_sentence": "这一片领土不容侵犯。", "error_description": "“领土”用量词“片”，“座”多用于山、桥、楼等，不能用于领土。错误形式“这一座领土”应改为“这一片领土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国家一定要住守自己的领土。", "corrected_sentence": "国家一定要守住自己的领土。", "error_description": "“守住”是动词加结果补语，顺序不能颠倒。“住守”错误，应说“守住自己的领土”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
