INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "饭是我们每天吃的东西。可以是白白的米饭，也可以是一顿饭。", "primary_collocate": null, "pronunciation": "fàn", "ipa": "fan˥˩", "syllable_count": 1, "sentences": [{"text": "我每天在家吃饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在厨房做饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗饭太热了，我等一下再吃。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们一起去吃饭吧。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一顿吃了三碗饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，快来吃吧。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想吃一碗热饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给孩子盛了一碗饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃过饭了吗？", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天回家都要先吃饭。", "target_word": "饭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "碗", "label": "量词"}, {"form": "顿", "label": "量词"}, {"form": "米饭", "label": "复合"}, {"form": "饭店", "label": "复合"}], "register": "中性", "sense_fingerprint": "饭：每天吃的东西，可以是米饭，也可以指一顿饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "饭", "is_correct": true, "explanation": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。"}, {"text": "翻", "is_correct": false, "explanation": "翻（fān，第一声）与饭（fàn，第四声）声调不同，意思是翻动、翻译。"}, {"text": "烦", "is_correct": false, "explanation": "烦（fán，第二声）与饭（fàn，第四声）声调不同，意思是烦恼。"}, {"text": "反", "is_correct": false, "explanation": "反（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是相反。"}, {"text": "放", "is_correct": false, "explanation": "放（fàng）与饭（fàn）韵母不同，放是 -ng，饭是 -n，意思是放置。"}], "explanations": {"饭": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。", "翻": "翻（fān，第一声）与饭（fàn，第四声）声调不同，意思是翻动、翻译。", "烦": "烦（fán，第二声）与饭（fàn，第四声）声调不同，意思是烦恼。", "反": "反（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是相反。", "放": "放（fàng）与饭（fàn）韵母不同，放是 -ng，饭是 -n，意思是放置。"}, "sentence_index": null, "correct_answer": "饭"}, "level_3": {"options": [{"text": "饭", "is_correct": true, "explanation": "正确：“每天在家吃饭”中的“饭”，指每天吃的食物。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”是场所，不能作“在家吃”的对象，与“在家”矛盾。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是地方，与“在家”矛盾，不能说“在家吃食堂”。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“吃”不搭配“水”，应说“喝水”。"}], "explanations": {"饭": "正确：“每天在家吃饭”中的“饭”，指每天吃的食物。", "餐厅": "语义：“餐厅”是场所，不能作“在家吃”的对象，与“在家”矛盾。", "食堂": "语义：“食堂”是地方，与“在家”矛盾，不能说“在家吃食堂”。", "水": "搭配：“吃”不搭配“水”，应说“喝水”。"}, "sentence_index": 0, "correct_answer": "饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我渴了，想喝饭。", "explanation": "这里应该用〈饮料〉。饭是固体食物，不能用“喝”。"}, {"text": "超市的货架上摆满了饭。", "explanation": "这里应该用〈食品〉。饭指做好的米饭或一顿饭，超市货架上摆的是包装食品，不说“饭”。"}, {"text": "我爷爷在田里种了很多饭。", "explanation": "这里应该用〈稻子〉。“种”的对象是稻、麦等作物，饭是煮熟的食物，不能种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "饭", "is_correct": true, "explanation": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。"}, {"text": "帆", "is_correct": false, "explanation": "帆（fān，第一声）与饭（fàn，第四声）声调不同，意思是船帆。"}, {"text": "凡", "is_correct": false, "explanation": "凡（fán，第二声）与饭（fàn，第四声）声调不同，意思是凡是、所有。"}, {"text": "返", "is_correct": false, "explanation": "返（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是返回。"}, {"text": "汗", "is_correct": false, "explanation": "汗（hàn）与饭（fàn）声母不同，h 与 f 不同，意思是汗水。"}], "explanations": {"饭": "饭（fàn）：每天吃的食物，可指米饭，也可指一顿饭。", "帆": "帆（fān，第一声）与饭（fàn，第四声）声调不同，意思是船帆。", "凡": "凡（fán，第二声）与饭（fàn，第四声）声调不同，意思是凡是、所有。", "返": "返（fǎn，第三声）与饭（fàn，第四声）声调不同，意思是返回。", "汗": "汗（hàn）与饭（fàn）声母不同，h 与 f 不同，意思是汗水。"}, "sentence_index": null, "correct_answer": "饭"}, "level_3": {"options": [{"text": "饭", "is_correct": true, "explanation": "正确：“我想吃一碗热饭”中的“饭”，指煮熟的米饭。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：蛋糕用“块”计量，不用“碗”，“一碗热蛋糕”不说。"}, {"text": "冰", "is_correct": false, "explanation": "语义：“热”与“冰”相矛盾，冰不能是热的，与“热”矛盾。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能用来吃，“吃一碗热书”不通。"}], "explanations": {"饭": "正确：“我想吃一碗热饭”中的“饭”，指煮熟的米饭。", "蛋糕": "搭配：蛋糕用“块”计量，不用“碗”，“一碗热蛋糕”不说。", "冰": "语义：“热”与“冰”相矛盾，冰不能是热的，与“热”矛盾。", "书": "语义：书不能用来吃，“吃一碗热书”不通。"}, "sentence_index": 6, "correct_answer": "饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸每天回家都要先喝饭。", "explanation": "这里应该用〈饮料〉。饭是固体食物，不能用“喝”。"}, {"text": "爸爸每天回家都要先洗饭。", "explanation": "这里应该用〈米〉。饭是煮好的食物，不能洗，要洗的是生米。"}, {"text": "爸爸每天回家都要先读饭。", "explanation": "这里应该用〈书〉。“读”的对象是书、文字，饭不能读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一天只吃一只饭。", "corrected_sentence": "他一天只吃一顿饭。", "error_description": "“饭”的量词应用“顿”（或“碗”），不能用“只”，“只”用于动物。正确说法是“一顿饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经吃饭过了。", "corrected_sentence": "我们已经吃过饭了。", "error_description": "“过”要紧跟动词，应说“吃过饭”，不能说“吃饭过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "幼年", "is_correct": true, "explanation": "「幼年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。"}, {"text": "河流", "is_correct": false, "explanation": "「河流」是地理事物，与「高年」没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "「窗户」是建筑部件，与「高年」不构成反义。"}, {"text": "课本", "is_correct": false, "explanation": "「课本」是学习用品，与「高年」不构成反义。"}], "correct_answer": "幼年", "explanations": {"幼年": "「幼年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。", "河流": "「河流」是地理事物，与「高年」没有反义关系。", "窗户": "「窗户」是建筑部件，与「高年」不构成反义。", "课本": "「课本」是学习用品，与「高年」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "童年", "is_correct": true, "explanation": "「童年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。"}, {"text": "树木", "is_correct": false, "explanation": "「树木」是植物，与「高年」没有反义关系。"}, {"text": "茶杯", "is_correct": false, "explanation": "「茶杯」是器物，与「高年」不构成反义。"}, {"text": "电话", "is_correct": false, "explanation": "「电话」是通讯工具，与「高年」不构成反义。"}], "correct_answer": "童年", "explanations": {"童年": "「童年」指人生的早期，与「高年」指年纪大的时期正相反，构成反义。", "树木": "「树木」是植物，与「高年」没有反义关系。", "茶杯": "「茶杯」是器物，与「高年」不构成反义。", "电话": "「电话」是通讯工具，与「高年」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年纪大的时期；老年。", "primary_collocate": null, "pronunciation": "gāo nián", "ipa": "kɑʊ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "人到高年，身体会慢慢变差。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷到了高年，每天都去公园走路。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入高年以后，他很少出远门。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在高年时还喜欢读书写字。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母步入高年，子女应多陪伴他们。", "target_word": "高年", "complexity_tier": "T3", "furigana": "gāo nián", "sentence_source": "generated"}, {"text": "我希望自己的高年过得健康快乐。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人到高年，记性常常不如以前。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的高年过得很平静。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了高年，他才有时间好好休息。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高年的时候，奶奶住在女儿家。", "target_word": "高年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "年纪大的时期；老年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54cdf3f2-e251-4733-85cf-17180d6e4543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高年", "is_correct": true, "explanation": "高年：指年纪大的时期，与「人到……身体会慢慢变差」的语境相符。"}, {"text": "青年", "is_correct": false, "explanation": "语义：「青年」指年轻的时期，与「身体会慢慢变差」的衰老语境相反。"}, {"text": "童年", "is_correct": false, "explanation": "语义：「童年」指孩童时期，说人到童年身体变差与句意不合。"}, {"text": "年终", "is_correct": false, "explanation": "搭配：「年终」指一年的末尾，是时间点而非人生阶段，不能说「人到年终」。"}], "explanations": {"高年": "高年：指年纪大的时期，与「人到……身体会慢慢变差」的语境相符。", "青年": "语义：「青年」指年轻的时期，与「身体会慢慢变差」的衰老语境相反。", "童年": "语义：「童年」指孩童时期，说人到童年身体变差与句意不合。", "年终": "搭配：「年终」指一年的末尾，是时间点而非人生阶段，不能说「人到年终」。"}, "sentence_index": 0, "correct_answer": "高年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他读六年级，是学校里的高年学生。", "explanation": "这里应该用〈高年级〉。「高年」指人生的老年时期，不指学校的年级，所以「高年学生」不通。"}, {"text": "这台高年电脑运行得很快。", "explanation": "这里应该用〈旧〉。「高年」指人年纪大的时期，不能用来形容电脑。"}, {"text": "我妈妈每周都去高年大学学画画。", "explanation": "这里应该用〈老年〉。「老年大学」是固定说法，「高年」不能修饰「大学」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高年", "is_correct": true, "explanation": "高年：指年纪大的时期，与「人到……记性常常不如以前」的衰退语境相符。"}, {"text": "少年", "is_correct": false, "explanation": "语义：「少年」指年纪小的时期，与「记性不如以前」的衰退语境相矛盾。"}, {"text": "幼年", "is_correct": false, "explanation": "语义：「幼年」指孩童时期，与「记性常常不如以前」相矛盾。"}, {"text": "雨季", "is_correct": false, "explanation": "语义：「雨季」指一年中多雨的时段，不指人的年龄阶段，与「记性不如以前」不符。"}], "explanations": {"高年": "高年：指年纪大的时期，与「人到……记性常常不如以前」的衰退语境相符。", "少年": "语义：「少年」指年纪小的时期，与「记性不如以前」的衰退语境相矛盾。", "幼年": "语义：「幼年」指孩童时期，与「记性常常不如以前」相矛盾。", "雨季": "语义：「雨季」指一年中多雨的时段，不指人的年龄阶段，与「记性不如以前」不符。"}, "sentence_index": 6, "correct_answer": "高年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的高年很长。", "explanation": "这里应该用〈长度〉。「高年」指人年纪大的时期，不能用来说河流的长短。"}, {"text": "这个高年我们要参加期末考试。", "explanation": "这里应该用〈学期〉。「高年」指人生的老年时期，不指学校的时间单位。"}, {"text": "他十八岁时在高年读书。", "explanation": "这里应该用〈高中〉。「高年」指老年时期，与「十八岁」矛盾，也不指学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲这一只高年过得很充实。", "corrected_sentence": "父亲这一段高年过得很充实。", "error_description": "「高年」指一段时期，量词应用「段」，不能用「只」（「只」用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90292, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这一场高年过得很幸福。", "corrected_sentence": "她这一段高年过得很幸福。", "error_description": "「高年」指一段时期，量词应用「段」，不能用「场」（「场」多用于比赛、雨等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
