INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90295, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己觉得很开心、很满意。", "primary_collocate": null, "pronunciation": "zì dé", "ipa": "tsɨ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "考了第一名，他脸上带着自得的笑。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看着自己做的蛋糕，神情十分自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着自己的画，心里很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟赢了比赛，自得地唱起歌来。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说起自己的工作，一脸自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿上新衣服，在镜子前自得地转了一圈。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板对这次生意很满意，显得很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写完文章，自得地读了一遍。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然得了奖，他也没有露出自得的样子。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王做对了难题，在同学面前有点自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洋洋自得", "label": "复合"}, {"form": "自得其乐", "label": "复合"}], "register": "书面", "sense_fingerprint": "自得：对自己的成绩或作品感到得意满意（神情流露出开心）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781f7237-455d-43e9-a284-e6dad8f125c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90295, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”表示因成绩而得意满足，与“考了第一名”的语境相符。"}, {"text": "委屈", "is_correct": false, "explanation": "语义：考了第一名，“委屈”的情绪与语境矛盾。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：考了第一名，“悲伤”与语境相反。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容笑。"}], "explanations": {"自得": "“自得”表示因成绩而得意满足，与“考了第一名”的语境相符。", "委屈": "语义：考了第一名，“委屈”的情绪与语境矛盾。", "悲伤": "语义：考了第一名，“悲伤”与语境相反。", "咸": "搭配：“咸”形容味道，不能用来形容笑。"}, "sentence_index": 0, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他输了比赛，哭得很自得。", "explanation": "“自得”表示得意满足，输了比赛后大哭不是这种心情；这里应该用〈伤心〉。"}, {"text": "他摔了一跤，疼得龇牙咧嘴，却很自得。", "explanation": "“自得”表示得意满足，摔跤后疼得龇牙咧嘴，不会感到满足；这里应该用〈痛苦〉。"}, {"text": "听到雷声，他自得地躲进了被子。", "explanation": "“自得”表示得意满足，因雷声而躲进被子不是得意的表现；这里应该用〈害怕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90295, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”表示对结果满意、得意，与“满意”的语境相符。"}, {"text": "愁苦", "is_correct": false, "explanation": "语义：前句写老板“很满意”，“愁苦”与之矛盾。"}, {"text": "惊慌", "is_correct": false, "explanation": "语义：生意顺利时，“惊慌”的情绪与语境不符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“显得很”后不接描写声音的“清脆”，搭配不当。"}], "explanations": {"自得": "“自得”表示对结果满意、得意，与“满意”的语境相符。", "愁苦": "语义：前句写老板“很满意”，“愁苦”与之矛盾。", "惊慌": "语义：生意顺利时，“惊慌”的情绪与语境不符。", "清脆": "搭配：“显得很”后不接描写声音的“清脆”，搭配不当。"}, "sentence_index": 6, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在海边晒太阳，自得地喝着茶。", "explanation": "这句说的是悠闲舒适，属于另一个义项，与本句“因成绩而得意”的意思不同。"}, {"text": "他被老师当场问住，自得地低下了头。", "explanation": "“自得”表示得意满足，被问住时的心理应是〈慌张〉。"}, {"text": "小王考试不及格，回家后显得很自得。", "explanation": "“自得”表示得意满足，与考试不及格的处境矛盾；这里应该用〈沮丧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对自己的画很自得地。", "corrected_sentence": "他对自己的画很自得。", "error_description": "错误：“很自得”作谓语，句末不能加“地”，“地”后面没有动词，应去掉〈地〉，说〈很自得〉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他洋洋自得的走进教室，好像什么都知道。", "corrected_sentence": "他洋洋自得地走进教室，好像什么都知道。", "error_description": "错误：“洋洋自得”作状语修饰动词“走进”，状语后应用〈地〉，不能用〈的〉，应说〈洋洋自得地走进教室〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "自己感到舒适满意。", "primary_collocate": null, "pronunciation": "zì dé", "ipa": "tsɨ˥˩ tɤ˧˥", "syllable_count": 2, "sentences": [{"text": "老人坐在院子里喝茶，样子很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在家看书，过得十分自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫躺在阳光下，看上去很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后养花钓鱼，过得悠闲自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她靠在沙发上听音乐，神态自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的老人钓着鱼，自得地晒着太阳。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山里住着，每天安静又自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上玩，一个个都很自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶躺在椅子上，自得地听着收音机。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末他在家泡茶看书，日子过得自得。", "target_word": "自得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自得其乐", "label": "复合"}, {"form": "悠闲自得", "label": "复合"}], "register": "书面", "sense_fingerprint": "自得：悠闲舒适、自己感到惬意（多用于休闲安逸的场景）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '781f7237-455d-43e9-a284-e6dad8f125c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”形容悠闲舒适的样子，与“坐在院子里喝茶”的情境相符。"}, {"text": "紧张", "is_correct": false, "explanation": "语义：“坐在院子里喝茶”是悠闲场景，“紧张”与之矛盾。"}, {"text": "匆忙", "is_correct": false, "explanation": "语义：“坐着喝茶”是从容的状态，“匆忙”与之矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“样子”后不接描写声音的“清脆”，二者搭配不当。"}], "explanations": {"自得": "“自得”形容悠闲舒适的样子，与“坐在院子里喝茶”的情境相符。", "紧张": "语义：“坐在院子里喝茶”是悠闲场景，“紧张”与之矛盾。", "匆忙": "语义：“坐着喝茶”是从容的状态，“匆忙”与之矛盾。", "清脆": "搭配：“样子”后不接描写声音的“清脆”，二者搭配不当。"}, "sentence_index": 0, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在办公室里忙得很自得。", "explanation": "“自得”形容悠闲舒适的状态，不能形容忙碌；这里应该用〈紧张〉。"}, {"text": "他被蚊子咬了一夜，浑身很自得。", "explanation": "“自得”表示舒适满意，被蚊子咬了一夜后不可能感到舒适，这里应该用〈难受〉。"}, {"text": "得知自己被开除以后，他唉声叹气，过得很自得。", "explanation": "“自得”表示悠闲舒适，与“唉声叹气”的沮丧处境矛盾；这里应该用〈沮丧〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自得", "is_correct": true, "explanation": "“自得”表示安逸舒适，与“安静”并列，符合语境。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：前半句说“安静”，“吵闹”与之直接矛盾。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”与前面的“安静”意思相反，句意不通。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”描写空间，不能与“每天”的生活状态并列。"}], "explanations": {"自得": "“自得”表示安逸舒适，与“安静”并列，符合语境。", "吵闹": "语义：前半句说“安静”，“吵闹”与之直接矛盾。", "热闹": "语义：“热闹”与前面的“安静”意思相反，句意不通。", "狭窄": "搭配：“狭窄”描写空间，不能与“每天”的生活状态并列。"}, "sentence_index": 6, "correct_answer": "自得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在工地上搬砖，累得直不起腰，过得很自得。", "explanation": "“自得”表示悠闲舒适，搬砖劳累，与之矛盾；这里应该用〈辛苦〉。"}, {"text": "一只大狗扑过来，他吓得直往后退，还显得很自得。", "explanation": "“自得”表示舒适满意，被狗吓得直往后退的情境与之矛盾；这里应该用〈害怕〉。"}, {"text": "他迟到了一个小时，被老师批评后一直低着头，显得很自得。", "explanation": "“自得”表示舒适满意，被批评后一直低头，与之矛盾；这里应该用〈难堪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他自得的坐在门口晒太阳。", "corrected_sentence": "他自得地坐在门口晒太阳。", "error_description": "错误：“自得”作状语修饰动词时要用助词〈地〉，不能用〈的〉。应为“自得地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在山里住着，过的悠闲自得。", "corrected_sentence": "他在山里住着，过得悠闲自得。", "error_description": "错误：“过得”后的“得”是补语标记，不能写成“的”，应为〈过得悠闲自得〉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2879e72f-6781-4c6d-9b17-1ae2612c3a76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
