INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "金色是像金子一样亮亮的黄颜色。", "primary_collocate": null, "pronunciation": "jīn sè", "ipa": "tɕin˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "金色的沙子在海边闪闪发光。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用金色的笔写了名字。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕阳下，河水变成了金色。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩戴着金色的帽子。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上有一个金色的大字。", "target_word": "金色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "树叶到了秋天会变成金色。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的封面是金色的。", "target_word": "金色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想买一块金色的手表。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金色的麦田一眼看不到头。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯光是金色的，房间很温暖。", "target_word": "金色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "金黄色", "label": "复合"}], "register": "中性", "sense_fingerprint": "像金子一样发亮的黄色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "金色", "is_correct": true, "explanation": "正确。“金色的沙子在海边闪闪发光”：沙子呈金黄色，并在阳光下发亮，符合语境。"}, {"text": "木头", "is_correct": false, "explanation": "语义：沙子不是木头，“木头的沙子”句意不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“的”后修饰沙子的应是颜色或质地，“声音”不能修饰沙子。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“雨的沙子”不成立，雨不是沙子的属性。"}], "explanations": {"金色": "正确。“金色的沙子在海边闪闪发光”：沙子呈金黄色，并在阳光下发亮，符合语境。", "木头": "语义：沙子不是木头，“木头的沙子”句意不通。", "声音": "搭配：“的”后修饰沙子的应是颜色或质地，“声音”不能修饰沙子。", "雨": "语义：“雨的沙子”不成立，雨不是沙子的属性。"}, "sentence_index": 0, "correct_answer": "金色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行存了一份金色。", "explanation": "这里应该存“金子”。“存”的对象是钱或物品，“金色”是颜色，不能存。"}, {"text": "这顶帽子是金色做的，很漂亮。", "explanation": "这里应该用“金子”。“是……做的”要接材料名词，“金色”是颜色，不能作材料。"}, {"text": "她买了一个金色，戴在头上很好看。", "explanation": "这里有两处问题：“金色”是颜色，不能买；颜色名词也不用“个”，应说“一种金色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "金色", "is_correct": true, "explanation": "正确。“这本书的封面是金色的”：封面的颜色是金色，符合语境。"}, {"text": "夜晚", "is_correct": false, "explanation": "搭配：“是……的”要接颜色或质地，“夜晚”是时间，不能作封面的属性。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：封面不是声音，“封面是歌声的”句意不通。"}, {"text": "雷", "is_correct": false, "explanation": "语义：封面不可能是雷，“封面是雷的”句意不通。"}], "explanations": {"金色": "正确。“这本书的封面是金色的”：封面的颜色是金色，符合语境。", "夜晚": "搭配：“是……的”要接颜色或质地，“夜晚”是时间，不能作封面的属性。", "歌声": "语义：封面不是声音，“封面是歌声的”句意不通。", "雷": "语义：封面不可能是雷，“封面是雷的”句意不通。"}, "sentence_index": 6, "correct_answer": "金色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯有一个金色，房间很温暖。", "explanation": "这里的量词应用“种”。“一个金色”的量词用错，颜色名词应说“一种金色”。"}, {"text": "他的眼睛闪着金色，很漂亮。", "explanation": "这里应该说“闪着金光”。“金色”是颜色，不能直接作“闪着”的宾语。"}, {"text": "灯光是金色做的，房间很温暖。", "explanation": "这里应该用“金子”。“是……做的”要接材料名词，“金色”是颜色，不能作材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "海边的夕阳是一个金色，很美。", "corrected_sentence": "海边的夕阳是一种金色，很美。", "error_description": "错误形式：“一个金色”；正确形式：“一种金色”。颜色名词“金色”作量词搭配时用“种”，不用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块玻璃的金色的很亮。", "corrected_sentence": "这块玻璃的金色很亮。", "error_description": "错误：“金色”后多加了一个“的”。“玻璃的金色”是名词短语，后面直接接谓语“很亮”，不应再加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
