INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90327, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人卖东西，一个人买东西；也指做生意。", "primary_collocate": null, "pronunciation": "mǎi mai", "ipa": "maɪ˨˩˦ maɪ", "syllable_count": 2, "sentences": [{"text": "他们俩谈成了一笔买卖。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一桩公平的买卖，我们都满意。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在网上做买卖，每天都很忙。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔买卖我亏了二百块钱。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买卖双方都要在合同上签字。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，做买卖要讲信用。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次买卖，他赚了一点钱。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢做买卖。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的买卖很红火。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李不做买卖了，回老家种地。", "target_word": "买卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔买卖", "label": "量词（笔）"}, {"form": "一桩买卖", "label": "量词（桩）"}, {"form": "買賣", "label": "繁体"}], "register": "口语", "sense_fingerprint": "买卖：一买一卖的交易，也指生意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4809b0-ba75-480f-b901-0e7163480787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90327, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗产", "is_correct": false, "explanation": "语义：遗产是继承来的，不是谈成的交易。"}, {"text": "友谊", "is_correct": false, "explanation": "搭配：“一笔”不用来计量友谊，“谈成”也不搭配友谊。"}, {"text": "买卖", "is_correct": true, "explanation": "“买卖”指一买一卖的交易，与“谈成”相合。"}, {"text": "爱情", "is_correct": false, "explanation": "语义：爱情不能“谈成一笔”作交易讲。"}], "explanations": {"遗产": "语义：遗产是继承来的，不是谈成的交易。", "友谊": "搭配：“一笔”不用来计量友谊，“谈成”也不搭配友谊。", "买卖": "“买卖”指一买一卖的交易，与“谈成”相合。", "爱情": "语义：爱情不能“谈成一笔”作交易讲。"}, "sentence_index": 0, "correct_answer": "买卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们俩谈成了一座买卖。", "explanation": "这里应该用〈笔〉。买卖作交易讲，量词用“笔”或“桩”；“座”用于山、楼等大型物体。"}, {"text": "他是我的买卖，每次都付现金。", "explanation": "这里应该用〈买主〉。买卖指交易，不能指人。"}, {"text": "老张每天都用买卖看新闻。", "explanation": "这里应该用〈手机〉。买卖指交易或生意，不能当作看新闻的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90327, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：考试是考核，不能赚钱。"}, {"text": "幸福", "is_correct": false, "explanation": "搭配：“这次”修饰事件，不修饰“幸福”这类状态。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是病，与赚钱无关。"}, {"text": "买卖", "is_correct": true, "explanation": "“买卖”指一次交易，与“赚了钱”相合。"}], "explanations": {"考试": "语义：考试是考核，不能赚钱。", "幸福": "搭配：“这次”修饰事件，不修饰“幸福”这类状态。", "感冒": "语义：感冒是病，与赚钱无关。", "买卖": "“买卖”指一次交易，与“赚了钱”相合。"}, "sentence_index": 6, "correct_answer": "买卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "买卖每天都在店里放。", "explanation": "这里应该用〈音乐〉。买卖指交易或生意，不是可以在店里播放的东西。"}, {"text": "他上个月参加了一场买卖。", "explanation": "这里应该用〈比赛〉。买卖指交易或生意，不能用“参加一场”来表示比赛。"}, {"text": "我的买卖很喜欢下棋。", "explanation": "这里应该用〈爷爷〉。买卖指交易或生意，不能做“喜欢下棋”这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩去年谈成了一本大买卖。", "corrected_sentence": "他们俩去年谈成了一笔大买卖。", "error_description": "量词错误：“买卖”作交易讲，应用“笔”计量；“本”用于书籍，应改为“一笔大买卖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们之前过做一笔买卖，那次很顺利。", "corrected_sentence": "我们之前做过一笔买卖，那次很顺利。", "error_description": "体标位置错误：经历体“过”应紧跟动词“做”，写作“做过一笔买卖”；“过做一笔买卖”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
