INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "首次建立或开创。", "primary_collocate": null, "pronunciation": "chuàng jiàn", "ipa": "tʂʰuɑŋ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这所大学创建于一百年前。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孙中山创建了中华民国。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授创建了国内第一个考古研究所。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在一九五〇年创建了这家报社。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市是古人在河边创建的。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老先生创建了这个学会，已有三十年。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府创建了一个新的研究中心。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社创建以来，出过很多好书。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生创建过三所医院。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司创建的第一年，只有五个人。", "target_word": "创建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创建了", "label": "完成体"}, {"form": "创建过", "label": "经历体"}, {"form": "创建者", "label": "复合词"}], "register": "书面", "sense_fingerprint": "创建：首次建立或开创机构、学校、城市等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da068f4-1758-479c-9a13-02dccfe2d5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：首次建立这所大学，与「一百年前」的开办时间相符。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：「出版」用于书籍、报刊，不能用于大学。"}, {"text": "出生", "is_correct": false, "explanation": "配价：「出生」的主语应是人或动物，大学不能出生。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：「发表」用于文章、言论，不能用来说大学的成立。"}], "explanations": {"创建": "创建：首次建立这所大学，与「一百年前」的开办时间相符。", "出版": "搭配：「出版」用于书籍、报刊，不能用于大学。", "出生": "配价：「出生」的主语应是人或动物，大学不能出生。", "发表": "搭配：「发表」用于文章、言论，不能用来说大学的成立。"}, "sentence_index": 0, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在一九五〇年创建了这座大桥。", "explanation": "这里应该用〈修建〉。创建指首次建立机构或城市；桥梁这类实体工程要用修建。"}, {"text": "他们在一九五〇年创建了这部小说。", "explanation": "这里应该用〈写〉。创建用于建立机构或城市；小说是写出来的作品，应说写。"}, {"text": "他们在一九五〇年创建了这只船。", "explanation": "这里应该用〈造〉。创建用于建立机构或城市；船只这类器物要用造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创建", "is_correct": true, "explanation": "创建：首次建立了这个研究中心，与句意相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：「拆除」指拆掉已有的建筑，与「新的研究中心」相矛盾。"}, {"text": "派遣", "is_correct": false, "explanation": "配价：「派遣」的宾语应是人，不能派遣一个研究中心。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：「摔」常用于杯子、东西等，不能用来指建立研究中心。"}], "explanations": {"创建": "创建：首次建立了这个研究中心，与句意相符。", "拆除": "语义：「拆除」指拆掉已有的建筑，与「新的研究中心」相矛盾。", "派遣": "配价：「派遣」的宾语应是人，不能派遣一个研究中心。", "摔": "搭配：「摔」常用于杯子、东西等，不能用来指建立研究中心。"}, "sentence_index": 6, "correct_answer": "创建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位工程师创建了一种新型发动机。", "explanation": "这里应该用〈研制〉。创建指建立机构或账号等；发动机这类技术产品要用研制。"}, {"text": "这位画家创建了一座新房子。", "explanation": "这里应该用〈建造〉。创建用于建立机构、账号等；房子这类建筑要用建造。"}, {"text": "孩子们在草地上创建了一个沙堡。", "explanation": "这里应该用〈堆〉。创建用于建立机构或城市；沙堡是堆出来的，应说堆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个协会创建在上世纪三十年代。", "corrected_sentence": "这个协会创建于上世纪三十年代。", "error_description": "介词错误：「创建」后面接时间时应用介词「于」，说「创建于」，不能用「在」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学院创建了以来，培养了很多人才。", "corrected_sentence": "这所学院创建以来，培养了很多人才。", "error_description": "动态助词错误：「创建以来」是固定的时间表达，「创建」之后不能加「了」，应说「创建以来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
