INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人去世后留下来的东西或钱。", "primary_collocate": null, "pronunciation": "yí chǎn", "ipa": "i˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "爷爷去世后，留下了一笔遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲的遗产有一套房子和一些钱。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人没有孩子，遗产给了他的侄子。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用母亲留下的遗产开了一家小店。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟两人为了遗产吵了起来。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不要父母的遗产，想自己赚钱。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师正在帮大家分遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把所有遗产都捐给了学校。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他继承了叔叔的遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从没想过要拿父亲的遗产。", "target_word": "遗产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔遗产", "label": "量词"}, {"form": "一份遗产", "label": "量词"}, {"form": "遺產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人去世后留给家人的钱和财物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遗产", "is_correct": true, "explanation": "正确。「一笔」与「遗产」搭配，指人去世后留下的钱或财物，符合句意。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：量词「笔」用于钱款，不能说「一笔房子」，应说「一套房子」。"}, {"text": "故事", "is_correct": false, "explanation": "语义：去世后留下的应是钱财，「故事」不属于遗产的范畴，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是个人用品，不能用「一笔」计量，也不符合「留下财产」的意思。"}], "explanations": {"遗产": "正确。「一笔」与「遗产」搭配，指人去世后留下的钱或财物，符合句意。", "房子": "搭配：量词「笔」用于钱款，不能说「一笔房子」，应说「一套房子」。", "故事": "语义：去世后留下的应是钱财，「故事」不属于遗产的范畴，句意不通。", "眼镜": "语义：眼镜是个人用品，不能用「一笔」计量，也不符合「留下财产」的意思。"}, "sentence_index": 0, "correct_answer": "遗产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直牢记祖父的遗产，努力做人。", "explanation": "这里应该用〈遗训〉。「牢记」的对象是教导和嘱托，遗产是财物，不能「牢记」。"}, {"text": "老人的遗产被安放在大厅里。", "explanation": "这里应该用〈遗体〉。「安放」的对象是遗体，遗产是财物，不能被安放。"}, {"text": "爷爷临终前写下了遗产。", "explanation": "这里应该用〈遗嘱〉。写下的是遗嘱这种文件，遗产是留下的财物，不能「写下」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遗产", "is_correct": true, "explanation": "正确。「分」的对象是遗产，指按继承人分配死者留下的财物，符合句意。"}, {"text": "方向", "is_correct": false, "explanation": "语义：「分」用于分配物品，「方向」不能被分配，不符合句意。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：「分」不与「脚步」搭配，人们不说「分脚步」。"}, {"text": "影子", "is_correct": false, "explanation": "语义：「影子」是光线形成的影像，不能作为分配的对象。"}], "explanations": {"遗产": "正确。「分」的对象是遗产，指按继承人分配死者留下的财物，符合句意。", "方向": "语义：「分」用于分配物品，「方向」不能被分配，不符合句意。", "脚步": "搭配：「分」不与「脚步」搭配，人们不说「分脚步」。", "影子": "语义：「影子」是光线形成的影像，不能作为分配的对象。"}, "sentence_index": 6, "correct_answer": "遗产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父亲的遗产很安详，大家都来告别。", "explanation": "这里应该用〈遗容〉。「安详」形容的是人的神态，遗产是财物，不能这样用。"}, {"text": "父亲的遗产一直是我的座右铭。", "explanation": "这里应该用〈遗言〉。「座右铭」是用来勉励自己的话，遗产是财物，不能这样用。"}, {"text": "他终于完成了父亲的遗产。", "explanation": "这里应该用〈遗愿〉。「完成」的对象是心愿或任务，遗产是财物，不能「完成」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸留下了一位遗产，我们很感激。", "corrected_sentence": "爸爸留下了一份遗产，我们很感激。", "error_description": "错误形式「留下了一位遗产」；正确形式「留下了一份遗产」。「位」是用于人的量词，「遗产」不是人，应使用「份」或「笔」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经继承过父亲的一位遗产。", "corrected_sentence": "他曾经继承过父亲的一份遗产。", "error_description": "错误形式「一位遗产」；正确形式「一份遗产」。「位」用于人，「遗产」应使用「份」，此处应说「一份遗产」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有事", "is_correct": true, "explanation": "“有事”表示有麻烦、出了事，与“没有事”（平安无麻烦）构成反义。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌好看，与“没有事”（平安无麻烦）没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情愉快，与“没有事”（平安无麻烦）没有反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”形容价格低，与“没有事”（平安无麻烦）没有反义关系。"}], "correct_answer": "有事", "explanations": {"有事": "“有事”表示有麻烦、出了事，与“没有事”（平安无麻烦）构成反义。", "漂亮": "“漂亮”形容外貌好看，与“没有事”（平安无麻烦）没有反义关系。", "高兴": "“高兴”形容心情愉快，与“没有事”（平安无麻烦）没有反义关系。", "便宜": "“便宜”形容价格低，与“没有事”（平安无麻烦）没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有问题", "is_correct": true, "explanation": "“有问题”表示出了问题，与“没有事”（没出问题）构成反义。"}, {"text": "冷静", "is_correct": false, "explanation": "“冷静”形容情绪平稳，与“没有事”（没出问题）没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧哗，与“没有事”（没出问题）没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容没有污物，与“没有事”（没出问题）没有反义关系。"}], "correct_answer": "有问题", "explanations": {"有问题": "“有问题”表示出了问题，与“没有事”（没出问题）构成反义。", "冷静": "“冷静”形容情绪平稳，与“没有事”（没出问题）没有反义关系。", "热闹": "“热闹”形容场面喧哗，与“没有事”（没出问题）没有反义关系。", "干净": "“干净”形容没有污物，与“没有事”（没出问题）没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有事是没有麻烦，也没有出问题，大家都好。", "primary_collocate": null, "pronunciation": "méi yǒu shì", "ipa": "meɪ˧˥ joʊ˨˩ ʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你放心，家里一切都没有事。", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他没有事，让我们别担心。", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说你生病了，现在没有事了吗？", "target_word": "没有事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给妈妈打电话，说我这里没有事。", "target_word": "没有事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束了，大家都没有事。", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查完了，医生说宝宝没有事。", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看起来很累，真的没有事吗？", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大风过去了，我们的房子没有事。", "target_word": "没有事", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着对我说：“我没有事，你回去吧。”", "target_word": "没有事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的问题已经解决了，现在没有事了。", "target_word": "没有事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "没事", "label": "变体"}, {"form": "没有事儿", "label": "变体"}], "register": "口语", "sense_fingerprint": "平安无麻烦，一切正常", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54cdf3f2-e251-4733-85cf-17180d6e4543') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没有事", "is_correct": true, "explanation": "“没有事”表示平安、没有麻烦，与“你放心”的安慰语气相符。"}, {"text": "危险", "is_correct": false, "explanation": "语义：“危险”表示有安全隐患，与“你放心”的安慰意思相反。"}, {"text": "糟糕", "is_correct": false, "explanation": "语义：“糟糕”表示情况很差，与“你放心”的语气矛盾。"}, {"text": "混乱", "is_correct": false, "explanation": "搭配：“混乱”多用于局面、秩序，说“家里一切都混乱”不自然。"}], "explanations": {"没有事": "“没有事”表示平安、没有麻烦，与“你放心”的安慰语气相符。", "危险": "语义：“危险”表示有安全隐患，与“你放心”的安慰意思相反。", "糟糕": "语义：“糟糕”表示情况很差，与“你放心”的语气矛盾。", "混乱": "搭配：“混乱”多用于局面、秩序，说“家里一切都混乱”不自然。"}, "sentence_index": 0, "correct_answer": "没有事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天一天都在开会，根本没有事去接你。", "explanation": "这里应该用〈没有空〉。“没有事”表示没出问题，用在这里说不通；句意是没有时间去接人，应说“没有空”。"}, {"text": "他的病越来越严重，现在已经没有事了。", "explanation": "这里应该用〈好转〉。病情好转要说“好转”，“没有事”指没出问题，与“越来越严重”矛盾。"}, {"text": "这座桥的钢索都断了，它却没有事，大家放心走吧。", "explanation": "这里应该用〈不安全〉。形容桥梁有危险要说“不安全”，“没有事”指没出问题，不能用来说明桥的危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没有事", "is_correct": true, "explanation": "“没有事”表示身体没有问题，与“你看起来很累”的关心语气相符。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”指有钱，与“你看起来很累”的情况不相关，句子不通。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容智力，与“看起来很累”无关，句子意思说不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，不能用来描述“看起来很累”的状态。"}], "explanations": {"没有事": "“没有事”表示身体没有问题，与“你看起来很累”的关心语气相符。", "富有": "语义：“富有”指有钱，与“你看起来很累”的情况不相关，句子不通。", "聪明": "语义：“聪明”形容智力，与“看起来很累”无关，句子意思说不通。", "高大": "体貌：“高大”形容身材，不能用来描述“看起来很累”的状态。"}, "sentence_index": 6, "correct_answer": "没有事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛我们没有事，大家都很难过。", "explanation": "这里应该用〈输了〉。比赛结果不好要说“输了”，“没有事”指没出问题，不能用来说明比赛结果。"}, {"text": "这次手术没有事，病人还在抢救。", "explanation": "这里应该用〈失败〉。手术没有成功要说“失败”，“没有事”指没出问题，与“还在抢救”矛盾。"}, {"text": "失恋以后，她一直没有事，哭了一整天。", "explanation": "这里应该用〈伤心〉。难过痛苦要说“伤心”，“没有事”指没出问题，与“哭了一整天”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈问我在学校怎么样，我说一切都没有没有事。", "corrected_sentence": "妈妈问我在学校怎么样，我说一切都没有事。", "error_description": "否定词重复：“没有事”前多加了一个“没有”，应去掉多余的“没有”，说“我说一切都没有事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子摔了一跤，但是医生说他很没有事。", "corrected_sentence": "孩子摔了一跤，但是医生说他没有事。", "error_description": "“没有事”前面不能加程度副词“很”，应去掉“很”，说“他没有事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d74a0e-820d-46f2-b8cb-b4c1d6317f2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整齐", "is_correct": true, "explanation": "正确：“整齐”与“混乱”是反义词，都说东西摆放得有没有秩序。"}, {"text": "辽阔", "is_correct": false, "explanation": "“辽阔”说空间广大，与“混乱”不构成反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "“响亮”说声音大而清楚，与“混乱”没有反义关系。"}, {"text": "光滑", "is_correct": false, "explanation": "“光滑”说表面平整，与“混乱”不构成反义关系。"}], "correct_answer": "整齐", "explanations": {"整齐": "正确：“整齐”与“混乱”是反义词，都说东西摆放得有没有秩序。", "辽阔": "“辽阔”说空间广大，与“混乱”不构成反义关系。", "响亮": "“响亮”说声音大而清楚，与“混乱”没有反义关系。", "光滑": "“光滑”说表面平整，与“混乱”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有序", "is_correct": true, "explanation": "正确：“有序”与“混乱”是反义词，都说队伍或事物的次序好坏。"}, {"text": "陡峭", "is_correct": false, "explanation": "“陡峭”说地势高低起伏，与“混乱”不构成反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”说温度低，与“混乱”不构成反义关系。"}, {"text": "圆润", "is_correct": false, "explanation": "“圆润”说形状或声音饱满，与“混乱”不构成反义关系。"}], "correct_answer": "有序", "explanations": {"有序": "正确：“有序”与“混乱”是反义词，都说队伍或事物的次序好坏。", "陡峭": "“陡峭”说地势高低起伏，与“混乱”不构成反义关系。", "寒冷": "“寒冷”说温度低，与“混乱”不构成反义关系。", "圆润": "“圆润”说形状或声音饱满，与“混乱”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "混乱是东西或人乱七八糟，一点也不整齐。", "primary_collocate": null, "pronunciation": "hùn luàn", "ipa": "xuən˥˩ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们玩完以后，客厅很混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书包里很混乱，什么都有。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服扔得到处都是，床上很混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，教室里混乱极了。", "target_word": "混乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房太混乱了，妈妈不高兴。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的书和笔弄得很混乱。", "target_word": "混乱", "complexity_tier": "T3", "furigana": "tā bǎ wǒ de shū hé bǐ nòng de hěn hùnluàn 。", "sentence_source": "generated"}, {"text": "他的桌子又脏又混乱。", "target_word": "混乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店的东西放得很混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的字写得很混乱，我看不清。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子跑来跑去，队伍很混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混乱不堪", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西或人乱七八糟不整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混乱", "is_correct": true, "explanation": "正确：“混乱”指东西乱七八糟，与“玩完以后”的语境相符。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不能用来形容客厅。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”指钱财或资源充足，不能用来形容客厅的状况。"}, {"text": "整洁", "is_correct": false, "explanation": "语义：“整洁”指干净有条理，与孩子们玩完以后的情境相矛盾。"}], "explanations": {"混乱": "正确：“混乱”指东西乱七八糟，与“玩完以后”的语境相符。", "苗条": "体貌：“苗条”形容人的身材，不能用来形容客厅。", "富有": "语义：“富有”指钱财或资源充足，不能用来形容客厅的状况。", "整洁": "语义：“整洁”指干净有条理，与孩子们玩完以后的情境相矛盾。"}, "sentence_index": 0, "correct_answer": "混乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的空气很混乱，大家都咳嗽。", "explanation": "这里应该用〈混浊〉。混浊指空气里杂质多、不清新，用于空气、水；混乱说的是秩序乱，不用来形容空气的洁净程度。"}, {"text": "这碗汤的味道很混乱，不知道放了什么。", "explanation": "这里应该用〈复杂〉。复杂指味道、情况等由多种因素构成；混乱说的是没有秩序，不用来形容味道的层次。"}, {"text": "孩子看见大狗，混乱地躲到了妈妈身后。", "explanation": "这里应该用〈慌张〉。慌张形容人因害怕而乱了阵脚，可以修饰人的动作；混乱说的是事物没有秩序，不用来形容人的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混乱", "is_correct": true, "explanation": "正确：“混乱”指桌上东西乱七八糟，与“又脏又”的语境相符。"}, {"text": "清晰", "is_correct": false, "explanation": "搭配：“清晰”说文字、声音或图像看得分明，不能用来形容桌子的状况。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来形容桌子。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”与“脏”的语境相反，“又脏又明亮”自相矛盾。"}], "explanations": {"混乱": "正确：“混乱”指桌上东西乱七八糟，与“又脏又”的语境相符。", "清晰": "搭配：“清晰”说文字、声音或图像看得分明，不能用来形容桌子的状况。", "甜": "搭配：“甜”形容味道，不能用来形容桌子。", "明亮": "语义：“明亮”与“脏”的语境相反，“又脏又明亮”自相矛盾。"}, "sentence_index": 6, "correct_answer": "混乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的发音很混乱，老师听不懂。", "explanation": "这里应该用〈含糊〉。含糊指发音不清楚；混乱说的是没有秩序，不用来形容发音的清晰度。"}, {"text": "她的身材很混乱，穿什么都不好看。", "explanation": "这里应该用〈匀称〉。匀称指身材各部分比例协调；混乱说的是事物没有秩序，不用来形容身材的比例。"}, {"text": "展厅里的作品良莠混乱。", "explanation": "这里应该用〈混杂〉。“良莠混杂”指好坏掺在一起；混乱只说秩序乱，不说好坏掺杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个混乱地房间让我找不到东西。", "corrected_sentence": "一个混乱的房间让我找不到东西。", "error_description": "错误形式：“混乱地房间”；正确形式：“混乱的房间”。“的”用于名词前作定语，“地”用于动词前作状语，“混乱”修饰名词“房间”时应用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的书包里东西混乱很。", "corrected_sentence": "他的书包里东西混乱得很。", "error_description": "错误形式：“混乱很”；正确形式：“混乱得很”。“得”作补语标记，须紧跟在形容词之后，构成“形容词+得+很”，缺少“得”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有条理", "is_correct": true, "explanation": "正确：“有条理”与“混乱”是反义词，都说事物有没有条理、次序。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”说声音或环境不吵闹，与“混乱”的无秩序义不构成反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”说光线充足，与“混乱”没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”说心情或事情不费力，与“混乱”不构成反义关系。"}], "correct_answer": "有条理", "explanations": {"有条理": "正确：“有条理”与“混乱”是反义词，都说事物有没有条理、次序。", "安静": "“安静”说声音或环境不吵闹，与“混乱”的无秩序义不构成反义关系。", "明亮": "“明亮”说光线充足，与“混乱”没有反义关系。", "轻松": "“轻松”说心情或事情不费力，与“混乱”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "整齐", "is_correct": true, "explanation": "正确：“整齐”与“混乱”是反义词，都说摆放或排列有没有秩序。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”说质地不硬，与“混乱”不构成反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "“清脆”形容声音，与“混乱”的无秩序义不相对。"}, {"text": "平坦", "is_correct": false, "explanation": "“平坦”说表面不起伏，与“混乱”不构成反义关系。"}], "correct_answer": "整齐", "explanations": {"整齐": "正确：“整齐”与“混乱”是反义词，都说摆放或排列有没有秩序。", "柔软": "“柔软”说质地不硬，与“混乱”不构成反义关系。", "清脆": "“清脆”形容声音，与“混乱”的无秩序义不相对。", "平坦": "“平坦”说表面不起伏，与“混乱”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "无秩序，无条理；杂乱。", "primary_collocate": null, "pronunciation": "hùn luàn", "ipa": "xuən˥˩ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "我的房间太混乱了，要收拾一下。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "马路上人和车很多，场面很混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，城市一片混乱。", "target_word": "混乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的想法很混乱，说不清楚。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束时，现场有点混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家同时说话，会议变得混乱。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活过得很混乱。", "target_word": "混乱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车站的秩序很混乱，大家都在挤。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份作业写得很混乱，老师看不懂。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书桌上很混乱，我找不到笔。", "target_word": "混乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混乱不堪", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有秩序和条理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干净", "is_correct": false, "explanation": "语义：“干净”与“要收拾一下”的语境矛盾，房间干净了就不需要收拾。"}, {"text": "混乱", "is_correct": true, "explanation": "正确：“混乱”指东西乱七八糟，与“要收拾一下”的语境相符。"}, {"text": "整齐", "is_correct": false, "explanation": "语义：“整齐”说摆放有序，房间整齐就用不着收拾，与句中的语境矛盾。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”说看得明白或说得明白，不能用来形容房间的整洁程度。"}], "explanations": {"干净": "语义：“干净”与“要收拾一下”的语境矛盾，房间干净了就不需要收拾。", "混乱": "正确：“混乱”指东西乱七八糟，与“要收拾一下”的语境相符。", "整齐": "语义：“整齐”说摆放有序，房间整齐就用不着收拾，与句中的语境矛盾。", "清楚": "搭配：“清楚”说看得明白或说得明白，不能用来形容房间的整洁程度。"}, "sentence_index": 0, "correct_answer": "混乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到敲门声，他混乱地站了起来。", "explanation": "这里应该用〈慌乱〉。慌乱形容人心慌意乱，可以修饰人的动作；混乱说的是事物没有秩序，不用来形容人慌张的动作。"}, {"text": "这杯水很混乱，根本没法喝。", "explanation": "这里应该用〈混浊〉。混浊指液体或空气里杂质多、不清澈，用于水、空气；混乱说的是秩序乱，不用来形容液体的清浊。"}, {"text": "这个市场鱼龙混乱，买东西要小心。", "explanation": "这里应该用〈混杂〉。“鱼龙混杂”是固定说法，指好坏掺在一起；混乱只说秩序乱，不说掺杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混乱", "is_correct": true, "explanation": "正确：“混乱”形容生活没有条理，与“过得很”搭配自然。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人的体型，不能用来说生活过得怎样。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的外形，用在生活状况上说不通。"}, {"text": "骄傲", "is_correct": false, "explanation": "语义：“骄傲”指自负或自豪，说的是人的心理，不能用来描述生活过得如何。"}], "explanations": {"混乱": "正确：“混乱”形容生活没有条理，与“过得很”搭配自然。", "胖": "体貌：“胖”形容人的体型，不能用来说生活过得怎样。", "高大": "体貌：“高大”形容人或物的外形，用在生活状况上说不通。", "骄傲": "语义：“骄傲”指自负或自豪，说的是人的心理，不能用来描述生活过得如何。"}, "sentence_index": 6, "correct_answer": "混乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很混乱，像是生了病。", "explanation": "这里应该用〈苍白〉或〈难看〉。混乱说的是事物没有秩序，不用来形容脸色；形容脸色应说“苍白”“难看”。"}, {"text": "这个病人的血压很混乱，需要马上吃药。", "explanation": "这里应该用〈不稳〉。血压不稳指数值忽高忽低；混乱说的是没有秩序，不用来形容血压。"}, {"text": "他的脾气很混乱，动不动就发火。", "explanation": "这里应该用〈暴躁〉。暴躁形容脾气急、易发火，用于人的脾气；混乱说的是没有秩序，不用来形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的房间混乱很，连床都看不见。", "corrected_sentence": "我的房间混乱得很，连床都看不见。", "error_description": "错误形式：“混乱很”；正确形式：“混乱得很”。“混乱”作谓语后，需用“得”引出程度补语，构成“形容词+得+很”，缺“得”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "广场上的人群混乱的挤在一起。", "corrected_sentence": "广场上的人群混乱地挤在一起。", "error_description": "错误形式：“混乱的挤在一起”；正确形式：“混乱地挤在一起”。修饰动词“挤”的状语要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
