INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "相比是把两个东西放在一起，看看哪个大，哪个小。", "primary_collocate": null, "pronunciation": "xiāng bǐ", "ipa": "ɕiaŋ˥ pi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张桌子和那张相比，大多了。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家和你家相比，你家的院子更大。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把两个苹果放在一起相比，红的大一点儿。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海相比，哪个城市人口多？", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和哥哥相比，我的个子小一些。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两座山相比，左边的更高。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与小河相比，大海宽多了。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个箱子相比，这个重，那个轻。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把新书和旧书相比，新书厚得多。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路和那条路相比，长一点儿。", "target_word": "相比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "相比之下", "label": "复合"}], "register": "中性", "sense_fingerprint": "相比：把两个东西放在一起比大小、高低", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相比", "is_correct": true, "explanation": "相比：把两个东西放在一起比大小，这里指两张桌子比大小。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洁的动作，与比较桌子大小无关，句子不通。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”需要搬运的对象和去处，“和那张搬”不能构成比较，句子不通。"}, {"text": "摆放", "is_correct": false, "explanation": "语义：“摆放”指把物品摆好，不表示比大小，与“大多了”不相容。"}], "explanations": {"相比": "相比：把两个东西放在一起比大小，这里指两张桌子比大小。", "洗": "语义：“洗”是清洁的动作，与比较桌子大小无关，句子不通。", "搬": "配价：“搬”需要搬运的对象和去处，“和那张搬”不能构成比较，句子不通。", "摆放": "语义：“摆放”指把物品摆好，不表示比大小，与“大多了”不相容。"}, "sentence_index": 0, "correct_answer": "相比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们相比三年后结了婚。", "explanation": "这里应该用〈相识〉。相比表示比较，不表示认识；“相识三年后结婚”才对。"}, {"text": "他俩在电影院里相比，看了一场电影。", "explanation": "这里应该用〈见面〉。相比表示比较，不表示见面；“在电影院见面”才对。"}, {"text": "我们在桌边相比，就开始吃饭了。", "explanation": "这里应该用〈相聚〉。相比表示比较，不表示聚在一起；“在桌边相聚”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相比", "is_correct": true, "explanation": "相比：把两个东西放在一起比大小，这里指大海与小河比宽窄。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”是在水中移动的动作，与比较宽窄无关，句子不通。"}, {"text": "流", "is_correct": false, "explanation": "配价：“流”不带“与……”的比较对象，“与小河流”无法构成比较。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是快速移动，不能用来比较大海和小河的宽窄。"}], "explanations": {"相比": "相比：把两个东西放在一起比大小，这里指大海与小河比宽窄。", "游": "语义：“游”是在水中移动的动作，与比较宽窄无关，句子不通。", "流": "配价：“流”不带“与……”的比较对象，“与小河流”无法构成比较。", "跑": "语义：“跑”是快速移动，不能用来比较大海和小河的宽窄。"}, "sentence_index": 6, "correct_answer": "相比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和同学在校门口相比，聊了很久。", "explanation": "这里应该用〈相遇〉。相比表示比大小或优劣，不表示碰见；“在校门口相遇”才对。"}, {"text": "他和朋友相比，成了好朋友。", "explanation": "这里应该用〈相识〉。相比表示比较，不表示认识或交往；“相识后成了好朋友”才对。"}, {"text": "我一直相比老师，就照他说的做了。", "explanation": "这里应该用〈相信〉。相比是互相比较，不表示信任；“相信老师说的话”才对，而“相比老师”缺少比较的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个箱子相比得，哪个重？", "corrected_sentence": "这两个箱子相比，哪个重？", "error_description": "错误形式「相比得」，正确形式「相比」。“得”须接补语，句中没有补语，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河和那条河相比是，哪条宽？", "corrected_sentence": "这条河和那条河相比，哪条宽？", "error_description": "错误形式「相比是」，「相比」后多出的「是」使句子不通，应删去。正确：「这条河和那条河相比，哪条宽？」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
