INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "祖国是我们出生、长大的国家，也是我们爱的国家。", "primary_collocate": null, "pronunciation": "zǔ guó", "ipa": "tsu˨˩˦ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "他在国外住了十年，很想念祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我出生和长大的地方，是我的祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小在中国长大，中国就是她的祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开祖国以后，他每天都给家人打电话。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节的时候，很多人从国外回到祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的祖国有很长的历史。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学完以后，回到祖国工作了。", "target_word": "祖国", "complexity_tier": "T3", "furigana": "zǔ guó", "sentence_source": "generated"}, {"text": "在外国，我常常想起祖国的饭菜。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们唱着歌，说他们爱祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，不管走到哪里，都不能忘了祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祖國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "祖国：自己出生、长大并且热爱的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祖国", "is_correct": true, "explanation": "祖国指自己出生、长大的国家，与“在国外住了十年”的情境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不是可以被“想念”的对象，与语境不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能成为“很想念”的对象。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“想念”一般不与“考试”搭配，语义上也不通。"}], "explanations": {"祖国": "祖国指自己出生、长大的国家，与“在国外住了十年”的情境相符。", "手机": "语义：“手机”不是可以被“想念”的对象，与语境不符。", "桌子": "语义：“桌子”是家具，不能成为“很想念”的对象。", "考试": "搭配：“想念”一般不与“考试”搭配，语义上也不通。"}, "sentence_index": 0, "correct_answer": "祖国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的祖国在山东，村里有很多果树。", "explanation": "这里应该用〈家乡〉。“祖国”指国家，不能说它在某个省份的某个村子。"}, {"text": "我的祖国有一个很大的公园，我常去散步。", "explanation": "这里应该用〈城市〉。“祖国”指国家，不指一座城市；说自己居住的城市，用“城市”。"}, {"text": "他在祖国留学，每天都学习到深夜。", "explanation": "这里应该用〈外国〉。“留学”是在外国学习，“祖国”指自己的国家，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祖国", "is_correct": true, "explanation": "祖国是自己出生、长大的国家，与“回到……工作”的语境相符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”是抽象概念，不能作“回到”的处所。"}, {"text": "故事", "is_correct": false, "explanation": "语义：“故事”不是地点，不能作“回到”的处所。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“星期”是时间单位，不能作“回到……工作”的处所。"}], "explanations": {"祖国": "祖国是自己出生、长大的国家，与“回到……工作”的语境相符。", "时间": "语义：“时间”是抽象概念，不能作“回到”的处所。", "故事": "语义：“故事”不是地点，不能作“回到”的处所。", "星期": "搭配：“星期”是时间单位，不能作“回到……工作”的处所。"}, "sentence_index": 6, "correct_answer": "祖国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我有一只祖国，很想念它。", "explanation": "这里应该用〈个〉。“只”是计量小动物的量词，祖国不能用“只”来计量。"}, {"text": "他有一座祖国，一直很想回去。", "explanation": "这里应该用〈个〉。“座”计量山、房屋等大型固定物，不能计量“祖国”。"}, {"text": "她心里有一本祖国，常常翻看。", "explanation": "这里应该用〈个〉。“本”计量书册，不能计量“祖国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他离开祖国时候还很年轻。", "corrected_sentence": "他离开祖国的时候还很年轻。", "error_description": "错误：“离开祖国”作定语修饰“时候”时，中间要加“的”。正确：“离开祖国的时候”。“的”连接定语“离开祖国”和中心语“时候”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他大学毕业以后，就回到祖国们工作了。", "corrected_sentence": "他大学毕业以后，就回到祖国工作了。", "error_description": "错误：“祖国”后面加了“们”。正确：“回到祖国工作了”。“们”只用于指人或有生命的名词，“祖国”是无生命的名词，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
