INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对本民族和个人出生、成长的国家的称呼。", "primary_collocate": null, "pronunciation": "zǔ guó", "ipa": "tsu˨˩˦ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "祖国的山河非常美丽。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员为祖国拿到了金牌。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一生都献给了祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海外华人心里一直想着祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖国需要我们，我们就回去。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祖国的发展让每个人都很高兴。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她远在国外，却时时关心祖国的消息。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "祝祖国的明天更好！", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们保护着祖国的安全。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家放弃国外的工作，回到祖国。", "target_word": "祖国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "祖國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "祖国：对本民族和个人出生、成长的国家的称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd46e1df1-3bbe-4da7-8679-0f1c42ad4b7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祖国", "is_correct": true, "explanation": "祖国：本民族和个人出生、成长的国家，指国土，可与“山河”搭配。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司是经营机构，没有山河，“公司的山河”不成立。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是教育机构，不是可以描述山河的对象，句子语义不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“山河”指陆地上的山和河，不与“大海”搭配，“大海的山河”不通。"}], "explanations": {"祖国": "祖国：本民族和个人出生、成长的国家，指国土，可与“山河”搭配。", "公司": "语义：公司是经营机构，没有山河，“公司的山河”不成立。", "学校": "语义：学校是教育机构，不是可以描述山河的对象，句子语义不通。", "大海": "搭配：“山河”指陆地上的山和河，不与“大海”搭配，“大海的山河”不通。"}, "sentence_index": 0, "correct_answer": "祖国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的祖国在四川，那里的山水非常美。", "explanation": "这里应该用〈家乡〉。祖国指整个国家，不指某个省份；说自己出生成长的地方，用“家乡”。"}, {"text": "我的祖国有一所很老的小学，我在那里上学。", "explanation": "这里应该用〈故乡〉。祖国指整个国家，不指某一所学校所在的地方；说自己成长的地方，用“故乡”。"}, {"text": "这个房子是我的祖国，我在这里住了十年。", "explanation": "这里应该用〈家〉。祖国指国家，不指房屋；说居住的地方用“家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "祖国", "is_correct": true, "explanation": "祖国：指本民族和个人出生、成长的国家，与“远在国外”形成对照，“关心……的消息”指国家的情况。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是可以“关心消息”的对象，与“远在国外”的语境也不相容。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，没有“消息”可言，句子不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的设备，与“远在国外”的语境不相容，也没有消息可言。"}], "explanations": {"祖国": "祖国：指本民族和个人出生、成长的国家，与“远在国外”形成对照，“关心……的消息”指国家的情况。", "厨房": "语义：厨房是做饭的地方，不是可以“关心消息”的对象，与“远在国外”的语境也不相容。", "椅子": "语义：“椅子”是家具，没有“消息”可言，句子不通。", "黑板": "语义：黑板是教室里的设备，与“远在国外”的语境不相容，也没有消息可言。"}, "sentence_index": 6, "correct_answer": "祖国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的祖国是一个小渔村，我从小就在海边玩。", "explanation": "这里应该用〈故乡〉。祖国指整个国家，不指一个小渔村；说自己成长的小地方，用“故乡”。"}, {"text": "祖国的房子是爷爷留下来的。", "explanation": "这里应该用〈老家〉。祖国是国家，不是可以留给后代的房产；“房子是……留下来的”一般说老家。"}, {"text": "这个山村是他的祖国，他小时候在这里放羊。", "explanation": "这里应该用〈出生地〉。祖国指整个国家，不指一个山村；说出生的具体地方，用“出生地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们只有一座祖国。", "corrected_sentence": "我们只有一个祖国。", "error_description": "错误形式「一座祖国」，正确形式「一个祖国」。量词「座」用于山、桥、楼等大型固定的事物，“祖国”应用通用量词「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直守卫祖国着。", "corrected_sentence": "他们一直守卫祖国。", "error_description": "错误：“着”放在宾语“祖国”之后。正确：“着”应紧跟动词，可说“他们一直守卫着祖国”；此句直接删去“着”也成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc5b696f-3a32-4f94-b807-c6aecf206c31') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
