INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点按是用手指轻轻碰一下屏幕或按钮。", "primary_collocate": null, "pronunciation": "diǎn àn", "ipa": "tjɛn˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "请点按屏幕上的绿色按钮。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他点按了一下手机图标。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点按这里，就可以打开照片。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子好奇地到处点按平板电脑。", "target_word": "点按", "complexity_tier": "T3", "furigana": "hái zi hào qí de dào chù diǎn àn píng bǎn diàn nǎo", "sentence_source": "generated"}, {"text": "先点按“设置”，再选择语言。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不会点按，我教了他。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你点按一下，页面就会变大。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻点按相机里的小红点。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请点按右上角的图标。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我点按了好几次，手机没有反应。", "target_word": "点按", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点按了", "label": "完成体"}, {"form": "点按着", "label": "持续体"}, {"form": "点按过", "label": "经历体"}], "register": "口语", "sense_fingerprint": "用手指轻碰一下屏幕或按钮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点按", "is_correct": true, "explanation": "点按：用手指轻碰屏幕按钮，与“请……绿色按钮”的操作相符。"}, {"text": "拆卸", "is_correct": false, "explanation": "语义：拆卸是把整体拆开，屏幕上的按钮是固定的，不能拆下来。"}, {"text": "粘贴", "is_correct": false, "explanation": "语义：粘贴是把东西贴到别处，与用手指按下屏幕按钮的操作不符。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤是用火加热食物，不能用于屏幕上的按钮。"}], "explanations": {"点按": "点按：用手指轻碰屏幕按钮，与“请……绿色按钮”的操作相符。", "拆卸": "语义：拆卸是把整体拆开，屏幕上的按钮是固定的，不能拆下来。", "粘贴": "语义：粘贴是把东西贴到别处，与用手指按下屏幕按钮的操作不符。", "烘烤": "语义：烘烤是用火加热食物，不能用于屏幕上的按钮。"}, "sentence_index": 0, "correct_answer": "点按"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他点按了一下那只旧皮箱，然后把它拎走了。", "explanation": "这里应该用〈拎〉。拎皮箱是用手提着走，点按只用于屏幕或按键，不能用于皮箱。"}, {"text": "她点按了一下墙上的画，想把它扶正。", "explanation": "这里应该用〈扶〉。扶正是用手使物体恢复直立，点按只用于屏幕或按键，不能用于墙上的画。"}, {"text": "他点按了一下大树，想把树上的果子摇下来。", "explanation": "这里应该用〈摇〉。摇树是晃动树身使果子落下，点按只用于屏幕或按键，不能用于大树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点按", "is_correct": true, "explanation": "点按：轻碰一下屏幕，页面才会放大，与句意相符。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：擦拭是擦干净，与页面变大无关。"}, {"text": "撕扯", "is_correct": false, "explanation": "语义：撕扯会损坏屏幕，无法让页面变大。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”要搬动实物，“页面”不能被搬运。"}], "explanations": {"点按": "点按：轻碰一下屏幕，页面才会放大，与句意相符。", "擦拭": "语义：擦拭是擦干净，与页面变大无关。", "撕扯": "语义：撕扯会损坏屏幕，无法让页面变大。", "搬运": "搭配：“搬运”要搬动实物，“页面”不能被搬运。"}, "sentence_index": 6, "correct_answer": "点按"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的手指在屏幕上向上点按了一下，列表就滚动起来。", "explanation": "这里应该用〈划〉。列表滚动要手指在屏幕上滑动，点按只是轻碰一下，不会让列表滚动。"}, {"text": "她把那只杯子点按在桌上，杯子就倒了。", "explanation": "这里应该用〈放〉。放杯子是把杯子搁下，点按只用于屏幕或按钮，不能用于杯子。"}, {"text": "足球被他点按进了球门。", "explanation": "这里应该用〈踢〉。足球要靠脚踢进球门，点按只用于手指按屏幕或按键。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈正在点按了屏幕，给我看照片。", "corrected_sentence": "妈妈正在点按屏幕，给我看照片。", "error_description": "错误：“点按”后多了“了”。“正在”表示动作进行中，不能与表示完成的“了”同用，应为“正在点按屏幕”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他点按很快，一下子就打开了应用。", "corrected_sentence": "他点按得很快，一下子就打开了应用。", "error_description": "错误：“点按”后表示程度的补语要用“得”连接，缺少“得”。应为“点按得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
