INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90386, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "希望将来能实现的想法。", "primary_collocate": null, "pronunciation": "yuàn wàng", "ipa": "ɥɛn˥˩ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的愿望是将来当一名医生。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日时，她许了一个愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候的愿望是去北京看看。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都祝他的愿望早日实现。", "target_word": "愿望", "complexity_tier": "T3", "furigana": "wǒ men dōu zhù tā de yuàn wàng zǎo rì shí xiàn", "sentence_source": "generated"}, {"text": "妈妈的愿望是孩子健康长大。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，大家都写下了自己的愿望。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个愿望，想环游世界。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的愿望终于实现了。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你长大后的愿望是什么？", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷最大的愿望是回老家看看。", "target_word": "愿望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "愿望清单", "label": "复合"}, {"form": "願望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "愿望：对将来抱有的、希望能够实现的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e791c86-9557-46be-af3d-f72d116cd67f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指对过去的追想，与“将来当一名医生”矛盾。"}, {"text": "愿望", "is_correct": true, "explanation": "正确：“愿望”指对将来的希望，与“将来当一名医生”相合。"}, {"text": "作文", "is_correct": false, "explanation": "语义：“作文”是写成的文章，不能说“我的作文是将来当一名医生”。"}, {"text": "经历", "is_correct": false, "explanation": "语义：“经历”指已经发生过的事，与“将来”矛盾。"}], "explanations": {"回忆": "语义：“回忆”指对过去的追想，与“将来当一名医生”矛盾。", "愿望": "正确：“愿望”指对将来的希望，与“将来当一名医生”相合。", "作文": "语义：“作文”是写成的文章，不能说“我的作文是将来当一名医生”。", "经历": "语义：“经历”指已经发生过的事，与“将来”矛盾。"}, "sentence_index": 0, "correct_answer": "愿望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人的情况很糟，家里人只剩一线愿望。", "explanation": "这里应该用〈希望〉。“一线希望”是固定说法，“愿望”不能受“一线”修饰。"}, {"text": "他认真填报了高考愿望。", "explanation": "这里应该用〈志愿〉。“填报志愿”指报考学校或专业，“愿望”不能用“填报”。"}, {"text": "他把愿望存进了银行。", "explanation": "这里应该用〈钱〉。“存”的对象是钱等财物，“愿望”不能存入银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任务", "is_correct": false, "explanation": "搭配：“任务”是分派的工作，与表示个人心愿的“想环游世界”搭配不当。"}, {"text": "愿望", "is_correct": true, "explanation": "正确：“愿望”指心里想实现的事，与“想环游世界”相合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间不能产生想环游世界的心愿，与“想”的主体不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验，与“想环游世界”的心愿毫不相关。"}], "explanations": {"任务": "搭配：“任务”是分派的工作，与表示个人心愿的“想环游世界”搭配不当。", "愿望": "正确：“愿望”指心里想实现的事，与“想环游世界”相合。", "房间": "语义：房间不能产生想环游世界的心愿，与“想”的主体不合。", "考试": "语义：“考试”是测验，与“想环游世界”的心愿毫不相关。"}, "sentence_index": 6, "correct_answer": "愿望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校制定了新的教学愿望。", "explanation": "这里应该用〈计划〉。“制定”用于计划、方案等有条理的安排，“愿望”不能被制定。"}, {"text": "她做出了一个艰难的愿望。", "explanation": "这里应该用〈决定〉。“做出决定”是常用搭配，“愿望”不能说“做出”。"}, {"text": "他一口气把愿望吃光了。", "explanation": "这里应该用〈饭〉。“吃”的对象应是食物，“愿望”不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他长大以后有一条愿望，想开一家书店。", "corrected_sentence": "他长大以后有一个愿望，想开一家书店。", "error_description": "量词错误：“愿望”前应用量词“个”，不能用“条”（“条”指细长的东西）。正确说法是“一个愿望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人临终前只有一个愿望的，就是再见儿子一面。", "corrected_sentence": "老人临终前只有一个愿望，就是再见儿子一面。", "error_description": "结构助词误用：“一个愿望”后不应加“的”，后面直接接“就是……”。正确说法是“只有一个愿望”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b454fe6d-899c-45af-ba14-3a0dc46e097a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
