INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "较大的旅馆，可以住宿的地方。", "primary_collocate": null, "pronunciation": "fàn diàn", "ipa": "fan˥˩ tiɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们住的饭店在海边。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有两百个房间。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在饭店订了一个房间。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出差时，公司帮我订了饭店。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店的房间很干净，还能看到海。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人住在这家饭店的十楼。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家五星级饭店的房间很贵。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国客人明天到，请先订好饭店。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在饭店住了三天。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店离火车站很近，坐车很方便。", "target_word": "饭店", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "飯店", "label": "繁体"}], "register": "口语", "sense_fingerprint": "较大的旅馆，可以住宿的饭店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是可以住宿的旅馆，“我们住的……在海边”符合语境。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不能住宿，不能说“住的图书馆”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能住宿。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“住的”后接住宿场所，“公园”不搭配。"}], "explanations": {"饭店": "“饭店”是可以住宿的旅馆，“我们住的……在海边”符合语境。", "图书馆": "语义：图书馆不能住宿，不能说“住的图书馆”。", "教室": "语义：教室是上课的地方，不能住宿。", "公园": "搭配：“住的”后接住宿场所，“公园”不搭配。"}, "sentence_index": 0, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在饭店坐飞机去海边。", "explanation": "这里应该用〈机场〉。坐飞机要去机场；饭店是住宿的旅馆，不是乘机的地方。"}, {"text": "我明天去饭店参加考试。", "explanation": "这里应该用〈考场〉。参加考试要去考场；饭店是住宿或餐饮的场所，不是考试的地方。"}, {"text": "大学生住在饭店里，学校每月收费很低。", "explanation": "这里应该用〈宿舍〉。学校安排的住处称“宿舍”，饭店是对外营业的旅馆，不是学校的住处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭店", "is_correct": true, "explanation": "“饭店”是可以住宿的旅馆，“五星级”也是旅馆的评级，符合语境。"}, {"text": "文具店", "is_correct": false, "explanation": "语义：文具店卖文具，没有可出租的房间，“房间很贵”不合。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市不出租房间，不能说房间很贵。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：“五星级”是旅馆的评级，不用于书店。"}], "explanations": {"饭店": "“饭店”是可以住宿的旅馆，“五星级”也是旅馆的评级，符合语境。", "文具店": "语义：文具店卖文具，没有可出租的房间，“房间很贵”不合。", "超市": "语义：超市不出租房间，不能说房间很贵。", "书店": "搭配：“五星级”是旅馆的评级，不用于书店。"}, "sentence_index": 6, "correct_answer": "饭店"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生在饭店给病人看病。", "explanation": "这里应该用〈医院〉。给病人看病要在医院；饭店是住宿的旅馆，不是看病的地方。"}, {"text": "我去饭店剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店；饭店不是理发的地方。"}, {"text": "她穿着饭店出门。", "explanation": "这里应该用〈衣服〉。“穿”的是衣服；饭店是店铺，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在海边订了一只饭店。", "corrected_sentence": "我们在海边订了一家饭店。", "error_description": "量词错误：“饭店”用“家”计量，说“一家饭店”，不说“一只饭店”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一份饭店住了两天。", "corrected_sentence": "我们在一家饭店住了两天。", "error_description": "量词错误：“饭店”用“家”计量，说“一家饭店”，不说“一份饭店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
